export const ArtisanDataProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    // Initializing state with persistence check
    const [inventory, setInventory] = useState<InventoryItem[]>(() => {
        const saved = localStorage.getItem('artisan_inventory');
        return saved ? JSON.parse(saved) : INITIAL_INVENTORY;
    });

    const [orders, setOrders] = useState<Order[]>(() => {
        const saved = localStorage.getItem('artisan_orders');
        return saved ? JSON.parse(saved) : INITIAL_ORDERS;
    });

    const [suppliers, setSuppliers] = useState<Supplier[]>(INITIAL_SUPPLIERS);
    const [recipes, setRecipes] = useState<Recipe[]>(INITIAL_RECIPES);
    const [qualityChecks, setQualityChecks] = useState<QualityCheck[]>(INITIAL_QUALITY_CHECKS);
    const [supplierCommunications, setSupplierCommunications] = useState<SupplierCommunication[]>(INITIAL_COMMUNICATIONS);
    const [locations, setLocations] = useState<Location[]>(INITIAL_LOCATIONS);
    const [productionStats, setProductionStats] = useState({ active: 0, inProgress: 0, awaiting: 0, completed: 0, pending: 5 });
    const [reports, setReports] = useState<Report[]>(INITIAL_REPORTS);
    const [marketingPosts, setMarketingPosts] = useState<MarketingPost[]>(INITIAL_MARKETING_POSTS);
    const [appointments, setAppointments] = useState<Appointment[]>(INITIAL_APPOINTMENTS);

    const [businessProfile, setBusinessProfile] = useState<BusinessProfile>(() => {
        const saved = localStorage.getItem('artisan_business_profile');
        return saved ? JSON.parse(saved) : INITIAL_BUSINESS_PROFILE;
    });

    const [integrations, setIntegrations] = useState<Integration[]>(() => {
        const saved = localStorage.getItem('artisan_integrations');
        return saved ? JSON.parse(saved) : INITIAL_INTEGRATIONS;
    });

    // Effect for persisting critical state
    useEffect(() => {
        localStorage.setItem('artisan_inventory', JSON.stringify(inventory));
    }, [inventory]);

    useEffect(() => {
        localStorage.setItem('artisan_orders', JSON.stringify(orders));
    }, [orders]);

    // --- Actions ---

    const updateInventory = (id: string | number, updates: Partial<InventoryItem>) => {
        setInventory(prev => prev.map(item => item.id === id ? { ...item, ...updates } : item));
    };

    const addInventoryItem = (item: Omit<InventoryItem, 'id' | 'stockValue'>) => {
        const newItem: InventoryItem = {
            ...item,
            id: Date.now(),
            stockValue: item.stock * item.unitCost,
            lastUpdated: new Date().toLocaleDateString()
        };
        setInventory(prev => [...prev, newItem]);
    };

    const processOrder = (orderId: string) => {
        const orderIndex = orders.findIndex(o => o.id === orderId);
        if (orderIndex === -1) return;

        const order = orders[orderIndex];
        const updatedOrders = [...orders];
        updatedOrders[orderIndex] = { ...order, status: 'Shipped' };
        setOrders(updatedOrders);

        const updatedInventory = [...inventory];
        order.items.forEach(orderItem => {
            const invItem = updatedInventory.find(i => i.name.includes(orderItem.name) || orderItem.name.includes(i.name));
            if (invItem) {
                invItem.stock = Math.max(0, invItem.stock - orderItem.qty);
                invItem.stockValue = invItem.stock * invItem.unitCost;
                if (invItem.stock <= invItem.reorderPoint) invItem.lowStock = true;
            }
        });
        setInventory(updatedInventory);
    };

    const importData = (type: 'inventory' | 'orders' | 'suppliers', data: any[]) => {
        if (type === 'inventory') {
            setInventory(prev => [...prev, ...data as InventoryItem[]]);
        }
    };

    const addSupplier = (supplier: Omit<Supplier, 'id'>) => {
        const newSupplier = { ...supplier, id: Date.now().toString() };
        setSuppliers(prev => [...prev, newSupplier]);
    };

    const addLocation = (location: Omit<Location, 'id'>) => {
        const newLocation = { ...location, id: Date.now().toString() };
        setLocations(prev => [...prev, newLocation]);
    };

    const addQualityCheck = (check: Omit<QualityCheck, 'id'>) => {
        const newCheck = { ...check, id: Date.now().toString() };
        setQualityChecks(prev => [newCheck, ...prev]);
    };

    const addCommunication = (comm: Omit<SupplierCommunication, 'id'>) => {
        const newComm = { ...comm, id: Date.now().toString() };
        setSupplierCommunications(prev => [newComm, ...prev]);
    };

    const generateSchedule = () => {
        if (productionStats.pending > 0) {
            setProductionStats({ active: 2, inProgress: 3, awaiting: 1, completed: 1, pending: 0 });
        }
    };

    const saveReport = (report: Omit<Report, 'id'>) => {
        const newReport = { ...report, id: Date.now().toString() };
        setReports(prev => [newReport, ...prev]);
    };

    const deleteReport = (id: string) => {
        setReports(prev => prev.filter(r => r.id !== id));
    };

    const addMarketingPost = (post: Omit<MarketingPost, 'id'>) => {
        const newPost = { ...post, id: Date.now().toString() };
        setMarketingPosts(prev => [newPost, ...prev]);
    };

    const updateMarketingPost = (id: string, updates: Partial<MarketingPost>) => {
        setMarketingPosts(prev => prev.map(post => post.id === id ? { ...post, ...updates } : post));
    };

    const updateBusinessProfile = (updates: Partial<BusinessProfile>) => {
        setBusinessProfile(prev => {
            const updated = { ...prev, ...updates };
            localStorage.setItem('artisan_business_profile', JSON.stringify(updated));
            return updated;
        });
    };

    const toggleIntegration = (id: string, status: 'Connected' | 'Connect' | 'Reconfigure', config?: any) => {
        setIntegrations(prev => {
            const updated = prev.map(int => 
                int.id === id ? { 
                  ...int, 
                  status, 
                  config: config ? { ...int.config, ...config } : int.config,
                  lastSync: status === 'Connected' ? new Date().toLocaleDateString() : undefined 
                } : int
            );
            localStorage.setItem('artisan_integrations', JSON.stringify(updated));
            return updated;
        });
    };

    const addAppointment = (apt: Omit<Appointment, 'id'>) => {
        const newApt = { ...apt, id: Date.now().toString() };
        setAppointments(prev => [...prev, newApt]);
    };

    // --- WooCommerce Sync Engine (High Fidelity Simulation) ---
    const syncWooCommerce = async (): Promise<{ success: boolean; error?: 'Unauthorized' | 'NotFound' | 'General'; count?: number }> => {
      const wooInt = integrations.find(i => i.name === 'WooCommerce');
      if (!wooInt || wooInt.status !== 'Connected') {
        return { success: false, error: 'Unauthorized' };
      }

      const { consumerKey, consumerSecret, storeUrl } = wooInt.config || {};

      // Connection Protocol Checks
      if (!storeUrl || !storeUrl.startsWith('http')) return { success: false, error: 'NotFound' };
      if (!consumerKey || !consumerSecret) return { success: false, error: 'Unauthorized' };

      // Intentional Error Injection for Demo Testing
      if (consumerKey === 'error') return { success: false, error: 'Unauthorized' };

      try {
        // Step 1: Handshake with WooCommerce API (Mocked 2s latency)
        console.log(`[Sync] Handshaking with ${storeUrl}...`);
        await new Promise(resolve => setTimeout(resolve, 2000));

        // Step 2: Fetch Orders (/wp-json/wc/v3/orders?status=processing)
        // We generate dynamic mock data that cross-references our actual inventory
        const availableFinishedProducts = inventory.filter(i => i.type === 'finished' && i.stock > 0);

        if (availableFinishedProducts.length === 0) {
           return { success: true, count: 0 }; // No new orders possible or synced
        }

        const mockNewOrders: Order[] = [
          {
            id: `#WC-${Math.floor(Math.random() * 9000) + 10000}`,
            customer: ['Jane Doe', 'John Smith', 'Alice Cooper', 'Bob Marley'][Math.floor(Math.random() * 4)],
            email: 'customer@woo.com',
            date: new Date().toLocaleDateString(),
            status: 'Processing',
            platform: 'WooCommerce',
            total: 0, // Calculated below
            location: 'Online Store',
            items: []
          }
        ];

        // Randomly pick 1-2 items from our real inventory
        const numItems = Math.floor(Math.random() * 2) + 1;
        for(let i=0; i<numItems; i++) {
            const product = availableFinishedProducts[Math.floor(Math.random() * availableFinishedProducts.length)];
            const qty = Math.floor(Math.random() * 3) + 1;
            mockNewOrders[0].items.push({
                name: product.name,
                qty: qty,
                price: product.retailPrice || 10.00
            });
            mockNewOrders[0].total += (product.retailPrice || 10.00) * qty;
        }

        // Step 3: Deduplicate and Update State
        setOrders(prev => {
          const combined = [...mockNewOrders, ...prev];
          const unique = combined.filter((v, i, a) => a.findIndex(t => t.id === v.id) === i);
          return unique;
        });

        // Step 4: Map Inventory Updates (Reduce stock for finished products in the order)
        setInventory(prev => {
          const updated = [...prev];
          mockNewOrders.forEach(order => {
            order.items.forEach(orderItem => {
              const itemIdx = updated.findIndex(i => i.name === orderItem.name);
              if (itemIdx !== -1) {
                updated[itemIdx].stock = Math.max(0, updated[itemIdx].stock - orderItem.qty);
                updated[itemIdx].stockValue = updated[itemIdx].stock * updated[itemIdx].unitCost;
                if (updated[itemIdx].stock <= updated[itemIdx].reorderPoint) {
                    updated[itemIdx].lowStock = true;
                }
              }
            });
          });
          return updated;
        });

        // Step 5: Finalize Sync Transaction
        toggleIntegration(wooInt.id, 'Connected'); // Update lastSync timestamp
        console.log(`[Sync] WooCommerce Sync Complete: ${mockNewOrders.length} orders imported.`);
        return { success: true, count: mockNewOrders.length };
      } catch (e) {
        console.error("[Sync] WooCommerce Sync Failed:", e);
        return { success: false, error: 'General' };
      }
    };

    const getInventoryValue = () => inventory.reduce((acc, item) => acc + item.stockValue, 0);
    const getTotalRevenue = () => orders.reduce((acc, order) => acc + order.total, 0);

    return (
        <DataContext.Provider value={{ 
            inventory, orders, suppliers, recipes, productionStats,
            qualityChecks, supplierCommunications, locations, reports, marketingPosts, businessProfile, integrations, appointments,
            updateInventory, addInventoryItem, processOrder, importData, 
            addSupplier, addLocation, addQualityCheck, addCommunication, 
            generateSchedule, saveReport, deleteReport, addMarketingPost, updateMarketingPost, updateBusinessProfile,
            toggleIntegration, addAppointment, syncWooCommerce,
            getInventoryValue, getTotalRevenue 
        }}>
            {children}
        </DataContext.Provider>
    );
};

export const useArtisanData = () => {
    const context = useContext(DataContext);
    if (!context) throw new Error('useArtisanData must be used within ArtisanDataProvider');
    return context;
};

