  reorderPoint: number;
  type: 'raw' | 'finished';
  category?: string;
  img?: string;
  lowStock?: boolean;
  description?: string;
  dimensions?: string;
  supplier?: string;
  lastUpdated?: string;
}

export interface OrderItem {
  name: string;
  qty: number;
  price: number;
}

export interface Order {
  id: string;
  customer: string;
  email?: string;
  date: string;
  status: 'Processing' | 'Shipped' | 'Delivered' | 'Cancelled';
  platform: 'WooCommerce' | 'Shopify' | 'Etsy' | 'Square';
  items: OrderItem[];
  total: number;
  location: string;
}

export interface Supplier {
    id: string;
    name: string;
    contactName: string;
    email: string;
    phone: string;
    rating: number;
    tier: 'Reliable' | 'Moderate' | 'Risk';
    pricePerUnit: number;
    leadTime: number; // days
    paymentTerms: string;
    discount?: string; // e.g., "5% off orders > 500"
    notes?: string;
}

export interface Recipe {
    id: string;
    name: string;
    sku: string;
    version: string;
    yield: number;
    materialCost: number;
    totalCost: number;
    productionTime: number; // minutes
    ingredients: { name: string; qty: string }[];
}

export interface QualityCheck {
    id: string;
    batchNumber: string;
    productName: string;
    date: string;
    status: 'Passed' | 'Failed' | 'Pending';
    inspector: string;
    notes: string;
}

export interface SupplierCommunication {
    id: string;
    supplierId: string;
    supplierName: string;
    subject: string;
    date: string;
    status: 'Pending' | 'Sent' | 'Responded' | 'Resolved';
    type: 'Email' | 'Phone' | 'Portal';
}

export interface Location {
    id: string;
    name: string;
    type: 'Warehouse' | 'Retail' | 'Storage';
    address: string;
    capacity: string;
}

export interface Report {
    id: string;
    title: string;
    category: string;
    type: string;
    generatedDate: string;
