    type: 'Consultation' | 'Strategy' | 'Support';
    status: 'Confirmed' | 'Pending';
}

export interface BusinessProfile {
    name: string;
    ownerName: string;
    email: string;
    phone: string;
    address: string;
    website: string;
    logo?: string;
    industry: string;
    goals?: string;
