export const Integrations = () => {
    const { integrations, toggleIntegration } = useArtisanData();
    const [selectedIntegration, setSelectedIntegration] = useState<Integration | null>(null);
    const [isConnecting, setIsConnecting] = useState(false);
    const [connError, setConnError] = useState<string | null>(null);
    const [connSuccess, setConnSuccess] = useState<boolean>(false);

    const [wooConfig, setWooConfig] = useState({
      consumerKey: '',
      consumerSecret: '',
      storeUrl: ''
    });

    const handleConnect = (int: Integration) => {
        setSelectedIntegration(int);
        setIsConnecting(false);
        setConnError(null);
        setConnSuccess(false);

        if (int.name === 'WooCommerce' && int.config) {
          setWooConfig({
            consumerKey: int.config.consumerKey || '',
            consumerSecret: int.config.consumerSecret || '',
            storeUrl: int.config.storeUrl || ''
          });
        } else {
           setWooConfig({ consumerKey: '', consumerSecret: '', storeUrl: '' });
        }
    };

    const submitConnection = async () => {
        setIsConnecting(true);
        setConnError(null);

        // Simulation of API verification (wp-json/wc/v3/orders)
        await new Promise(resolve => setTimeout(resolve, 1500));

        if (selectedIntegration?.name === 'WooCommerce') {
          if (!wooConfig.storeUrl.includes('http')) {
            setConnError('Invalid Store URL. Ensure it starts with http:// or https://');
            setIsConnecting(false);
            return;
          }
          if (wooConfig.consumerKey.length < 5) {
            setConnError('Unauthorized: Consumer Key is invalid or malformed.');
            setIsConnecting(false);
            return;
          }
        }

        if (selectedIntegration) {
            toggleIntegration(selectedIntegration.id, 'Connected', wooConfig);
            setConnSuccess(true);
            setTimeout(() => {
                setSelectedIntegration(null);
                setConnSuccess(false);
            }, 1000);
        }
        setIsConnecting(false);
    };

    return (
        <div className="p-6 space-y-8 animate-in fade-in pb-20">
            <Modal isOpen={!!selectedIntegration} onClose={() => setSelectedIntegration(null)} title={`Configure ${selectedIntegration?.name}`}>
                <div className="space-y-6">
                    <div className="flex items-center justify-center p-6 bg-stone-50 rounded-xl">
                        <img src={selectedIntegration?.logo} className="h-12 object-contain grayscale hover:grayscale-0 transition-all" />
                    </div>

                    <div className="space-y-4">
                        <div className="flex items-center gap-2 text-xs font-bold text-gray-500 uppercase tracking-widest">
                            <Key size={14} /> Security Protocol: API Key V3
                        </div>

                        {selectedIntegration?.name === 'WooCommerce' ? (
                          <div className="space-y-4">
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-2">Store Endpoint</label>
                                <Input 
                                    placeholder="https://yourstore.com" 
                                    value={wooConfig.storeUrl}
                                    onChange={e => setWooConfig({...wooConfig, storeUrl: e.target.value})}
                                />
                                <p className="text-[10px] text-gray-400 mt-1">Found in your WordPress settings.</p>
                            </div>
                            <div className="grid grid-cols-1 gap-4">
                                <div>
                                    <label className="block text-xs font-bold text-gray-500 uppercase mb-2">Consumer Key</label>
                                    <Input 
                                        placeholder="ck_xxxxxxxxxxxxxxxxxxxxxxxx" 
                                        value={wooConfig.consumerKey}
                                        onChange={e => setWooConfig({...wooConfig, consumerKey: e.target.value})}
                                    />
                                </div>
                                <div>
                                    <label className="block text-xs font-bold text-gray-500 uppercase mb-2">Consumer Secret</label>
                                    <Input 
                                        type="password" 
                                        placeholder="cs_xxxxxxxxxxxxxxxxxxxxxxxx" 
                                        value={wooConfig.consumerSecret}
                                        onChange={e => setWooConfig({...wooConfig, consumerSecret: e.target.value})}
                                    />
                                </div>
                            </div>
                          </div>
                        ) : (
                            <div className="py-10 text-center text-gray-400">
                                <AlertTriangle size={32} className="mx-auto mb-2 opacity-50" />
                                <p className="text-sm">Integration module for {selectedIntegration?.name} is in restricted beta.</p>
                            </div>
                        )}
                    </div>

                    {connError && (
                      <div className="p-3 bg-red-50 border border-red-200 rounded-lg flex items-center gap-2 text-red-700 text-[10px] font-black uppercase tracking-tight animate-in shake">
                        <AlertTriangle size={14} />
                        {connError}
                      </div>
                    )}

                    {connSuccess ? (
                        <div className="p-4 bg-emerald-50 text-emerald-700 border border-emerald-200 rounded-xl flex items-center justify-center gap-2 font-bold animate-in zoom-in">
                            <Check size={20} /> Connection Secured
                        </div>
                    ) : (
                        <div className="flex flex-col gap-2">
                            <Button 
                                className="w-full bg-[#6A2C91] text-white py-4 font-black tracking-widest text-xs uppercase" 
                                onClick={submitConnection} 
                                disabled={isConnecting || !selectedIntegration?.name.includes('WooCommerce')}
                            >
