                                <><div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin mr-2"></div> VERIFYING ENDPOINT...</>
                                ) : 'SAVE & SECURE CONNECTION'}
                            </Button>
                            <a href="https://woocommerce.com/document/woocommerce-rest-api/" target="_blank" rel="noopener noreferrer" className="text-[10px] text-center text-gray-400 hover:text-[#6A2C91] transition-colors flex items-center justify-center gap-1">
                                <ExternalLink size={10} /> Documentation: Generating API Keys
                            </a>
                        </div>
                    )}
                </div>
            </Modal>

            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-3xl font-bold text-gray-900">Integrations Ecosystem</h1>
                    <p className="text-gray-500">Connect your commerce platforms and social channels.</p>
                </div>
                <div className="flex gap-2">
                    <Badge color="purple">API Status: Healthy</Badge>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {integrations.map(int => (
                    <div key={int.id} className="bg-white border border-gray-200 rounded-xl p-6 shadow-sm hover:shadow-lg transition-all flex flex-col group relative">
