                                <img src={int.logo} alt={int.name} className="max-h-8 max-w-full object-contain" />
                            </div>
                            <div>
                                <h4 className="font-bold text-gray-900 group-hover:text-[#6A2C91] transition-colors">{int.name}</h4>
                                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">{int.category}</p>
                            </div>
                        </div>
                        <p className="text-xs text-gray-500 leading-relaxed flex-1 mb-6">{int.description}</p>

                        <div className="flex flex-col gap-3">
                            <div className="flex justify-between items-center px-1">
                                <Badge color={int.status === 'Connected' ? 'green' : 'gray'} className="text-[9px] font-black uppercase tracking-widest px-2">
                                    {int.status}
                                </Badge>
                                {int.lastSync && <span className="text-[9px] text-gray-400 font-bold uppercase tracking-tight">Synced: {int.lastSync}</span>}
                            </div>
                            <Button 
                                className={`w-full text-xs font-black tracking-widest uppercase transition-all ${
                                    int.status === 'Connected' 
                                    ? 'bg-stone-50 text-gray-600 hover:bg-stone-100 border border-stone-200' 
                                    : 'bg-[#6A2C91] text-white shadow-md hover:shadow-xl'
                                }`} 
                                onClick={() => handleConnect(int)}
                            >
                              {int.status === 'Connected' ? 'Manage Connection' : 'Establish Link'}
                            </Button>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

