import { GoogleGenAI } from "@google/genai";
import { InventoryItem } from "../types";

// Initialize the Google GenAI client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Main chat interaction with Lola AI assistant.
 * Now accepts manufacturing context to provide inventory-aware answers.
 */
export const chatWithLola = async (message: string, context?: any) => { 
  try {
    const systemPrompt = `
      You are Lola, a world-class Systems Architect for artisan businesses. 
      You have access to the real-time Artisan Flow manufacturing database.

      CURRENT BUSINESS CONTEXT:
      ${JSON.stringify(context || {}, null, 2)}

      GUIDELINES:
      1. INVENTORY: If asked about stock, units, or SKUs, check the 'inventory' array in the context. Be precise.
      2. PRODUCTION: If asked about batches or status, check 'productionStats'.
      3. WHOLESALE LEADS: If a user expresses interest in wholesale:
         - Check if 'isMarginHealthy' is true.
         - Check if 'totalFinishedUnits' > 50.
         - If BOTH are true, offer to schedule a 'Wholesale Strategy Call'.
         - If EITHER is false, explain that we need to optimize their production efficiency first and suggest a 'Manufacturing Audit'.
      4. BRAND: Professional, authoritative, yet supportive. Use the brand color #6A2C91 mentally as your vibe.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: message,
      config: {
        systemInstruction: systemPrompt,
      },
    });

    return { 
      text: response.text || "I'm processing your request but having trouble finding the right data. Could you rephrase?", 
      isError: false 
    }; 
  } catch (error) {
    console.error("Lola AI Error:", error);
    return {
      text: "I encountered an error connecting to the manufacturing core. Please check your network.",
      isError: true
    };
  }
};

/**
 * Generates a marketing strategy based on provided data.
 */
export const generateMarketingStrategy = async (data: any, tier?: string) => { 
  try {
    const prompt = `Analyze this business pulse data and generate a marketing strategy. Tier: ${tier || 'Standard'}. Data: ${JSON.stringify(data)}`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: "You are a senior marketing strategist specializing in artisan brands. Provide actionable, creative, and data-driven strategy points.",
      },
    });

    const lines = response.text?.split('\n').filter(l => l.trim().length > 5) || [];

    return {
      strategy: lines.length > 0 ? lines : [
        "Focus on high-margin product bundling.",
        "Leverage customer testimonials for high-AOV items.",
        "Implement a 'behind-the-scenes' content series to build trust."
      ]
    };
  } catch (error) {
    console.error("Marketing Gen Error:", error);
    return {
      strategy: [
        "Focus on customer retention and high-margin products.",
        "The AI generator is currently experiencing heavy load."
      ]
    };
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { MessageSquare, Send, Minimize2, Sparkles, Calendar, Factory, Database, ShieldCheck } from 'lucide-react';
import { useArtisanData } from './DataContext';
import { chatWithLola } from '../services/geminiService';

type Msg = { 
  role: 'user' | 'assistant', 
  text: string, 
  isSlotSelector?: boolean,
  isAuditPrompt?: boolean,
  isDataInsight?: boolean
};

export const AIAssistant: React.FC = () => { 
  const { businessProfile, addAppointment, inventory, productionStats, getTotalRevenue } = useArtisanData();
  const [isOpen, setIsOpen] = useState(false); 
  const [messages, setMessages] = useState<Msg[]>([ 
    { role: 'assistant', text: `Greetings! I am Lola. I've successfully synchronized with your manufacturing floor. How can I help you optimize your flow today?` } 
  ]); 
  const [input, setInput] = useState(''); 
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // --- Manufacturing Logic Engine ---
  const finishedGoodsUnits = inventory
    .filter(item => item.type === 'finished')
    .reduce((sum, item) => sum + item.stock, 0);

  // Calculate 2.2x Margin Health across inventory
  const totalCost = inventory.reduce((sum, i) => sum + (i.unitCost * i.stock), 0);
  const totalRetail = inventory.reduce((sum, i) => sum + ((i.retailPrice || 0) * i.stock), 0);
  const isMarginHealthy = totalCost > 0 ? (totalRetail / totalCost) >= 2.2 : true;

  const manufacturingContext = {
    inventory: inventory.map(i => ({ name: i.name, stock: i.stock, unit: i.unit, sku: i.sku, type: i.type })),
    productionStats,
    totalFinishedUnits: finishedGoodsUnits,
    isMarginHealthy,
    currentRevenue: getTotalRevenue(),
    marginMultiplier: totalCost > 0 ? (totalRetail / totalCost).toFixed(2) : "0",
    ownerName: businessProfile.ownerName
  };

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  const handleSend = async () => { 
    if (!input.trim()) return;

    const userMsg = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsLoading(true);

    try {
        // Send message to Gemini with injected manufacturing state
        const response = await chatWithLola(userMsg, manufacturingContext);

        const assistantMsg: Msg = { 
            role: 'assistant', 
            text: response.text 
        };

        // Detect if AI wants to show slots or audit based on lead keywords
        // (Lola will return text suggesting these based on system instructions)
        if (userMsg.toLowerCase().includes('wholesale') || userMsg.toLowerCase().includes('strategy')) {
            if (!isMarginHealthy || finishedGoodsUnits < 50) {
                assistantMsg.isAuditPrompt = true;
            } else {
                assistantMsg.isSlotSelector = true;
            }
        }

        setMessages(prev => [...prev, assistantMsg]);
    } catch (error) {
        setMessages(prev => [...prev, { role: 'assistant', text: "Connectivity interrupted. Re-syncing with manufacturing floor..." }]);
    } finally {
        setIsLoading(false);
    }
  };

  const handleSelectSlot = (time: string, type: string = 'Wholesale Strategy') => {
      addAppointment({
          clientName: 'Wholesale Lead',
          email: 'lead@artisanflow.ai',
          date: '2025-12-16',
          time: time,
          type: type as any,
          status: 'Confirmed'
      });
      setMessages(prev => [...prev, { 
          role: 'assistant', 
          text: `Confirmed. I have secured your ${type.toLowerCase()} for Dec 16th at ${time}. Your production data has been attached to the meeting invite.` 
      }]);
  };

  if (!isOpen) { 
    return ( 
      <button 
        onClick={() => setIsOpen(true)} 
        className="fixed bottom-6 right-6 w-14 h-14 bg-[#6A2C91] text-white rounded-full flex items-center justify-center shadow-2xl hover:scale-110 transition-all z-50 animate-float"
      >
         <MessageSquare size={24} />
         <div className="absolute -top-1 -right-1 w-4 h-4 bg-[#C5A059] rounded-full border-2 border-white animate-pulse"></div>
      </button> 
    ); 
  }

  return (
