                </h3>
                <p className="text-[10px] text-white/60 font-medium uppercase tracking-widest">Inventory-Aware Agent</p>
            </div>
        </div>
        <button onClick={() => setIsOpen(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors">
            <Minimize2 size={18} />
        </button>
      </div>

      {/* Sync Status Bar */}
      <div className="px-5 py-2 bg-stone-100 border-b border-stone-200 flex justify-between items-center">
          <div className="flex items-center gap-2">
              <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></div>
              <span className="text-[10px] font-bold text-gray-500 uppercase tracking-tight">Factory Link Active</span>
          </div>
          <div className="flex items-center gap-1.5 text-[10px] font-bold text-[#C5A059]">
              <ShieldCheck size={12} />
              <span>MARGIN GUARD™ PROTECTED</span>
          </div>
      </div>

      {/* Message Feed */}
      <div className="flex-1 overflow-y-auto p-5 space-y-4 bg-stone-50/50">
        {messages.map((msg, idx) => (
          <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-4 rounded-2xl text-sm shadow-sm leading-relaxed ${
              msg.role === 'user' 
                ? 'bg-[#6A2C91] text-white rounded-br-none' 
                : 'bg-white text-gray-800 rounded-bl-none border border-stone-200'
            }`}>
              {msg.text}

              {msg.isAuditPrompt && (
                <div className="mt-4 p-3 bg-amber-50 border border-amber-200 rounded-xl space-y-3">
                   <p className="text-[11px] font-bold text-amber-800 flex items-center gap-2">
                       <Factory size={14} /> CAPACITY ALERT: Margin health is currently {manufacturingContext.marginMultiplier}x
                   </p>
                   <p className="text-[10px] text-amber-700">Lola recommends a Manufacturing Audit before accepting wholesale volume.</p>
                   <button 
                      onClick={() => handleSelectSlot('10:00 AM', 'Manufacturing Audit')}
                      className="w-full bg-[#C5A059] text-white py-2 rounded-lg text-xs font-black uppercase tracking-widest hover:bg-[#b08e4d] transition-all"
                    >
                      Schedule Audit
                    </button>
                </div>
              )}

              {msg.isSlotSelector && (
                  <div className="mt-4 space-y-2">
                      <p className="text-[10px] font-bold text-emerald-600 uppercase mb-2">Availability Synchronized:</p>
                      <div className="grid grid-cols-2 gap-2">
                        {['09:00 AM', '02:00 PM'].map(slot => (
                            <button 
                              key={slot} 
                              onClick={() => handleSelectSlot(slot)}
                              className="bg-purple-50 text-[#6A2C91] border border-purple-100 py-2 rounded-xl text-xs font-bold hover:bg-[#6A2C91] hover:text-white transition-all flex items-center justify-center gap-2"
                            >
                                <Calendar size={12} /> {slot}
                            </button>
                        ))}
                      </div>
                  </div>
              )}
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-white text-gray-400 p-4 rounded-2xl text-xs italic border border-stone-100 shadow-sm animate-pulse">
                Lola is querying the floor...
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div className="p-5 bg-white border-t border-stone-100">
        <div className="flex items-center gap-2 bg-stone-100 rounded-2xl px-4 py-1 border border-stone-200 focus-within:border-[#6A2C91] focus-within:ring-1 focus-within:ring-[#6A2C91] transition-all">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Ask Lola about stock or batches..."
            className="flex-1 bg-transparent py-3 text-gray-900 text-sm outline-none placeholder:text-stone-400"
          />
          <button 
            onClick={handleSend}
            disabled={isLoading}
            className="p-2 text-[#6A2C91] hover:scale-110 transition-all disabled:opacity-30"
          >
            <Send size={20} />
          </button>
        </div>
        <p className="text-[8px] text-center text-stone-400 mt-3 font-bold tracking-[0.2em] uppercase">Powered by Gemini 3 Flash Core</p>
      </div>
    </div>
  ); 
};

import React, { createContext, useContext, useState, useEffect } from 'react';

// --- Types ---
export interface InventoryItem {
  id: string | number;
  name: string;
  sku: string;
  stock: number;
  unit: string;
  unitCost: number;
  retailPrice?: number;
  stockValue: number;
  reorderPoint: number;
  type: 'raw' | 'finished';
  category?: string;
  img?: string;
  lowStock?: boolean;
  description?: string;
  dimensions?: string;
  supplier?: string;
  lastUpdated?: string;
}

export interface OrderItem {
  name: string;
  qty: number;
  price: number;
}

export interface Order {
  id: string;
  customer: string;
  email?: string;
  date: string;
  status: 'Processing' | 'Shipped' | 'Delivered' | 'Cancelled';
  platform: 'WooCommerce' | 'Shopify' | 'Etsy' | 'Square';
  items: OrderItem[];
  total: number;
  location: string;
}

export interface Supplier {
    id: string;
    name: string;
    contactName: string;
    email: string;
    phone: string;
    rating: number;
    tier: 'Reliable' | 'Moderate' | 'Risk';
    pricePerUnit: number;
    leadTime: number; // days
    paymentTerms: string;
    discount?: string; // e.g., "5% off orders > 500"
    notes?: string;
}

export interface Recipe {
    id: string;
    name: string;
    sku: string;
    version: string;
    yield: number;
    materialCost: number;
    totalCost: number;
    productionTime: number; // minutes
    ingredients: { name: string; qty: string }[];
}

export interface QualityCheck {
    id: string;
    batchNumber: string;
    productName: string;
    date: string;
    status: 'Passed' | 'Failed' | 'Pending';
    inspector: string;
    notes: string;
}

export interface SupplierCommunication {
    id: string;
    supplierId: string;
    supplierName: string;
    subject: string;
    date: string;
    status: 'Pending' | 'Sent' | 'Responded' | 'Resolved';
    type: 'Email' | 'Phone' | 'Portal';
}

export interface Location {
    id: string;
    name: string;
    type: 'Warehouse' | 'Retail' | 'Storage';
    address: string;
    capacity: string;
}

export interface Report {
    id: string;
    title: string;
    category: string;
    type: string;
    generatedDate: string;
    summaryStats: { label: string; value: string | number; color?: string }[];
    headers: string[];
    data: any[]; // Rows
}

export interface MarketingPost {
    id: string;
    platform: 'Instagram' | 'Facebook' | 'Pinterest' | 'TikTok' | 'Twitter/X' | 'Blog' | 'YouTube' | 'LinkedIn';
    content: string;
    topic: string;
    scheduledDate: string; // YYYY-MM-DD
    status: 'Scheduled' | 'Draft' | 'Published' | 'Pending Approval';
    type: 'Video' | 'Image' | 'Text' | 'Article';
    mediaUrl?: string;
    feedback?: string;
}

export interface BrandVoice {
    adjectives: string[];
    restrictedWords: string[];
}

export interface ReceptionistLogic {
    qualificationQuestions: string[];
}

export interface Appointment {
    id: string;
    clientName: string;
    email: string;
    date: string; // YYYY-MM-DD
    time: string; // HH:mm
    type: 'Consultation' | 'Strategy' | 'Support';
    status: 'Confirmed' | 'Pending';
}

export interface BusinessProfile {
    name: string;
    ownerName: string;
    email: string;
    phone: string;
    address: string;
    website: string;
    logo?: string;
    industry: string;
    goals?: string;
    brandVoice: BrandVoice;
    receptionistLogic: ReceptionistLogic;
    socials: { facebook?: string; instagram?: string; twitter?: string; linkedin?: string; tiktok?: string };
    socialTokens?: Record<string, any>;
    settings: Record<string, any>;
}

export interface Integration {
    id: string;
    name: string;
    category: 'E-commerce' | 'Social' | 'Accounting' | 'Wholesale' | 'POS' | 'Payments';
    status: 'Connected' | 'Connect' | 'Reconfigure';
    logo: string; 
    description: string;
    lastSync?: string;
    config?: {
      consumerKey?: string;
      consumerSecret?: string;
      storeUrl?: string;
    };
}

// Sensor Types
export interface DemandInsight {
    sku: string;
    itemName: string;
    dailyVelocity: number;
    daysOfRunway: number;
    isCritical: boolean;
    recommendedBatch: number;
}

