    { id: '17', name: 'PayPal', category: 'Payments', status: 'Connect', logo: 'https://upload.wikimedia.org/wikipedia/commons/b/b5/PayPal.svg', description: 'Import your order and invoice data from PayPal & PayPal Here. Keep order records complete and inventory current.' }
