export const ArtisanDataProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const [inventory, setInventory] = useState<InventoryItem[]>(() => {
        const saved = localStorage.getItem('artisan_inventory');
        return saved ? JSON.parse(saved) : INITIAL_INVENTORY;
    });

    const [orders, setOrders] = useState<Order[]>(() => {
        const saved = localStorage.getItem('artisan_orders');
        return saved ? JSON.parse(saved) : INITIAL_ORDERS;
    });

    const [suppliers, setSuppliers] = useState<Supplier[]>([]);
    const [recipes, setRecipes] = useState<Recipe[]>([]);
    const [qualityChecks, setQualityChecks] = useState<QualityCheck[]>([]);
    const [supplierCommunications, setSupplierCommunications] = useState<SupplierCommunication[]>([]);
    const [locations, setLocations] = useState<Location[]>([]);
    const [productionStats, setProductionStats] = useState({ active: 1, inProgress: 1, awaiting: 0, completed: 0, pending: 2 });
    const [reports, setReports] = useState<Report[]>([]);
    const [marketingPosts, setMarketingPosts] = useState<MarketingPost[]>([]);
    const [appointments, setAppointments] = useState<Appointment[]>([]);
    const [isMarketingSyncActive, setMarketingSyncActive] = useState(false);
    const [demandInsights, setDemandInsights] = useState<DemandInsight[]>([]);

    const [businessProfile, setBusinessProfile] = useState<BusinessProfile>(() => {
        const saved = localStorage.getItem('artisan_business_profile');
        return saved ? JSON.parse(saved) : {
            name: 'Herbalistic Wellness', ownerName: 'LaToya Renee Carter', email: 'irenee.bss@gmail.com',
            phone: '4435620793', address: '4704 Ridgeway Ave', website: 'https://herbalisticwellness.com', industry: 'Skincare',
            brandVoice: { adjectives: ['Artisanal', 'Luxurious'], restrictedWords: [] },
            receptionistLogic: { qualificationQuestions: [] }, socials: {}, settings: {}
        };
    });

    const [integrations, setIntegrations] = useState<Integration[]>(() => {
        const saved = localStorage.getItem('artisan_integrations');
        return saved ? JSON.parse(saved) : [
          { id: '1', name: 'WooCommerce', category: 'E-commerce', status: 'Connected', logo: 'https://upload.wikimedia.org/wikipedia/commons/2/2a/WooCommerce_logo.svg', description: 'Sync sales velocity.', lastSync: '12/15/2025' }
        ];
    });

    // --- TEMPORAL DEMAND SENSOR ENGINE ---
    useEffect(() => {
        const runDemandSensor = () => {
            const sevenDaysAgo = new Date();
            sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);

            const recentOrders = orders.filter(o => new Date(o.date) >= sevenDaysAgo);
            const insights: DemandInsight[] = [];

            inventory.filter(i => i.type === 'finished').forEach(item => {
                let unitsSold = 0;
                recentOrders.forEach(order => {
                    order.items.forEach(orderItem => {
                        if (orderItem.name === item.name) unitsSold += orderItem.qty;
                    });
                });

                const dailyVelocity = unitsSold / 7;
                const daysOfRunway = dailyVelocity > 0 ? item.stock / dailyVelocity : 999;
                const isCritical = daysOfRunway < 14;

                // Recommended Batch based on 30-day demand + 10% safety buffer
                const recommendedBatch = dailyVelocity > 0 ? Math.ceil((dailyVelocity * 30) * 1.1) : 25;

                insights.push({
                    sku: item.sku,
                    itemName: item.name,
                    dailyVelocity,
                    daysOfRunway,
                    isCritical,
                    recommendedBatch
                });

                // Automated Marketing Studio Integration
                if (isCritical && isMarketingSyncActive) {
                    const postExists = marketingPosts.some(p => p.topic.includes(`STOCK ALERT: ${item.name}`));
                    if (!postExists) {
                         const newPost: Omit<MarketingPost, 'id'> = {
                            platform: 'Email',
                            topic: `STOCK ALERT: ${item.name} Low stock detected`,
                            content: `Our Demand Sensor predicts a stockout for ${item.name} within ${daysOfRunway.toFixed(1)} days. Automated "Last Chance" sequence drafted for approval.`,
                            scheduledDate: new Date().toISOString().split('T')[0],
                            status: 'Draft',
                            type: 'Text'
                        };
                        addMarketingPost(newPost);
                    }
                }
            });
            setDemandInsights(insights);
        };
        runDemandSensor();
    }, [orders, inventory, isMarketingSyncActive]);

    const updateInventory = (id: string | number, updates: Partial<InventoryItem>) => {
        setInventory(prev => prev.map(item => item.id === id ? { ...item, ...updates } : item));
    };

    const addInventoryItem = (item: Omit<InventoryItem, 'id' | 'stockValue'>) => {
        const newItem: InventoryItem = { ...item, id: Date.now(), stockValue: item.stock * item.unitCost, lastUpdated: new Date().toLocaleDateString() };
        setInventory(prev => [...prev, newItem]);
    };

    const processOrder = (orderId: string) => {
        const orderIndex = orders.findIndex(o => o.id === orderId);
        if (orderIndex === -1) return;
        const updatedOrders = [...orders];
        updatedOrders[orderIndex] = { ...orders[orderIndex], status: 'Shipped' };
        setOrders(updatedOrders);
    };

    const addSupplier = (supplier: Omit<Supplier, 'id'>) => {
        setSuppliers(prev => [...prev, { ...supplier, id: Date.now().toString() }]);
    };

    const addLocation = (location: Omit<Location, 'id'>) => {
        setLocations(prev => [...prev, { ...location, id: Date.now().toString() }]);
    };

    const addQualityCheck = (check: Omit<QualityCheck, 'id'>) => {
        setQualityChecks(prev => [{ ...check, id: Date.now().toString() }, ...prev]);
    };

    const addCommunication = (comm: Omit<SupplierCommunication, 'id'>) => {
        setSupplierCommunications(prev => [{ ...comm, id: Date.now().toString() }, ...prev]);
    };

    const generateSchedule = () => {
        setProductionStats({ ...productionStats, active: productionStats.active + 1, pending: Math.max(0, productionStats.pending - 1) });
    };

    const saveReport = (report: Omit<Report, 'id'>) => {
        setReports(prev => [{ ...report, id: Date.now().toString() }, ...prev]);
    };

    const deleteReport = (id: string) => {
        setReports(prev => prev.filter(r => r.id !== id));
    };

    const addMarketingPost = (post: Omit<MarketingPost, 'id'>) => {
        setMarketingPosts(prev => [{ ...post, id: Date.now().toString() }, ...prev]);
    };

    const updateMarketingPost = (id: string, updates: Partial<MarketingPost>) => {
        setMarketingPosts(prev => prev.map(post => post.id === id ? { ...post, ...updates } : post));
    };

    const updateBusinessProfile = (updates: Partial<BusinessProfile>) => {
        setBusinessProfile(prev => {
            const updated = { ...prev, ...updates };
            localStorage.setItem('artisan_business_profile', JSON.stringify(updated));
            return updated;
        });
    };

    const toggleIntegration = (id: string, status: 'Connected' | 'Connect' | 'Reconfigure', config?: any) => {
        setIntegrations(prev => prev.map(int => int.id === id ? { ...int, status, config: config || int.config } : int));
    };

    const addAppointment = (apt: Omit<Appointment, 'id'>) => {
        setAppointments(prev => [...prev, { ...apt, id: Date.now().toString() }]);
    };

    const syncWooCommerce = async (): Promise<{ success: boolean; error?: 'Unauthorized' | 'NotFound' | 'General'; count?: number }> => {
      await new Promise(resolve => setTimeout(resolve, 1500));
      return { success: true, count: 0 };
    };

    const getInventoryValue = () => inventory.reduce((acc, item) => acc + item.stockValue, 0);
    const getTotalRevenue = () => orders.reduce((acc, order) => acc + order.total, 0);

    return (
        <DataContext.Provider value={{ 
            inventory, orders, suppliers, recipes, productionStats,
            qualityChecks, supplierCommunications, locations, reports, marketingPosts, businessProfile, integrations, appointments,
            isMarketingSyncActive, setMarketingSyncActive, demandInsights,
            updateInventory, addInventoryItem, processOrder, importData: () => {}, 
            addSupplier, addLocation, addQualityCheck, addCommunication, 
            generateSchedule, saveReport, deleteReport, addMarketingPost, updateMarketingPost, updateBusinessProfile,
            toggleIntegration, addAppointment, syncWooCommerce,
            getInventoryValue, getTotalRevenue 
        }}>
            {children}
        </DataContext.Provider>
    );
};

export const useArtisanData = () => {
    const context = useContext(DataContext);
    if (!context) throw new Error('useArtisanData must be used within ArtisanDataProvider');
    return context;
};

