    const [marketingPosts, setMarketingPosts] = useState<MarketingPost[]>([]);
    const [appointments, setAppointments] = useState<Appointment[]>([]);
    const [isMarketingSyncActive, setMarketingSyncActive] = useState(false);
    const [demandInsights, setDemandInsights] = useState<DemandInsight[]>([]);

    const [businessProfile, setBusinessProfile] = useState<BusinessProfile>(() => {
        const saved = localStorage.getItem('artisan_business_profile');
        return saved ? JSON.parse(saved) : {
            name: 'Herbalistic Wellness', 
            ownerName: 'LaToya Renee Carter', 
            email: 'irenee.bss@gmail.com',
            phone: '4435620793', 
            address: '4704 Ridgeway Ave', 
            website: 'https://herbalisticwellness.com', 
            industry: 'Skincare',
            brandVoice: { adjectives: ['Artisanal', 'Luxurious'], restrictedWords: [] },
            receptionistLogic: { qualificationQuestions: [] }, 
            socials: {}, 
            settings: {}
        };
    });

    const [integrations, setIntegrations] = useState<Integration[]>([
        { id: '1', name: 'WooCommerce', category: 'E-commerce', status: 'Connected', logo: 'https://upload.wikimedia.org/wikipedia/commons/2/2a/WooCommerce_logo.svg', description: 'Sync products and orders daily.' },
        { id: '2', name: 'Shopify', category: 'E-commerce', status: 'Connect', logo: 'https://upload.wikimedia.org/wikipedia/commons/0/0e/Shopify_logo_2018.svg', description: 'Connect your Shopify store.' },
        { id: '3', name: 'Etsy', category: 'E-commerce', status: 'Connect', logo: 'https://upload.wikimedia.org/wikipedia/commons/8/89/Etsy_logo.svg', description: 'Seamlessly sync your Etsy shop.' },
        { id: '4', name: 'Square', category: 'POS', status: 'Connect', logo: 'https://upload.wikimedia.org/wikipedia/commons/3/30/Square_Inc._Logo.svg', description: 'Connect your Square POS.' },
        { id: '5', name: 'Wix', category: 'E-commerce', status: 'Connect', logo: 'https://upload.wikimedia.org/wikipedia/commons/7/76/Wix.com_website_logo.svg', description: 'Sync orders and product details.' },
        { id: '6', name: 'QuickBooks', category: 'Accounting', status: 'Connect', logo: 'https://upload.wikimedia.org/wikipedia/commons/9/9f/QuickBooks_201x_logo.svg', description: 'Export Purchase Orders.' },
        { id: '7', name: 'Faire', category: 'Wholesale', status: 'Connect', logo: 'https://cdn.worldvectorlogo.com/logos/faire-1.svg', description: 'Connect your Faire wholesale account.' },
        { id: '8', name: 'Amazon Handmade', category: 'E-commerce', status: 'Connect', logo: 'https://upload.wikimedia.org/wikipedia/commons/a/a9/Amazon_logo.svg', description: 'Pull in products and orders.' },
        { id: '9', name: 'Squarespace', category: 'E-commerce', status: 'Connect', logo: 'https://upload.wikimedia.org/wikipedia/commons/b/b3/Squarespace_logo.svg', description: 'Sync Squarespace orders.' },
        { id: '10', name: 'Instagram', category: 'Social', status: 'Connect', logo: 'https://upload.wikimedia.org/wikipedia/commons/e/e7/Instagram_logo_2016.svg', description: 'Schedule and publish posts.' },
        { id: '11', name: 'TikTok', category: 'Social', status: 'Connect', logo: 'https://upload.wikimedia.org/wikipedia/commons/3/34/Ionic_Ionicons_logo-tiktok.svg', description: 'Connect TikTok Business.' },
        { id: '12', name: 'Twitter', category: 'Social', status: 'Connect', logo: 'https://upload.wikimedia.org/wikipedia/commons/6/6f/Logo_of_Twitter.svg', description: 'Schedule tweets and threads.' },
        { id: '13', name: 'LinkedIn', category: 'Social', status: 'Connect', logo: 'https://upload.wikimedia.org/wikipedia/commons/c/ca/LinkedIn_logo_initials.png', description: 'Schedule to LinkedIn profiles.' },
        { id: '14', name: 'Facebook', category: 'Social', status: 'Connect', logo: 'https://upload.wikimedia.org/wikipedia/commons/5/51/Facebook_f_logo_%282019%29.svg', description: 'Connect Facebook Pages.' },
        { id: '15', name: 'YouTube', category: 'Social', status: 'Connect', logo: 'https://upload.wikimedia.org/wikipedia/commons/0/09/YouTube_full-color_icon_%282017%29.svg', description: 'Upload and schedule videos.' },
        { id: '16', name: 'Pinterest', category: 'Social', status: 'Connect', logo: 'https://upload.wikimedia.org/wikipedia/commons/0/08/Pinterest-logo.png', description: 'Schedule pins and manage boards.' },
        { id: '17', name: 'PayPal', category: 'Payments', status: 'Connect', logo: 'https://upload.wikimedia.org/wikipedia/commons/b/b5/PayPal.svg', description: 'Import order and invoice data.' }
    ]);

    // --- Core Sensing Engine ---
    useEffect(() => {
        const runDemandSensor = () => {
            const sevenDaysAgo = new Date();
            sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);
            const recentOrders = orders.filter(o => new Date(o.date) >= sevenDaysAgo);
            const insights: DemandInsight[] = [];

            inventory.filter(i => i.type === 'finished').forEach(item => {
                let unitsSold = 0;
                recentOrders.forEach(order => {
                    order.items.forEach(oi => {
                        if (oi.name === item.name || item.name.includes(oi.name)) unitsSold += oi.qty;
                    });
                });

                const dailyVelocity = unitsSold / 7;
                const daysOfRunway = dailyVelocity > 0 ? item.stock / dailyVelocity : 999;
                const isCritical = daysOfRunway < 14;
                const recommendedBatch = dailyVelocity > 0 ? Math.ceil((dailyVelocity * 30) * 1.1) : 25;

                insights.push({ sku: item.sku, itemName: item.name, dailyVelocity, daysOfRunway, isCritical, recommendedBatch });

                if (isCritical && isMarketingSyncActive) {
                    const postExists = marketingPosts.some(p => p.topic.includes(`STOCK ALERT: ${item.name}`));
                    if (!postExists) {
                         setMarketingPosts(prev => [{
                            id: Date.now().toString(), platform: 'Email', topic: `STOCK ALERT: ${item.name} Low Stock`,
                            content: `Our sensor detects a stockout for ${item.name} in ${daysOfRunway.toFixed(1)} days. Automated "Last Chance" email generated for approval.`,
                            scheduledDate: new Date().toISOString().split('T')[0], status: 'Draft', type: 'Text'
                        }, ...prev]);
                    }
                }
            });
            setDemandInsights(insights);
        };
        runDemandSensor();
    }, [orders, inventory, isMarketingSyncActive]);

    const updateInventory = (id: string | number, updates: Partial<InventoryItem>) => {
        setInventory(prev => prev.map(item => item.id === id ? { ...item, ...updates } : item));
    };

    const addInventoryItem = (item: Omit<InventoryItem, 'id' | 'stockValue'>) => {
        setInventory(prev => [...prev, { ...item, id: Date.now(), stockValue: item.stock * item.unitCost }]);
    };

    const processOrder = (orderId: string) => {
        setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: 'Shipped' } : o));
    };

    const addSupplier = (supplier: Omit<Supplier, 'id'>) => {
        setSuppliers(prev => [...prev, { ...supplier, id: Date.now().toString() }]);
    };

    const generateSchedule = () => {
        setProductionStats(prev => ({ ...prev, active: prev.active + 1, pending: Math.max(0, prev.pending - 1) }));
    };

    const saveReport = (report: Omit<Report, 'id'>) => {
        setReports(prev => [{ ...report, id: Date.now().toString() }, ...prev]);
    };

    const deleteReport = (id: string) => {
        setReports(prev => prev.filter(r => r.id !== id));
    };

    const addMarketingPost = (post: Omit<MarketingPost, 'id'>) => {
        setMarketingPosts(prev => [{ ...post, id: Date.now().toString() }, ...prev]);
    };

    const updateMarketingPost = (id: string, updates: Partial<MarketingPost>) => {
        setMarketingPosts(prev => prev.map(post => post.id === id ? { ...post, ...updates } : post));
    };

    const updateBusinessProfile = (updates: Partial<BusinessProfile>) => {
        setBusinessProfile(prev => {
            const updated = { ...prev, ...updates };
            localStorage.setItem('artisan_business_profile', JSON.stringify(updated));
            return updated;
        });
    };

    const toggleIntegration = (id: string, status: 'Connected' | 'Connect' | 'Reconfigure', config?: any) => {
        setIntegrations(prev => prev.map(int => int.id === id ? { ...int, status, config: config || int.config } : int));
    };

    const addAppointment = (apt: Omit<Appointment, 'id'>) => {
        setAppointments(prev => [...prev, { ...apt, id: Date.now().toString() }]);
    };

    const syncWooCommerce = async (): Promise<{ success: boolean; error?: 'Unauthorized' | 'NotFound' | 'General'; count?: number }> => {
        await new Promise(resolve => setTimeout(resolve, 1500));
        return { success: true, count: 0 };
    };

    const getInventoryValue = () => inventory.reduce((acc, item) => acc + (item.stock * item.unitCost), 0);
    const getTotalRevenue = () => orders.reduce((acc, order) => acc + order.total, 0);

    return (
        <DataContext.Provider value={{ 
            inventory, orders, suppliers, recipes, productionStats, reports, marketingPosts, integrations,
            businessProfile, appointments,
            isMarketingSyncActive, setMarketingSyncActive, demandInsights,
            updateInventory, addInventoryItem, processOrder, 
            addSupplier, generateSchedule, saveReport, deleteReport, addMarketingPost, updateMarketingPost,
            updateBusinessProfile, toggleIntegration, addAppointment, syncWooCommerce, getInventoryValue, getTotalRevenue 
        }}>
            {children}
        </DataContext.Provider>
    );
};

export const useArtisanData = () => {
