    recommendedBatch: number;
}

// Fix: Exported missing MarketingPost interface
export interface MarketingPost {
  id: string;
  platform: 'Instagram' | 'TikTok' | 'Pinterest' | 'Email' | 'Blog' | 'Facebook' | 'YouTube' | 'LinkedIn' | 'Twitter/X' | 'Twitter' | 'Direct';
