// --- 2. Business Setup ---
export const BusinessSetup = () => {
    const { businessProfile, updateBusinessProfile } = useArtisanData();
    const [profile, setProfile] = useState(businessProfile);
    const [isSaving, setIsSaving] = useState(false);
    const [saveSuccess, setSaveSuccess] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleSave = () => {
        setIsSaving(true);
        updateBusinessProfile(profile);
        setTimeout(() => {
            setIsSaving(false);
            setSaveSuccess(true);
            setTimeout(() => setSaveSuccess(false), 2000);
        }, 800);
    };

    const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            const reader = new FileReader();
            reader.onloadend = () => {
                const result = reader.result as string;
                setProfile(prev => ({ ...prev, logo: result }));
                updateBusinessProfile({ logo: result });
            };
            reader.readAsDataURL(file);
        }
    };

    return (
        <div className="p-6 space-y-8 animate-in fade-in pb-20">
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-3xl font-bold text-gray-900">Business Setup</h1>
                    <p className="text-gray-500">Configure your business parameters</p>
                </div>
                <Button 
                    className={`min-w-[140px] text-white transition-all ${saveSuccess ? 'bg-green-600' : 'bg-[#6A2C91]'}`} 
                    onClick={handleSave}
                    disabled={isSaving}
                >
                    {isSaving ? 'Saving...' : saveSuccess ? 'Saved!' : 'Save Changes'}
                </Button>
            </div>

            <Card title="Business Identity">
                <div className="space-y-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <Input value={profile.name} onChange={e => setProfile({...profile, name: e.target.value})} placeholder="Business Name" />
                        <Select value={profile.industry} onChange={e => setProfile({...profile, industry: e.target.value})}>
                            <option value="Skincare">Skincare & Beauty</option>
                            <option value="Candles">Candles</option>
                        </Select>
                    </div>
                    <div className="flex items-center gap-6">
                        <div className="w-24 h-24 bg-gray-100 rounded-xl border flex items-center justify-center overflow-hidden">
                            {profile.logo ? <img src={profile.logo} className="w-full h-full object-cover" /> : <span className="text-[10px] text-gray-400 uppercase">No Logo</span>}
                        </div>
                        <Button variant="outline" onClick={() => fileInputRef.current?.click()}><Upload size={16} className="mr-2"/> Upload Logo</Button>
                        <input type="file" ref={fileInputRef} className="hidden" onChange={handleLogoUpload} />
                    </div>
                </div>
            </Card>
        </div>
    );
};

