                    <p className="text-gray-500">Connect your commerce platforms and social channels.</p>
                </div>
                <Badge color="purple">API Status: Healthy</Badge>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {integrations.map(int => (
                    <div key={int.id} className="bg-white border border-gray-200 rounded-xl p-6 shadow-sm hover:shadow-lg transition-all flex flex-col group relative">
                        {int.status === 'Connected' && <CheckCircle className="absolute top-4 right-4 text-emerald-500" size={20} />}
