    ]);

    useEffect(() => {
        const runDemandSensor = () => {
            const sevenDaysAgo = new Date();
            sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);
            const recentOrders = orders.filter(o => new Date(o.date) >= sevenDaysAgo);
            const insights: DemandInsight[] = [];

            inventory.filter(i => i.type === 'finished').forEach(item => {
                let unitsSold = 0;
                recentOrders.forEach(order => {
                    order.items.forEach(oi => {
                        if (oi.name === item.name || item.name.includes(oi.name)) unitsSold += oi.qty;
                    });
                });

                const dailyVelocity = unitsSold / 7;
                const daysOfRunway = dailyVelocity > 0 ? item.stock / dailyVelocity : 999;
                const isCritical = daysOfRunway < 14;
                const recommendedBatch = dailyVelocity > 0 ? Math.ceil((dailyVelocity * 30) * 1.1) : 25;

                insights.push({ sku: item.sku, itemName: item.name, dailyVelocity, daysOfRunway, isCritical, recommendedBatch });

                if (isCritical && isMarketingSyncActive) {
                    const postExists = marketingPosts.some(p => p.topic?.includes(`STOCK ALERT: ${item.name}`));
                    if (!postExists) {
                         setMarketingPosts(prev => [{
                            id: Date.now().toString(), platform: 'Email', topic: `STOCK ALERT: ${item.name} Low Stock`,
                            content: `Our sensor detects a stockout for ${item.name} in ${daysOfRunway.toFixed(1)} days.`,
                            scheduledDate: new Date().toISOString().split('T')[0], status: 'Draft', type: 'Text'
                        }, ...prev]);
                    }
                }
            });
            setDemandInsights(insights);
        };
        runDemandSensor();
    }, [orders, inventory, isMarketingSyncActive]);

    const updateInventory = (id: string | number, updates: Partial<InventoryItem>) => setInventory(prev => prev.map(item => item.id === id ? { ...item, ...updates } : item));
    const addInventoryItem = (item: any) => setInventory(prev => [...prev, { ...item, id: Date.now(), stockValue: item.stock * item.unitCost }]);
    const processOrder = (orderId: string) => setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: 'Shipped' } : o));
    const addSupplier = (supplier: any) => setSuppliers(prev => [...prev, { ...supplier, id: Date.now().toString() }]);
    const generateSchedule = () => setProductionStats(prev => ({ ...prev, active: prev.active + 1, pending: Math.max(0, prev.pending - 1) }));
    const addMarketingPost = (post: any) => setMarketingPosts(prev => [{ ...post, id: Date.now().toString() }, ...prev]);
    const updateBusinessProfile = (updates: Partial<BusinessProfile>) => {
        setBusinessProfile(prev => {
            const updated = { ...prev, ...updates };
            localStorage.setItem('artisan_business_profile', JSON.stringify(updated));
            return updated;
        });
    };
    const toggleIntegration = (id: string, status: any, config?: any) => setIntegrations(prev => prev.map(int => int.id === id ? { ...int, status, config } : int));
    const syncWooCommerce = async () => { await new Promise(r => setTimeout(r, 1500)); return { success: true, count: 0 }; };
    const getInventoryValue = () => inventory.reduce((acc, item) => acc + (item.stock * item.unitCost), 0);
    const getTotalRevenue = () => orders.reduce((acc, order) => acc + order.total, 0);

    // Context handler implementations
    const saveReport = (report: Omit<Report, 'id'>) => setReports(prev => [{ ...report, id: Date.now().toString() }, ...prev]);
    const deleteReport = (id: string) => setReports(prev => prev.filter(r => r.id !== id));
    const addCommunication = (comm: any) => setSupplierCommunications(prev => [{ ...comm, id: Date.now().toString() }, ...prev]);
    const addQualityCheck = (check: any) => setQualityChecks(prev => [{ ...check, id: Date.now().toString() }, ...prev]);
    const addLocation = (location: any) => setLocations(prev => [...prev, { ...location, id: Date.now().toString() }]);
    const addAppointment = (appointment: any) => setAppointments(prev => [...prev, { ...appointment, id: Date.now().toString() }]);

    return (
        <DataContext.Provider value={{ 
            inventory, orders, suppliers, productionStats, marketingPosts, integrations, businessProfile,
            isMarketingSyncActive, setMarketingSyncActive, demandInsights,
            reports, supplierCommunications, qualityChecks, locations, recipes,
            updateInventory, addInventoryItem, processOrder, addSupplier, generateSchedule, addMarketingPost,
            updateBusinessProfile, toggleIntegration, syncWooCommerce, getInventoryValue, getTotalRevenue,
            saveReport, deleteReport, addCommunication, addQualityCheck, addLocation, addAppointment
        }}>
            {children}
        </DataContext.Provider>
    );
};

export const useArtisanData = () => {
    const context = useContext(DataContext);
    if (!context) throw new Error('useArtisanData must be used within ArtisanDataProvider');
    return context;
};

