export interface InventoryItem {
  id: string | number;
  name: string;
  sku: string;
  stock: number;
  unit: string;
  unitCost: number;
  retailPrice?: number;
  stockValue: number;
  reorderPoint: number;
  type: 'raw' | 'finished';
