  img?: string;
  lowStock?: boolean;
  description?: string;
  dimensions?: string;
  supplier?: string;
  lastUpdated?: string;
}

export interface Order {
  id: string;
  customer: string;
  email?: string;
  date: string;
  status: 'Processing' | 'Shipped' | 'Delivered' | 'Cancelled';
  platform: string;
  items: { name: string; qty: number; price: number }[];
  total: number;
  location: string;
}

export interface Supplier {
    id: string;
