    leadTime: number; 
    paymentTerms: string;
}

export interface BusinessProfile {
    name: string;
    ownerName: string;
    email: string;
    phone: string;
    address: string;
    website: string;
    logo?: string;
    industry: string;
    brandVoice: { adjectives: string[]; restrictedWords: string[] };
    receptionistLogic: { qualificationQuestions: string[] };
