export interface Integration {
    id: string;
    name: string;
    category: string;
    status: 'Connected' | 'Connect' | 'Reconfigure';
    logo: string; 
    description: string;
    lastSync?: string;
    config?: any;
}

export interface DemandInsight {
    sku: string;
    itemName: string;
    dailyVelocity: number;
    daysOfRunway: number;
    isCritical: boolean;
    recommendedBatch: number;
}

export interface MarketingPost {
  id: string;
  platform: string;
  topic: string;
  content: string;
  scheduledDate: string;
