  const getTotalRevenue = () => orders.reduce((acc, o) => acc + o.total, 0);

  return (
    <DataContext.Provider value={{ 
      inventory, orders, suppliers, marketingPosts, integrations, businessProfile, appointments, reports, qualityChecks, locations, recipes, demandInsights, productionStats,
      updateInventory, addInventoryItem, processOrder, addSupplier, generateSchedule, addMarketingPost, updateMarketingPost, updateBusinessProfile, toggleIntegration, addAppointment, saveReport, deleteReport, addQualityCheck, addLocation, syncWooCommerce, getInventoryValue, getTotalRevenue 
    }}>
      {children}
    </DataContext.Provider>
  );
};

export const useArtisanData = () => {
