      <div className="p-5 bg-white border-t border-stone-100">
        <div className="flex items-center gap-2 bg-stone-100 rounded-2xl px-4 py-1 border border-stone-200 focus-within:border-[#6A2C91] transition-all">
          <input type="text" value={input} onChange={(e) => setInput(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSend()} placeholder="Ask Lola about stock or batches..." className="flex-1 bg-transparent py-3 text-gray-900 text-sm outline-none placeholder:text-stone-400" />
          <button onClick={handleSend} disabled={isLoading} className="p-2 text-[#6A2C91] hover:scale-110 transition-all disabled:opacity-30"><Send size={20} /></button>
        </div>
      </div>
    </div>
  ); 
};

