      };
    });
    setDemandInsights(insights);
  }, [inventory]);

  const updateInventory = (id: string | number, updates: Partial<InventoryItem>) => setInventory(prev => prev.map(i => i.id === id ? { ...i, ...updates } : i));
  const addInventoryItem = (item: any) => setInventory(prev => [...prev, { ...item, id: Date.now(), stockValue: (item.stock || 0) * (item.unitCost || 0) }]);

  const importData = async (files: File[]) => {
      console.log("Ingesting manufacturing data...", files);
      await new Promise(r => setTimeout(r, 1000));
      return true;
  };

  const processOrder = (id: string) => setOrders(prev => prev.map(o => o.id === id ? { ...o, status: 'Shipped' } : o));
  const addSupplier = (s: any) => setSuppliers(prev => [...prev, { ...s, id: Date.now().toString() }]);
  const generateSchedule = () => setProductionStats(prev => ({ ...prev, active: prev.active + 1, pending: Math.max(0, prev.pending - 1) }));
  const addMarketingPost = (post: any) => setMarketingPosts(prev => [{ ...post, id: Date.now().toString() }, ...prev]);
  const updateMarketingPost = (id: string, updates: Partial<MarketingPost>) => setMarketingPosts(prev => prev.map(p => p.id === id ? { ...p, ...updates } : p));
  const updateBusinessProfile = (updates: Partial<BusinessProfile>) => setBusinessProfile(prev => ({ ...prev, ...updates }));
  const toggleIntegration = (id: string, status: any) => setIntegrations(prev => prev.map(int => int.id === id ? { ...int, status } : int));
  const addAppointment = (a: any) => setAppointments(prev => [...prev, { ...a, id: Date.now().toString() }]);
  const saveReport = (r: any) => setReports(prev => [{ ...r, id: Date.now().toString() }, ...prev]);
  const deleteReport = (id: string) => setReports(prev => prev.filter(r => r.id !== id));
  const addCommunication = (comm: any) => setSupplierCommunications(prev => [{ ...comm, id: Date.now().toString() }, ...prev]);
  const addQualityCheck = (c: any) => setQualityChecks(prev => [{ ...c, id: Date.now().toString() }, ...prev]);
  const addLocation = (l: any) => setLocations(prev => [{ ...l, id: Date.now().toString() }, ...prev]);

  const syncWooCommerce = async () => { await new Promise(r => setTimeout(r, 1000)); return { success: true, count: 0 }; };
  const getInventoryValue = () => inventory.reduce((acc, i) => acc + (i.stock * i.unitCost), 0);
  const getTotalRevenue = () => orders.reduce((acc, o) => acc + o.total, 0);

  const getMarginMetrics = () => {
      const finished = inventory.filter(i => i.type === 'finished');
      if (finished.length === 0) return { isMarginHealthy: true, marginMultiplier: 2.2 };
      const avgMultiplier = finished.reduce((acc, i) => acc + (i.retailPrice && i.unitCost ? i.retailPrice / i.unitCost : 2.2), 0) / finished.length;
      return { isMarginHealthy: avgMultiplier >= 2.0, marginMultiplier: avgMultiplier };
  };

  return (
    <DataContext.Provider value={{ 
      inventory, orders, suppliers, marketingPosts, integrations, businessProfile, appointments, reports, supplierCommunications, qualityChecks, locations, recipes, demandInsights, productionStats,
      updateInventory, addInventoryItem, importData, processOrder, addSupplier, generateSchedule, addMarketingPost, updateMarketingPost, updateBusinessProfile, toggleIntegration, addAppointment, saveReport, deleteReport, addCommunication, addQualityCheck, addLocation, syncWooCommerce, getInventoryValue, getTotalRevenue, getMarginMetrics
    }}>
      {children}
    </DataContext.Provider>
  );
};

export const useArtisanData = () => {
  const context = useContext(DataContext);
  if (!context) throw new Error('useArtisanData must be used within ArtisanDataProvider');
  return context;
};
