export const Integrations = () => {
    const { integrations, toggleIntegration } = useArtisanData();
    const [selectedInt, setSelectedInt] = useState<Integration | null>(null);
    const [isConnecting, setIsConnecting] = useState(false);
    const navigate = useNavigate();

    const handleConnect = async () => {
        setIsConnecting(true);
        await new Promise(r => setTimeout(r, 1500));
        if (selectedInt) {
            toggleIntegration(selectedInt.id, 'Connected');
            setSelectedInt(null);
        }
        setIsConnecting(false);
    };

    return (
        <div className="p-6 space-y-8 animate-in fade-in pb-20">
