import React, { useState } from 'react';
import { Card, Button, Badge, Input, Select, Modal } from './UI';
import { useArtisanData, QualityCheck } from './DataContext';
import { ClipboardList, Plus, Search, Filter, CheckCircle, XCircle, Clock, ArrowLeft } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

export const QualityControl = () => {
  const { qualityChecks, addQualityCheck } = useArtisanData();
  const [searchTerm, setSearchTerm] = useState('');
  const [showAdd, setShowAdd] = useState(false);
  const navigate = useNavigate();

  const [newCheck, setNewCheck] = useState<Partial<QualityCheck>>({
      productName: '', batchNumber: '', status: 'Pending', inspector: '', date: new Date().toLocaleDateString()
  });

  const handleAdd = () => {
      if(!newCheck.productName) return;
      addQualityCheck(newCheck as any);
      setShowAdd(false);
      setNewCheck({ productName: '', batchNumber: '', status: 'Pending', inspector: '' });
  };

  return (
    <div className="p-6 space-y-6 animate-in fade-in pb-20">
      <Modal isOpen={showAdd} onClose={() => setShowAdd(false)} title="New Quality Check">
          <div className="space-y-4">
              <Input placeholder="Product / Material Name" value={newCheck.productName} onChange={e => setNewCheck({...newCheck, productName: e.target.value})} />
              <Input placeholder="Batch Number" value={newCheck.batchNumber} onChange={e => setNewCheck({...newCheck, batchNumber: e.target.value})} />
              <Input placeholder="Inspector Name" value={newCheck.inspector} onChange={e => setNewCheck({...newCheck, inspector: e.target.value})} />
              <div>
                  <label className="text-xs text-gray-500">Status</label>
                  <Select value={newCheck.status} onChange={e => setNewCheck({...newCheck, status: e.target.value as any})}>
                      <option>Pending</option>
                      <option>Passed</option>
                      <option>Failed</option>
                  </Select>
              </div>
              <Button onClick={handleAdd} className="w-full">Save Check</Button>
          </div>
      </Modal>

      <div className="flex flex-col gap-1">
        <button onClick={() => navigate(-1)} className="flex items-center gap-2 text-gray-500 hover:text-[#6A2C91] mb-2 font-medium transition-colors">
          <ArrowLeft size={18} /> Back
        </button>
        <div className="flex justify-between items-center">
            <div>
                <h1 className="text-3xl font-bold text-gray-900">Quality Control</h1>
                <p className="text-gray-500">Track quality inspections and ensure standards</p>
            </div>
            <Button className="bg-[#6A2C91] text-white" onClick={() => setShowAdd(true)}>
                <Plus size={16} className="mr-2" /> New Quality Check
            </Button>
        </div>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm">
              <p className="text-xs text-gray-500 font-bold uppercase mb-2">Total Checks</p>
              <p className="text-3xl font-bold text-gray-900">{qualityChecks.length}</p>
          </div>
          <div className="bg-emerald-50 p-6 rounded-xl border border-emerald-100 shadow-sm">
              <p className="text-xs text-emerald-700 font-bold uppercase mb-2">Passed</p>
              <p className="text-3xl font-bold text-emerald-700">{qualityChecks.filter(c => c.status === 'Passed').length}</p>
          </div>
          <div className="bg-red-50 p-6 rounded-xl border border-red-100 shadow-sm">
              <p className="text-xs text-red-700 font-bold uppercase mb-2">Failed</p>
              <p className="text-3xl font-bold text-red-700">{qualityChecks.filter(c => c.status === 'Failed').length}</p>
          </div>
          <div className="bg-[#FFF9E6] p-6 rounded-xl border border-[#FFE082] shadow-sm">
              <p className="text-xs text-[#B45309] font-bold uppercase mb-2">Pending</p>
              <p className="text-3xl font-bold text-[#B45309]">{qualityChecks.filter(c => c.status === 'Pending').length}</p>
          </div>
      </div>

      <div className="flex gap-4">
          <div className="relative flex-1">
              <Search className="absolute left-3 top-3 text-gray-400" size={18} />
              <Input 
                  placeholder="Search checks..." 
                  className="pl-10" 
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
              />
          </div>
          <Select className="w-48">
              <option>All Status</option>
              <option>Passed</option>
              <option>Failed</option>
              <option>Pending</option>
          </Select>
      </div>

      {/* Content Area */}
      <Card title="Quality Check History" className="min-h-[400px]">
          {qualityChecks.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-64 text-center">
                  <div className="w-16 h-16 bg-gray-50 rounded-xl flex items-center justify-center mb-4">
                      <ClipboardList size={32} className="text-gray-300" />
                  </div>
                  <p className="text-gray-500">No quality checks found</p>
              </div>
          ) : (
              <div className="space-y-2">
                  {qualityChecks.map(check => (
                      <div key={check.id} className="flex items-center justify-between p-4 border-b border-gray-100 last:border-0 hover:bg-gray-50">
                          <div>
                              <h4 className="font-bold text-gray-900">{check.productName}</h4>
                              <p className="text-xs text-gray-500">Batch: {check.batchNumber} • Inspector: {check.inspector}</p>
                          </div>
                          <Badge color={check.status === 'Passed' ? 'green' : check.status === 'Failed' ? 'red' : 'gold'}>
                              {check.status}
                          </Badge>
                      </div>
                  ))}
              </div>
          )}
      </Card>
    </div>
  );
};

