  marketingPosts: any[];
  integrations: any[];
  demandInsights: any[];
}

const DataContext = createContext<DataContextType | undefined>(undefined);

const SHEET_URL = "https://docs.google.com/spreadsheets/d/1DGKyyamGRbo-iWQET2ZCE4bmPuHwoKb70TJEaj2PBV8/edit";

export const ArtisanDataProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userTier, setUserTier] = useState<UserTier>('Free Audit');
  const [businessProfile, setBusinessProfile] = useState<BusinessProfile>({
    name: 'Herbalistic Wellness', 
    ownerName: 'LaToya Renee Carter', 
    email: 'irenee.bss@gmail.com', 
    industry: 'Skincare',
    tier: 'Free Audit',
    status: 'Active',
    brandVoice: { adjectives: ['Artisanal', 'Luxurious'], restrictedWords: [] },
    receptionistLogic: { qualificationQuestions: [] }
  });

  const [inventory, setInventory] = useState<InventoryItem[]>([
    { id: 1, name: '100% Grain Alcohol', sku: '576764A', stock: 23, unit: 'oz', unitCost: 0.77, stockValue: 17.71, reorderPoint: 10, type: 'raw' },
    { id: 2, name: 'Rosemary Leaf', sku: 'Herb-115', stock: 6, unit: 'oz', unitCost: 2.50, stockValue: 15.00, reorderPoint: 10, type: 'raw', lowStock: true },
    { id: 101, name: 'Lavender Rose SOAP', sku: '3', stock: 7, unit: 'piece', unitCost: 3.20, retailPrice: 8.00, stockValue: 22.40, reorderPoint: 20, type: 'finished', category: 'Soaps' },
    { id: 102, name: 'Turmeric Myrrh Soap', sku: '53', stock: 12, unit: 'piece', unitCost: 3.50, retailPrice: 9.00, stockValue: 42.00, reorderPoint: 15, type: 'finished', category: 'Soaps' },
  ]);

  const [orders] = useState<Order[]>([
    { id: '#13086', customer: 'RJ Baise', email: 'rj.baise@me.com', date: new Date().toLocaleDateString(), location: 'Cave City, KY', status: 'Processing', platform: 'Direct', total: 24.59, items: [{ name: 'Turmeric Myrrh Soap', qty: 10, price: 6.15 }] }
  ]);

  const [reports, setReports] = useState<Report[]>([]);
  const [productionStats, setProductionStats] = useState({ active: 1, inProgress: 1, awaiting: 0, completed: 0, pending: 2 });

  // Pings sheet to verify session on mount
  useEffect(() => {
    const syncStatus = async () => {
      console.log(`[ArtisanFlow] Pinging Google Sheet at ${SHEET_URL} to verify status...`);
      // Simulate verification
      await new Promise(r => setTimeout(r, 500));
    };
    syncStatus();
  }, []);

  const login = async (email: string, pass: string) => {
    setIsAuthenticated(true);
    return true;
  };

  const googleLogin = async () => {
    setIsAuthenticated(true);
  };

  const logout = () => {
    setIsAuthenticated(false);
  };

  const signUp = async (data: any) => {
    console.log(`[ArtisanFlow] Appending user metadata to Sheet: ${data.email}, Tier: ${data.tier}`);
    setBusinessProfile(prev => ({ ...prev, ...data }));
    setUserTier(data.tier);
    setIsAuthenticated(true);
  };

  const updateTier = async (tier: UserTier) => {
    console.log(`[ArtisanFlow] Updating Tier in Google Sheet to: ${tier}`);
    setUserTier(tier);
    setBusinessProfile(prev => ({ ...prev, tier }));
  };

  const updateBusinessProfile = (updates: Partial<BusinessProfile>) => setBusinessProfile(prev => ({ ...prev, ...updates }));

  const getInventoryValue = () => inventory.reduce((acc, i) => acc + (i.stock * i.unitCost), 0);
  const getTotalRevenue = () => orders.reduce((acc, o) => acc + o.total, 0);

  const getMarginMetrics = () => {
    const finished = inventory.filter(i => i.type === 'finished');
    if (finished.length === 0) return { isMarginHealthy: true, marginMultiplier: 2.2 };
    const avgMultiplier = finished.reduce((acc, i) => acc + (i.retailPrice && i.unitCost ? i.retailPrice / i.unitCost : 2.2), 0) / finished.length;
    return { isMarginHealthy: avgMultiplier >= 2.0, marginMultiplier: avgMultiplier };
  };

  const saveReport = (r: any) => setReports(prev => [{ ...r, id: Date.now().toString() }, ...prev]);
  const deleteReport = (id: string) => setReports(prev => prev.filter(r => r.id !== id));

  const importData = async (files: File[]) => {
      console.log("Ingesting manufacturing data...", files);
      await new Promise(r => setTimeout(r, 1000));
      return true;
  };

  const addInventoryItem = (item: any) => setInventory(prev => [...prev, { ...item, id: Date.now(), stockValue: (item.stock || 0) * (item.unitCost || 0) }]);
  const addAppointment = (a: any) => console.log("Appointment added", a);
  const generateSchedule = () => setProductionStats(prev => ({ ...prev, active: prev.active + 1 }));
  const processOrder = (id: string) => console.log("Processing order", id);
  const syncWooCommerce = async () => ({ success: true, count: 0 });

  return (
    <DataContext.Provider value={{ 
      inventory, orders, businessProfile, isAuthenticated, userTier, reports, productionStats,
      login, googleLogin, logout, signUp, updateTier, updateBusinessProfile,
      getInventoryValue, getTotalRevenue, getMarginMetrics, saveReport, deleteReport,
      importData, addInventoryItem, addAppointment, generateSchedule, processOrder, syncWooCommerce,
      suppliers: [], marketingPosts: [], integrations: [], demandInsights: []
    }}>
      {children}
    </DataContext.Provider>
  );
};

export const useArtisanData = () => {
  const context = useContext(DataContext);
  if (!context) throw new Error('useArtisanData must be used within ArtisanDataProvider');
  return context;
};

