export const FileUploader: React.FC<{ 
  onUpload?: (files: File[]) => void; 
  acceptedFormats?: string; // e.g., ".csv, .pdf, .xlsx"
  label?: string;
}> = ({ onUpload, acceptedFormats = ".csv, .pdf, .xlsx, .xls", label = "Upload Data" }) => {
  const [dragActive, setDragActive] = useState(false);
  const [files, setFiles] = useState<File[]>([]);
  const inputRef = useRef<HTMLInputElement>(null);

  const handleDrag = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") {
      setDragActive(true);
    } else if (e.type === "dragleave") {
      setDragActive(false);
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFiles(Array.from(e.dataTransfer.files));
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    e.preventDefault();
    if (e.target.files && e.target.files[0]) {
      handleFiles(Array.from(e.target.files));
    }
  };

  const handleFiles = (newFiles: File[]) => {
    setFiles([...files, ...newFiles]);
    if (onUpload) onUpload(newFiles);
  };

  const removeFile = (idx: number) => {
    const newFiles = [...files];
    newFiles.splice(idx, 1);
    setFiles(newFiles);
  };

  return (
    <div className="w-full">
        <label className="block text-sm font-medium text-gray-700 mb-2">{label}</label>
        <div 
            className={`relative border-2 border-dashed rounded-xl p-6 text-center transition-all duration-200 ease-in-out ${dragActive ? 'border-[#6A2C91] bg-purple-50' : 'border-gray-300 bg-gray-50 hover:bg-gray-100'}`}
            onDragEnter={handleDrag} 
            onDragLeave={handleDrag} 
            onDragOver={handleDrag} 
            onDrop={handleDrop}
        >
            <input 
                ref={inputRef}
                type="file" 
                multiple 
                className="hidden" 
                onChange={handleChange}
                accept={acceptedFormats}
            />

            <div className="flex flex-col items-center gap-2 cursor-pointer" onClick={() => inputRef.current?.click()}>
                <div className={`p-3 rounded-full ${dragActive ? 'bg-[#6A2C91] text-white' : 'bg-gray-200 text-gray-500'}`}>
                    <Upload size={24} />
                </div>
                <p className="text-sm font-medium text-gray-700">
                    <span className="text-[#6A2C91] font-bold hover:underline">Click to upload</span> or drag and drop
                </p>
                <p className="text-xs text-gray-500 uppercase tracking-wide">CSV, PDF, Excel</p>
            </div>
        </div>

        {/* File List */}
        {files.length > 0 && (
            <div className="mt-4 space-y-2">
                {files.map((file, idx) => (
                    <div key={idx} className="flex items-center justify-between p-3 bg-white border border-gray-200 rounded-lg shadow-sm animate-fade-in">
                        <div className="flex items-center gap-3">
                            <FileText size={18} className="text-[#6A2C91]" />
                            <div>
                                <p className="text-sm font-medium text-gray-900 truncate max-w-[200px]">{file.name}</p>
                                <p className="text-xs text-gray-500">{(file.size / 1024).toFixed(1)} KB</p>
                            </div>
                        </div>
                        <div className="flex items-center gap-2">
                            <CheckCircle size={16} className="text-green-500" />
                            <button onClick={() => removeFile(idx)} className="text-gray-400 hover:text-red-500 transition-colors">
                                <X size={16} />
                            </button>
                        </div>
                    </div>
                ))}
            </div>
        )}
    </div>
  );
};

