export const SubscriptionManagement = () => {
    const { userTier, updateTier } = useArtisanData();
    const [isUpgrading, setIsUpgrading] = useState(false);
    const [selectedUpgrade, setSelectedUpgrade] = useState<UserTier | null>(null);
    const navigate = useNavigate();

    const handleUpgrade = async () => {
        if (!selectedUpgrade) return;
        setIsUpgrading(true);
        // Simulate Payment Gateway Handshake (Stripe/Square)
        await new Promise(r => setTimeout(r, 2000));
        await updateTier(selectedUpgrade);
        setIsUpgrading(false);
        setSelectedUpgrade(null);
    };

    return (
        <div className="p-6 space-y-8 pb-20 animate-in fade-in">
            <Modal isOpen={!!selectedUpgrade} onClose={() => setSelectedUpgrade(null)} title="Secure Payment Gateway">
                <div className="space-y-6 p-2 text-center">
                    <div className="p-4 bg-purple-50 rounded-xl mb-4">
                        <p className="text-[10px] font-black text-purple-600 uppercase tracking-widest mb-1">Confirm Membership Upgrade</p>
                        <h4 className="text-xl font-bold text-gray-900">{selectedUpgrade}</h4>
                    </div>
                    <div className="space-y-4">
                        <Input placeholder="Card Number" defaultValue="4242 4242 4242 4242" />
                        <div className="grid grid-cols-2 gap-4">
                            <Input placeholder="MM/YY" defaultValue="12/26" />
                            <Input placeholder="CVC" defaultValue="***" />
                        </div>
                    </div>
                    <div className="pt-4">
                        <Button className="w-full bg-[#6A2C91] text-white h-14 font-black text-xs tracking-widest" onClick={handleUpgrade} disabled={isUpgrading}>
                           {isUpgrading ? 'ESTABLISHING SECURE HANDSHAKE...' : <><CreditCard size={18} className="mr-2" /> AUTHORIZE & UPGRADE</>}
                        </Button>
                        <p className="text-[10px] text-gray-400 mt-4 italic">Encrypted by ArtisanFlow Vault Service. 256-bit AES protection active.</p>
                    </div>
                </div>
            </Modal>

            <button onClick={() => navigate(-1)} className="flex items-center gap-2 text-gray-500 hover:text-[#6A2C91] mb-2 font-medium transition-colors">
              <ArrowLeft size={18} /> Back
            </button>
            <h1 className="text-3xl font-bold text-gray-900 tracking-tight">Membership Architecture</h1>

            <div className="bg-white border-2 border-[#6A2C91] rounded-2xl p-8 flex flex-col md:flex-row justify-between items-center gap-8 shadow-xl">
               <div className="flex items-center gap-6">
                  <div className="w-20 h-20 bg-purple-100 rounded-2xl flex items-center justify-center text-[#6A2C91] shadow-inner">
                      <Crown size={40} />
                  </div>
                  <div>
                      <span className="text-[10px] font-black text-[#6A2C91] uppercase tracking-[0.2em] mb-1 block">Current Deployment Level</span>
                      <h3 className="text-4xl font-black text-gray-900">{userTier}</h3>
                      <p className="text-gray-500 mt-1 font-medium italic">Status: <span className="text-emerald-500 not-italic font-black">Active & Verified</span></p>
