    return (
        <div className="p-6 space-y-8 pb-20 animate-in fade-in">
            <Modal isOpen={!!selectedUpgrade} onClose={() => setSelectedUpgrade(null)} title="Secure Payment Gateway">
                <div className="space-y-6 p-2 text-center">
