const SHEET_URL = "https://docs.google.com/spreadsheets/d/1DGKyyamGRbo-iWQET2ZCE4bmPuHwoKb70TJEaj2PBV8/edit";

export const ArtisanDataProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userTier, setUserTier] = useState<UserTier>('Free Audit');
  const [isSessionVerifying, setIsSessionVerifying] = useState(false);
  const [businessProfile, setBusinessProfile] = useState<BusinessProfile>({
    name: 'Herbalistic Wellness', 
    ownerName: 'LaToya Renee Carter', 
    email: 'irenee.bss@gmail.com', 
    industry: 'Skincare',
    tier: 'Free Audit',
    status: 'Active',
    brandVoice: { adjectives: ['Artisanal', 'Luxurious'], restrictedWords: [] },
