  const [integrations] = useState<Integration[]>([
    { id: '1', name: 'WooCommerce', category: 'E-commerce', status: 'Connected', logo: 'https://upload.wikimedia.org/wikipedia/commons/2/2a/WooCommerce_logo.svg', description: 'Real-time stock sync.' },
    { id: '2', name: 'Shopify', category: 'E-commerce', status: 'Connect', logo: 'https://upload.wikimedia.org/wikipedia/commons/0/0e/Shopify_logo_2018.svg', description: 'Import orders daily.' }
