  // Operational Logic: Every session begins by pinging Google Sheet
  useEffect(() => {
    const verifySession = async () => {
      if (isAuthenticated) {
        setIsSessionVerifying(true);
        console.log(`[ArtisanFlow] Pinging Google Sheet for session verification: ${SHEET_URL}`);
