            <LockedNode isLocked={userTier === 'Free Audit'} requiredTier="Artisan Flow Basic" onUpgrade={() => navigate('/settings/subscription')}>
                <DashboardPage />
            </LockedNode>
        } />
        <Route path="/inventory" element={
            <LockedNode isLocked={userTier === 'Free Audit'} requiredTier="Artisan Flow Basic" onUpgrade={() => navigate('/settings/subscription')}>
                <Inventory />
            </LockedNode>
        } />

        <Route path="/operations" element={<OperationsDashboard />} />
        <Route path="/operations/warehouse" element={<WarehouseView />} />
        <Route path="/operations/orders" element={<Orders />} />
        <Route path="/operations/crm" element={<CRM />} />

        <Route path="/marketing" element={<MarketingPage />} />
        <Route path="/marketing/strategy-report" element={<MarketingStrategyReport />} />
        <Route path="/marketing/brand-voice" element={<BrandVoiceProfile />} />
        <Route path="/marketing/calendar" element={<ContentCalendar />} />

        {/* PRO TIER DASHBOARDS */}
        <Route path="/forecasting" element={
            <LockedNode isLocked={userTier === 'Free Audit'} requiredTier="Margin Protection Pro" onUpgrade={() => navigate('/settings/subscription')}>
                <Forecasting />
            </LockedNode>
        } />

        {/* SETTINGS */}
        <Route path="/settings/account" element={<AccountSettings />} />
        <Route path="/settings/business" element={<BusinessSetup />} />
        <Route path="/settings/subscription" element={<SubscriptionManagement />} />
        <Route path="/settings/integrations" element={<Integrations />} />
        <Route path="/settings/portal" element={<CustomerPortal />} />
        <Route path="/settings/privacy" element={<PrivacyGovernance />} />

        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
      <AIAssistant />
    </Layout>
  );
};

export default function App() {
  return (
    <Router>
        <ArtisanDataProvider>
          <AppContent />
        </ArtisanDataProvider>
    </Router>
  );
}

