    return (
        <nav className="flex items-center space-x-2 text-[10px] font-black uppercase tracking-widest text-gray-400 mb-6 animate-in fade-in">
            <span className="hover:text-[#6A2C91] cursor-pointer">Vault</span>
            {pathnames.map((name, index) => {
                const routeTo = `/${pathnames.slice(0, index + 1).join('/')}`;
                const isLast = index === pathnames.length - 1;
                return (
                    <React.Fragment key={name}>
                        <ChevronRight size={10} />
                        <span className={`${isLast ? 'text-[#C5A059]' : 'hover:text-[#6A2C91] cursor-pointer'}`}>
