 */

export default function Layout({ children }: { children?: React.ReactNode }) {
  const navigate = useNavigate();
  const location = useLocation();
  const { businessProfile, userTier, logout, inventory, orders, getMarginMetrics } = useArtisanData();

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [searchResult, setSearchResult] = useState<string | null>(null);

  // Nav State Groups
  const [openGroups, setOpenGroups] = useState<Record<string, boolean>>({
    dashboard: true,
    operations: true,
    inventory: true,
    marketing: false
  });

  const toggleGroup = (group: string) => {
    setOpenGroups(prev => ({ ...prev, [group]: !prev[group] }));
  };

  const getTierColor = () => {
    if (userTier === 'Margin Protection Pro') return 'text-[#C5A059] bg-[#C5A059]/10 border-[#C5A059]/20';
    if (userTier === 'Artisan Flow Basic') return 'text-[#6A2C91] bg-[#6A2C91]/10 border-[#6A2C91]/20';
    return 'text-slate-500 bg-slate-100 border-slate-200';
  };

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchQuery.trim()) return;
    setIsSearching(true);
    const context = { inventory, orders, margins: getMarginMetrics() };
    const result = await searchBusinessData(searchQuery, context);
    setSearchResult(result || null);
    setIsSearching(false);
    setTimeout(() => setSearchResult(null), 10000);
  };

  const NavItem = ({ to, icon: Icon, label, nested = false }: any) => {
    const isActive = location.pathname === to;
    return (
      <button 
        onClick={() => { navigate(to); setIsMobileMenuOpen(false); }}
        className={`flex items-center w-full px-4 py-2.5 rounded-xl transition-all duration-200 group relative ${
          isActive 
            ? 'bg-purple-50 text-[#6A2C91] font-bold shadow-sm' 
            : 'text-gray-500 hover:bg-stone-50 hover:text-gray-900'
        } ${nested ? 'ml-6 text-xs' : 'text-sm'}`}
      >
        <Icon size={nested ? 16 : 18} className={`mr-3 ${isActive ? 'text-[#6A2C91]' : 'text-gray-400 group-hover:text-[#6A2C91]'}`} />
        <span className="flex-1 text-left">{label}</span>
        {isActive && <div className="w-1.5 h-1.5 rounded-full bg-[#6A2C91] ml-2 animate-pulse"></div>}
      </button>
    );
  };

  const NavGroup = ({ id, label, icon: Icon, children }: any) => {
    const isOpen = openGroups[id];
    return (
      <div className="space-y-1">
        <button 
          onClick={() => toggleGroup(id)}
          className="flex items-center justify-between w-full px-4 py-3 text-sm font-black uppercase tracking-widest text-gray-400 hover:text-[#6A2C91] transition-colors"
        >
          <div className="flex items-center">
            <Icon size={16} className="mr-3" />
            <span>{label}</span>
          </div>
          {isOpen ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
        </button>
        {isOpen && <div className="space-y-1 pb-2">{children}</div>}
      </div>
    );
  };

  const pathnames = location.pathname.split('/').filter(x => x);

  return (
    <div className="flex h-screen w-full bg-stone-50 text-gray-900 font-sans">
      <style>{`
        @keyframes soft-success-glow {
          0% { box-shadow: 0 0 0 0 rgba(120, 190, 32, 0); border-color: transparent; }
          50% { box-shadow: 0 0 20px 5px rgba(120, 190, 32, 0.25); border-color: rgba(120, 190, 32, 0.5); }
          100% { box-shadow: 0 0 0 0 rgba(120, 190, 32, 0); border-color: transparent; }
        }
        .animate-soft-success {
          animation: soft-success-glow 2.5s ease-in-out forwards;
        }
        .sidebar-gradient {
          background: linear-gradient(to bottom, #ffffff, #fafaf9);
        }
      `}</style>

      {/* Mobile Sidebar Overlay */}
      <div 
        className={`fixed inset-0 bg-black/50 backdrop-blur-sm z-40 transition-opacity md:hidden ${isMobileMenuOpen ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`} 
        onClick={() => setIsMobileMenuOpen(false)} 
      />

      {/* Sidebar */}
      <aside className={`fixed md:relative z-50 w-64 h-full border-r border-stone-200 flex flex-col sidebar-gradient shadow-xl md:shadow-none transition-transform duration-300 ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}`}>
        <div className="p-6 border-b border-stone-100 flex flex-col gap-4 sticky top-0 bg-white/80 backdrop-blur-md z-10">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
               <div className="relative shrink-0">
                  <Hexagon size={32} className="text-[#C5A059] fill-[#C5A059]/10" />
                  <div className="absolute inset-0 flex items-center justify-center">
                      <div className="w-2 h-2 bg-[#6A2C91] rounded-full"></div>
                  </div>
               </div>
               <div className="flex-1 min-w-0">
                  <h1 className="font-bold tracking-tight uppercase text-xs text-gray-900 leading-tight truncate">{businessProfile.name}</h1>
                  <span className="text-[9px] font-mono font-bold text-[#6A2C91] tracking-widest uppercase italic">Artisan Flow</span>
               </div>
            </div>
            <button onClick={() => setIsMobileMenuOpen(false)} className="md:hidden text-gray-400">
              <X size={24} />
            </button>
          </div>
          <div className={`px-3 py-1 rounded-full border text-[9px] font-black uppercase tracking-[0.1em] flex items-center gap-1.5 w-fit ${getTierColor()}`}>
             <Crown size={10} /> {userTier}
