    industry: 'Skincare',
    tier: 'Free Audit',
    status: 'Active',
    brandVoice: { adjectives: ['Artisanal', 'Luxurious'], restrictedWords: [] },
    receptionistLogic: { qualificationQuestions: [] }
  });

  const [inventory, setInventory] = useState<InventoryItem[]>([
    { id: 1, name: '100% Grain Alcohol', sku: '576764A', stock: 23, unit: 'oz', unitCost: 0.77, stockValue: 17.71, reorderPoint: 10, type: 'raw' },
    { id: 2, name: 'Rosemary Leaf', sku: 'Herb-115', stock: 6, unit: 'oz', unitCost: 2.50, stockValue: 15.00, reorderPoint: 10, type: 'raw', lowStock: true },
    { id: 101, name: 'Lavender Rose SOAP', sku: '3', stock: 7, unit: 'piece', unitCost: 3.20, retailPrice: 8.00, stockValue: 22.40, reorderPoint: 20, type: 'finished', category: 'Soaps' },
    { id: 102, name: 'Turmeric Myrrh Soap', sku: '53', stock: 12, unit: 'piece', unitCost: 3.50, retailPrice: 9.00, stockValue: 42.00, reorderPoint: 15, type: 'finished', category: 'Soaps' },
  ]);

  const [orders] = useState<Order[]>([
    { id: '#13086', customer: 'RJ Baise', email: 'rj.baise@me.com', date: new Date().toLocaleDateString(), location: 'Cave City, KY', status: 'Processing', platform: 'Direct', total: 24.59, items: [{ name: 'Turmeric Myrrh Soap', qty: 10, price: 6.15 }] }
  ]);

  const [reports, setReports] = useState<Report[]>([]);
  const [productionStats, setProductionStats] = useState({ active: 1, inProgress: 1, awaiting: 0, completed: 0, pending: 2 });
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [marketingPosts, setMarketingPosts] = useState<MarketingPost[]>([]);
  const [qualityChecks, setQualityChecks] = useState<QualityCheck[]>([]);
  const [locations, setLocations] = useState<Location[]>([]);
  const [supplierCommunications, setSupplierCommunications] = useState<SupplierCommunication[]>([]);
  const [recipes] = useState<Recipe[]>([]);

  const [integrations] = useState<Integration[]>([
    { id: '1', name: 'WooCommerce', category: 'E-commerce', status: 'Connected', logo: 'https://upload.wikimedia.org/wikipedia/commons/2/2a/WooCommerce_logo.svg', description: 'Real-time omnichannel stock synchronization.' },
    { id: '2', name: 'Shopify', category: 'E-commerce', status: 'Connect', logo: 'https://upload.wikimedia.org/wikipedia/commons/0/0e/Shopify_logo_2018.svg', description: 'Deep integration for orders and fulfillment.' },
    { id: '3', name: 'Etsy', category: 'E-commerce', status: 'Connect', logo: 'https://upload.wikimedia.org/wikipedia/commons/8/89/Etsy_logo.svg', description: 'Artisan marketplace order ingesting.' }
  ]);

  useEffect(() => {
    const verifySession = async () => {
      if (isAuthenticated) {
        setIsSessionVerifying(true);
        console.log(`[ArtisanFlow] Pinging Google Sheet for session verification: ${SHEET_URL}`);
        await new Promise(r => setTimeout(r, 1200));
        console.log(`[ArtisanFlow] Handshake Success. User Status: ACTIVE. Tier: ${userTier}`);

        // Populate critical demand insights for the dashboard safely
        setDemandInsights([
            { id: '1', material: 'Shea Butter', isCritical: true, recommendedBatch: 250, daysRemaining: 4 },
            { id: '2', material: 'Rosemary Leaf', isCritical: true, recommendedBatch: 50, daysRemaining: 2 }
        ]);
        setIsSessionVerifying(false);
      }
    };
    verifySession();
  }, [isAuthenticated, userTier]);

  const login = async (email: string, pass: string) => {
    setIsAuthenticated(true);
    return true;
  };

  const googleLogin = async () => {
    setIsAuthenticated(true);
  };

  const logout = () => {
    setIsAuthenticated(false);
  };

  const signUp = async (data: any) => {
    console.log(`[ArtisanFlow] Appending user metadata to Google Sheet: ${SHEET_URL}`);
    setBusinessProfile(prev => ({ ...prev, ...data }));
    setUserTier(data.tier);
    setIsAuthenticated(true);
  };

  const updateTier = async (tier: UserTier) => {
    console.log(`[ArtisanFlow] Updating Tier in Google Sheet to: ${tier}`);
    setUserTier(tier);
    setBusinessProfile(prev => ({ ...prev, tier }));
  };

  const updateBusinessProfile = (updates: Partial<BusinessProfile>) => setBusinessProfile(prev => ({ ...prev, ...updates }));

  const getInventoryValue = () => inventory.reduce((acc, i) => acc + (i.stock * i.unitCost), 0);
  const getTotalRevenue = () => orders.reduce((acc, o) => acc + o.total, 0);

  const getMarginMetrics = () => {
    const finished = inventory.filter(i => i.type === 'finished');
    if (finished.length === 0) return { isMarginHealthy: true, marginMultiplier: 2.2 };
    const avgMultiplier = finished.reduce((acc, i) => acc + (i.retailPrice && i.unitCost ? i.retailPrice / i.unitCost : 2.2), 0) / finished.length;
    return { isMarginHealthy: avgMultiplier >= 2.2, marginMultiplier: avgMultiplier };
  };

  const saveReport = (r: any) => setReports(prev => [{ ...r, id: Date.now().toString() }, ...prev]);
  const deleteReport = (id: string) => setReports(prev => prev.filter(r => r.id !== id));

  const importData = async (files: File[]) => {
      await new Promise(r => setTimeout(r, 1000));
      return true;
  };

  const addInventoryItem = (item: any) => setInventory(prev => [...prev, { ...item, id: Date.now(), stockValue: (item.stock || 0) * (item.unitCost || 0) }]);
  const addSupplier = (s: any) => setSuppliers(prev => [...prev, { ...s, id: Date.now().toString() }]);
  const addLocation = (l: any) => setLocations(prev => [...prev, { ...l, id: Date.now().toString() }]);
  const addCommunication = (c: any) => setSupplierCommunications(prev => [...prev, { ...c, id: Date.now().toString() }]);
  const addQualityCheck = (q: any) => setQualityChecks(prev => [...prev, { ...q, id: Date.now().toString() }]);
  const addMarketingPost = (p: any) => setMarketingPosts(prev => [...prev, { ...p, id: Date.now().toString() }]);
  const addAppointment = (app: Omit<Appointment, 'id'>) => setAppointments(prev => [...prev, { ...app, id: Date.now().toString() }]);
  const updateMarketingPost = (id: string, updates: any) => setMarketingPosts(prev => prev.map(post => post.id === id ? { ...post, ...updates } : post));
  const generateSchedule = () => setProductionStats(prev => ({ ...prev, active: prev.active + 1 }));
  const processOrder = (id: string) => console.log("Processing order", id);
  const syncWooCommerce = async () => ({ success: true, count: 0 });

  return (
    <DataContext.Provider value={{ 
      inventory, orders, businessProfile, isAuthenticated, userTier, reports, productionStats,
      suppliers: suppliers || [], 
      marketingPosts: marketingPosts || [], 
      integrations: integrations || [], 
      qualityChecks: qualityChecks || [], 
      locations: locations || [], 
      supplierCommunications: supplierCommunications || [], 
      recipes: recipes || [], 
      appointments: appointments || [], 
      isSessionVerifying, 
      demandInsights: demandInsights || [],
      login, googleLogin, logout, signUp, updateTier, updateBusinessProfile,
      getInventoryValue, getTotalRevenue, getMarginMetrics, saveReport, deleteReport,
      importData, addInventoryItem, addSupplier, addLocation, addCommunication, addQualityCheck, addMarketingPost, addAppointment, updateMarketingPost, 
      generateSchedule, processOrder, syncWooCommerce
    }}>
      {children}
    </DataContext.Provider>
  );
};

export const useArtisanData = () => {
  const context = useContext(DataContext);
  if (!context) throw new Error('useArtisanData must be used within ArtisanDataProvider');
  return context;
};

import React, { useState, useEffect } from 'react';
import { Card, Button, Badge, Input, Select } from './UI';
import { Search, Filter, ShoppingCart, DollarSign, Package, Truck, User, MapPin, Calendar, CheckCircle, Download, RefreshCw, AlertCircle, X, ChevronRight, ArrowLeft } from 'lucide-react';
import { useArtisanData } from './DataContext';
