            <NavGroup id="operations" label="Manufacturing" icon={Factory}>
              <NavItem to="/operations" label="Operations Hub" icon={Boxes} />
              <NavItem to="/operations/orders" label="Orders & Sync" icon={ShoppingBag} nested />
              <NavItem to="/operations/crm" label="CRM" icon={User} nested />
              <NavItem to="/operations/warehouse" label="Virtual Warehouse" icon={MapPin} nested />
