                  <span className="hover:text-[#6A2C91] cursor-pointer transition-colors" onClick={() => navigate('/')}>Vault</span>
                  {pathnames.map((name, index) => {
                      const routeTo = `/${pathnames.slice(0, index + 1).join('/')}`;
                      const isLast = index === pathnames.length - 1;
                      return (
                          <React.Fragment key={name}>
                              <ChevronRight size={12} className="text-stone-300" />
                              <span className={`${isLast ? 'text-[#C5A059]' : 'hover:text-[#6A2C91] cursor-pointer transition-colors'}`} onClick={() => !isLast && navigate(routeTo)}>
