        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const systemPrompt = `
            You are the ArtisanFlow Synaptic Search Engine. 
            Analyze the provided business context and answer the query concisely.
            If the user asks for specific metrics (margins, stock levels, revenue), calculate them from the data.
