export const generateMarketingStrategy = async (data: any, tier?: string) => { 
  try {
    // Create a new GoogleGenAI instance right before making an API call to ensure it always uses the most up-to-date API key.
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `Analyze this business pulse data and generate a marketing strategy. Tier: ${tier || 'Standard'}. Data: ${JSON.stringify(data)}`;
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { systemInstruction: "You are a senior marketing strategist specializing in artisan brands." },
    });
    const lines = response.text?.split('\n').filter(l => l.trim().length > 5) || [];
    return { strategy: lines.length > 0 ? lines : ["Focus on high-margin product bundling."] };
  } catch (error) {
    return { strategy: ["The AI generator is currently experiencing heavy load."] };
  }
};

