export const generateFinancialAnalysis = async (orders: any[], inventory: any[], periodYears: number = 1) => {
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const systemPrompt = `
            You are a world-class CFO and Financial Architect. 
            Analyze the following business data and project financial performance for the next ${periodYears} years.

            ORDERS HISTORY: ${JSON.stringify(orders)}
            INVENTORY STATUS: ${JSON.stringify(inventory)}

            Deliver a JSON object containing:
            1. 'summary': 2-3 sentences on financial health.
            2. 'projections': Array of yearly objects with 'year', 'projectedRevenue', 'projectedExpenses', 'projectedProfit'.
            3. 'recommendations': Array of 3 strategic financial moves.
            4. 'riskLevel': 'Low', 'Medium', or 'High' based on burn rates.
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Generate a financial projection for ${periodYears} years.`,
            config: { 
                systemInstruction: systemPrompt,
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        summary: { type: Type.STRING },
                        projections: {
                            type: Type.ARRAY,
                            items: {
                                type: Type.OBJECT,
                                properties: {
                                    year: { type: Type.NUMBER },
                                    projectedRevenue: { type: Type.NUMBER },
                                    projectedExpenses: { type: Type.NUMBER },
                                    projectedProfit: { type: Type.NUMBER }
                                }
                            }
                        },
                        recommendations: {
                            type: Type.ARRAY,
                            items: { type: Type.STRING }
                        },
                        riskLevel: { type: Type.STRING }
                    }
                }
            }
        });

        return JSON.parse(response.text || "{}");
