        {isActive && <div className="absolute right-0 top-0 h-full w-1.5 bg-amber-400"></div>}
      </button>
    );
  };

  const NavGroup = ({ id, label, icon: Icon, children }: any) => {
    const isOpen = openGroups[id];
    return (
      <div className="space-y-1">
        <button 
          onClick={() => toggleGroup(id)}
