                  <span className="hover:text-[#6A2C91] cursor-pointer transition-colors" onClick={() => navigate('/')}>Vault</span>
                  {pathnames.map((name, index) => {
                      const routeTo = `/${pathnames.slice(0, index + 1).join('/')}`;
