                  <span className="text-[10px] font-mono font-black text-[#C5A059] tracking-widest uppercase block mt-0.5">Systems Architect</span>
               </div>
            </div>
            <button onClick={() => setIsMobileMenuOpen(false)} className="md:hidden text-gray-400 hover:text-red-500 transition-colors">
              <X size={24} />
            </button>
          </div>
          <div className={`px-4 py-1.5 rounded-full border text-[9px] font-black uppercase tracking-[0.2em] flex items-center gap-2 w-fit shadow-inner ${getTierColor()}`}>
             <Crown size={12} /> {userTier}
          </div>
        </div>

        <nav className="flex-1 px-4 py-8 space-y-6 overflow-y-auto scrollbar-hide">
            <NavGroup id="dashboard" label="Synaptic Path" icon={LayoutDashboard}>
              <NavItem to="/" label="Overview" icon={Activity} />
              <NavItem to="/command-center" label="Command Center" icon={LayoutDashboard} />
            </NavGroup>

            <NavGroup id="operations" label="Manufacturing" icon={Factory}>
              <NavItem to="/operations" label="Operations Hub" icon={Boxes} />
              <NavItem to="/operations/orders" label="Orders & Sync" icon={ShoppingBag} nested />
              <NavItem to="/operations/crm" label="CRM" icon={User} nested />
              <NavItem to="/operations/warehouse" label="Virtual Warehouse" icon={MapPin} nested />
            </NavGroup>

            <NavGroup id="inventory" label="Resource Hub" icon={Package}>
              <NavItem to="/inventory" label="Inventory Hub" icon={Package} />
              <NavItem to="/recipes" label="Recipes (BOM)" icon={FileText} nested />
              <NavItem to="/supplier_manager" label="Suppliers" icon={Truck} nested />
              <NavItem to="/qc" label="Quality Control" icon={ClipboardList} nested />
            </NavGroup>

            <NavGroup id="marketing" label="Growth Studio" icon={Sparkles}>
              <NavItem to="/marketing" label="Marketing Studio" icon={Sparkles} />
              <NavItem to="/finance" label="Business Finance" icon={DollarSign} nested />
              <NavItem to="/marketing/strategy-report" label="Strategy Report" icon={Target} nested />
              <NavItem to="/marketing/brand-voice" label="Brand Voice" icon={Volume2} nested />
              <NavItem to="/marketing/calendar" label="Content Calendar" icon={Calendar} nested />
            </NavGroup>

            <NavGroup id="settings" label="System Protocols" icon={Settings}>
              <NavItem to="/settings/business" label="Enterprise Setup" icon={Hexagon} nested />
