        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 overflow-auto relative bg-stone-50 flex flex-col">
        {/* TOP BAR: SYNAPTIC HEADER */}
        <header className="sticky top-0 z-30 w-full bg-white/80 backdrop-blur-xl border-b border-stone-200 px-10 py-5 flex items-center justify-between gap-12">
            <div className="flex items-center gap-8">
              <button onClick={() => setIsMobileMenuOpen(true)} className="md:hidden p-2 -ml-2 text-gray-600">
                <Menu size={24} />
              </button>
              {/* Breadcrumbs - Path Navigator */}
              <nav className="flex items-center space-x-3 text-[10px] font-black uppercase tracking-[0.2em] text-gray-400">
                  <span className="hover:text-[#6A2C91] cursor-pointer transition-colors" onClick={() => navigate('/')}>Vault</span>
                  {pathnames.map((name, index) => {
                      const routeTo = `/${pathnames.slice(0, index + 1).join('/')}`;
                      const isLast = index === pathnames.length - 1;
                      return (
                          <React.Fragment key={name}>
                              <ChevronRight size={12} className="text-stone-300" />
                              <span className={`${isLast ? 'text-[#C5A059]' : 'hover:text-[#6A2C91] cursor-pointer transition-colors'}`} onClick={() => !isLast && navigate(routeTo)}>
                                  {name.replace(/[-_]/g, ' ')}
                              </span>
                          </React.Fragment>
                      );
                  })}
              </nav>
            </div>

            {/* Global AI Search Gateway */}
            <form onSubmit={handleSearch} className="flex-1 max-w-2xl relative group">
