 */
export const generateFinancialAnalysis = async (orders: any[], inventory: any[], periodYears: number = 5) => {
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const systemPrompt = `
            You are a world-class CFO and Financial Architect. 
            Analyze the following business data and project financial performance for the next ${periodYears} years.

            GOAL: Create a strategy to bring the business to a 'Balanced State' and scale using a Dropshipping model.

            ORDERS HISTORY: ${JSON.stringify(orders)}
            INVENTORY STATUS: ${JSON.stringify(inventory)}

            Deliver a JSON object containing:
            1. 'summary': Executive overview of current state vs. target balance.
            2. 'projections': Array of yearly objects with 'year', 'projectedRevenue', 'projectedProfit'.
            3. 'dropshippingEstimates': Array of yearly objects with 'year', 'estRevenue', 'estProfit' IF the dropshipping strategy is followed.
            4. 'recoveryPlans': Object with 'oneYear', 'threeYear', and 'fiveYear' plans to reach balance.
            5. 'riskLevel': 'Low', 'Medium', or 'High'.
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: `Generate a 5-year recovery and dropshipping scale-up projection.`,
            config: { 
                systemInstruction: systemPrompt,
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        summary: { type: Type.STRING },
                        riskLevel: { type: Type.STRING },
                        recoveryPlans: {
                            type: Type.OBJECT,
                            properties: {
                                oneYear: { type: Type.STRING },
                                threeYear: { type: Type.STRING },
                                fiveYear: { type: Type.STRING }
                            },
                            required: ["oneYear", "threeYear", "fiveYear"]
                        },
                        projections: {
                            type: Type.ARRAY,
                            items: {
                                type: Type.OBJECT,
                                properties: {
                                    year: { type: Type.NUMBER },
                                    projectedRevenue: { type: Type.NUMBER },
                                    projectedProfit: { type: Type.NUMBER }
                                }
                            }
                        },
                        dropshippingEstimates: {
                            type: Type.ARRAY,
                            items: {
                                type: Type.OBJECT,
                                properties: {
                                    year: { type: Type.NUMBER },
                                    estRevenue: { type: Type.NUMBER },
                                    estProfit: { type: Type.NUMBER }
                                }
                            }
                        }
                    }
                }
            }
        });

        return JSON.parse(response.text || "{}");
    } catch (e) {
        console.error("Finance AI error", e);
        return null;
    }
};

