export const QualityControl = () => {
  const { qualityChecks, addQualityCheck, inventory } = useArtisanData();
  const [searchTerm, setSearchTerm] = useState('');
  const [showAdd, setShowAdd] = useState(false);
  const navigate = useNavigate();

  const [newCheck, setNewCheck] = useState<Partial<QualityCheck>>({
      productName: '', batchNumber: '', status: 'Pending', inspector: '', date: new Date().toLocaleDateString()
  });

  const handleAdd = () => {
      if(!newCheck.productName) return;
      addQualityCheck(newCheck as any);
      setShowAdd(false);
      setNewCheck({ productName: '', batchNumber: '', status: 'Pending', inspector: '' });
  };

  const passRate = qualityChecks.length > 0 
    ? Math.round((qualityChecks.filter(c => c.status === 'Passed').length / qualityChecks.length) * 100) 
    : 100;

  return (
    <div className="p-6 space-y-10 animate-in fade-in pb-20">
      <Modal isOpen={showAdd} onClose={() => setShowAdd(false)} title="Initialize Integrity Inspection">
          <div className="space-y-6 p-2">
              <Select value={newCheck.productName} onChange={e => setNewCheck({...newCheck, productName: e.target.value})}>
                  <option value="">Select Asset...</option>
                  {inventory.map(i => <option key={i.id} value={i.name}>{i.name} ({i.sku})</option>)}
              </Select>
              <div className="grid grid-cols-2 gap-4">
                  <Input placeholder="Batch Code" value={newCheck.batchNumber} onChange={e => setNewCheck({...newCheck, batchNumber: e.target.value})} />
                  <Input placeholder="Sign-off Name" value={newCheck.inspector} onChange={e => setNewCheck({...newCheck, inspector: e.target.value})} />
              </div>
              <Select value={newCheck.status} onChange={e => setNewCheck({...newCheck, status: e.target.value as any})}>
                  <option>Pending</option>
                  <option>Passed</option>
                  <option>Failed</option>
              </Select>
              <Button onClick={handleAdd} className="w-full bg-[#6A2C91] text-white h-14 rounded-2xl font-black text-xs tracking-widest shadow-xl mt-4 uppercase">
                  LOG INSPECTION DATA
              </Button>
          </div>
      </Modal>

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
        <div>
            <h1 className="text-4xl font-black text-gray-900 tracking-tighter uppercase italic">Quality Control Hub</h1>
            <p className="text-gray-500 font-medium">Batch Integrity Vault: Enforcing Excellence Across the Manufacturing Floor.</p>
        </div>
        <Button className="bg-[#6A2C91] text-white h-12 rounded-2xl font-black text-[10px] tracking-widest px-8 shadow-xl" onClick={() => setShowAdd(true)}>
            <Plus size={16} className="mr-2" /> NEW INSPECTION
        </Button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          <StatBox label="Total Audits" val={qualityChecks.length} color="text-purple-600" />
          <StatBox label="Pass Velocity" val={`${passRate}%`} color="text-emerald-600" />
          <StatBox label="Failure Waste" val="$0.00" color="text-red-500" />
          <StatBox label="Pending QA" val={qualityChecks.filter(c => c.status === 'Pending').length} color="text-amber-500" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-2">
              <Card title="Inspection Ledger" className="rounded-[2.5rem] min-h-[400px] border-stone-100">
                  {qualityChecks.length === 0 ? (
                      <div className="flex flex-col items-center justify-center py-20 text-center bg-stone-50 rounded-[2rem] border border-dashed border-stone-200">
                          <ClipboardCheck size={48} className="text-stone-200 mb-4" />
                          <p className="text-gray-400 font-black text-[10px] uppercase tracking-widest italic">No inspection history detected in vault.</p>
                      </div>
                  ) : (
                      <div className="divide-y divide-stone-50">
                          {qualityChecks.map(check => (
                              <div key={check.id} className="py-6 flex items-center justify-between group">
                                  <div className="flex items-center gap-5">
                                      <div className={`p-3 rounded-2xl ${check.status === 'Passed' ? 'bg-emerald-50 text-emerald-600' : 'bg-amber-50 text-amber-500'}`}>
                                          {check.status === 'Passed' ? <ShieldCheck size={20}/> : <Clock size={20}/>}
                                      </div>
                                      <div>
                                          <h4 className="font-black text-gray-900 uppercase italic tracking-tight">{check.productName}</h4>
                                          <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest">Batch: {check.batchNumber} • Sign-off: {check.inspector}</p>
                                      </div>
                                  </div>
                                  <Badge color={check.status === 'Passed' ? 'green' : 'gold'} className="px-4 py-1 uppercase font-black text-[9px] tracking-widest">{check.status}</Badge>
                              </div>
                          ))}
                      </div>
                  )}
              </Card>
          </div>

          <div className="lg:col-span-1 space-y-6">
              <div className="bg-stone-900 rounded-[2.5rem] p-10 text-white relative overflow-hidden shadow-2xl">
                  <div className="absolute bottom-0 right-0 p-10 opacity-10"><History size={120} /></div>
                  <h4 className="text-2xl font-black uppercase italic tracking-tighter mb-4">Integrity Historicals</h4>
                  <p className="text-stone-400 text-sm leading-relaxed mb-8">No critical batch failures detected in the last 180 days.</p>
                  <Button variant="outline" className="w-full border-stone-700 text-white font-black text-[10px] tracking-widest h-12 rounded-2xl hover:bg-stone-800 transition-all uppercase">DOWNLOAD ARCHIVE</Button>
              </div>
          </div>
      </div>
    </div>
