              <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Primary Liaison</label>
                  <Input placeholder="Primary Liaison" value={formData.contactName} onChange={e => setFormData({...formData, contactName: e.target.value})} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Secure Email</label>
                    <Input placeholder="Secure Email" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} />
