              <Button onClick={handleCommit} className="w-full bg-[#6A2C91] text-white h-14 rounded-2xl font-black text-xs tracking-widest shadow-xl mt-4 uppercase">
                  {isEditing ? <><RefreshCw size={18} className="mr-2"/> UPDATE VENDOR NODE</> : <><ShieldCheck size={18} className="mr-2"/> AUTHORIZE VENDOR</>}
