interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'ghost' | 'outline' | 'premium' | 'danger';
  children: React.ReactNode;
}

export const Button: React.FC<ButtonProps> = ({ variant = 'primary', className = '', children, style, ...props }) => {
  const baseStyle = "px-6 py-2 rounded-md font-medium transition-all duration-300 flex items-center justify-center gap-2 uppercase tracking-wide text-sm";

  let variantClass = "";

  if (variant === 'primary') {
    variantClass = "bg-[#6A2C91] text-white hover:bg-[#5a257a] shadow-md";
  } else if (variant === 'premium') {
    variantClass = "bg-[#C5A059] text-white hover:bg-[#b08e4d] shadow-lg shadow-[#C5A059]/20";
  } else if (variant === 'secondary') {
    variantClass = "bg-white text-[#6A2C91] border border-[#6A2C91]/30 hover:bg-purple-50";
  } else if (variant === 'outline') {
    variantClass = "border border-gray-300 text-gray-700 hover:bg-gray-50";
  } else if (variant === 'danger') {
    variantClass = "bg-red-50 text-red-600 border border-red-100 hover:bg-red-100 shadow-sm";
  } else {
    variantClass = "text-gray-500 hover:bg-gray-100 hover:text-gray-900";
  }

  return (
    <button 
      className={`${baseStyle} ${variantClass} ${className}`} 
      style={style}
      {...props}
    >
      {children}
    </button>
  );
};

