// --- RECEPTIONIST LOGIC ---
export const ReceptionistLogic = () => {
    const navigate = useNavigate();
    const { businessProfile, updateBusinessProfile } = useArtisanData();
    const [questions, setQuestions] = useState<string[]>(businessProfile.receptionistLogic?.qualificationQuestions || ['', '', '']);
    const [isSaving, setIsSaving] = useState(false);

    const handleQuestionChange = (index: number, value: string) => {
        const newQs = [...questions];
        newQs[index] = value;
        setQuestions(newQs);
    };

    const addQuestion = () => {
        if (questions.length < 5) {
            setQuestions([...questions, '']);
        }
    };

    const removeQuestion = (index: number) => {
        if (questions.length > 3) {
            setQuestions(questions.filter((_, i) => i !== index));
        }
    };

    const handleSave = () => {
        setIsSaving(true);
        updateBusinessProfile({
            receptionistLogic: {
                qualificationQuestions: questions.filter(q => q.trim() !== '')
            }
        });
        setTimeout(() => {
            setIsSaving(false);
            alert("Receptionist Logic saved successfully.");
        }, 600);
    };

    return (
        <div className="p-6 space-y-6 animate-in fade-in pb-20">
            <button onClick={() => navigate('/marketing')} className="flex items-center gap-2 text-gray-500 hover:text-[#6A2C91] font-medium">
                <ArrowLeft size={18} /> Back
            </button>
            <div className="flex items-center gap-3 mb-6">
                <div className="p-3 bg-white border border-gray-200 rounded-xl text-purple-600 shadow-sm">
                    <Headphones size={24} />
                </div>
                <div>
                    <h1 className="text-3xl font-bold text-gray-900">Receptionist Logic</h1>
                    <p className="text-gray-500">Screen leads with automated qualification questions before scheduling</p>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                <div className="lg:col-span-2">
                    <Card title="Qualification Questions">
                        <p className="text-sm text-gray-500 mb-6 uppercase tracking-tight font-medium">Define 3-5 questions the AI agent will ask to screen leads.</p>
                        <div className="space-y-4">
                            {questions.map((q, idx) => (
                                <div key={idx} className="flex items-start gap-3">
                                    <div className="flex-none w-8 h-10 flex items-center justify-center bg-gray-100 rounded text-xs font-bold text-gray-400">
                                        {idx + 1}
                                    </div>
                                    <div className="flex-1">
                                        <textarea 
                                            className="w-full bg-white border border-gray-200 text-gray-900 p-3 rounded-lg focus:outline-none focus:border-[#6A2C91] h-20 resize-none shadow-sm font-sans text-sm"
                                            placeholder="e.g. What is your monthly production volume?"
                                            value={q}
                                            onChange={e => handleQuestionChange(idx, e.target.value)}
                                        />
                                    </div>
                                    {questions.length > 3 && (
                                        <button onClick={() => removeQuestion(idx)} className="mt-2 text-gray-400 hover:text-red-500 transition-colors">
                                            <Trash2 size={18} />
                                        </button>
                                    )}
                                </div>
                            ))}

                            {questions.length < 5 && (
                                <button 
                                    onClick={addQuestion}
                                    className="w-full py-3 border-2 border-dashed border-gray-200 rounded-xl text-gray-400 hover:text-[#6A2C91] hover:border-[#6A2C91] hover:bg-purple-50 transition-all font-medium flex items-center justify-center gap-2"
                                >
                                    <Plus size={18} /> Add Question
                                </button>
                            )}
                        </div>
                    </Card>
                </div>

                <div className="lg:col-span-1 space-y-6">
                    <Card title="Agent Behavior">
                        <div className="space-y-4">
                            <div className="p-4 bg-purple-50 rounded-xl border border-purple-100">
                                <h4 className="text-sm font-bold text-purple-900 mb-2">Lead Scoring</h4>
                                <p className="text-xs text-purple-800 leading-relaxed">
                                    The AI agent will analyze answers to these questions to determine lead quality. High-scoring leads are immediately shown your available calendar slots.
                                </p>
                            </div>
                            <div className="p-4 bg-gray-50 rounded-xl border border-gray-200">
                                <h4 className="text-sm font-bold text-gray-900 mb-2">Screening Workflow</h4>
                                <ul className="text-xs text-gray-600 space-y-2">
                                    <li className="flex gap-2">
                                        <div className="w-4 h-4 bg-green-500 rounded-full flex-none mt-0.5" />
                                        <span>Agent introduces brand and greets visitor.</span>
                                    </li>
                                    <li className="flex gap-2">
                                        <div className="w-4 h-4 bg-green-500 rounded-full flex-none mt-0.5" />
                                        <span>Agent asks defined qualification questions.</span>
                                    </li>
                                    <li className="flex gap-2">
                                        <div className="w-4 h-4 bg-green-500 rounded-full flex-none mt-0.5" />
                                        <span>Agent evaluates fit and redirects to calendar.</span>
                                    </li>
                                </ul>
                            </div>
                        </div>
                    </Card>

                    <Button onClick={handleSave} disabled={isSaving} className="w-full bg-[#6A2C91] text-white">
                        {isSaving ? 'Saving...' : 'Save Receptionist Logic'}
                    </Button>
                </div>
            </div>
        </div>
    );
};

// --- BRAND VOICE PROFILE ---
export const BrandVoiceProfile = () => {
    const navigate = useNavigate();
    const { businessProfile, updateBusinessProfile } = useArtisanData();
    const [adjectives, setAdjectives] = useState<string[]>(businessProfile.brandVoice?.adjectives || ['', '', '', '', '']);
    const [restrictedInput, setRestrictedInput] = useState<string>(businessProfile.brandVoice?.restrictedWords?.join(', ') || '');
    const [isSaving, setIsSaving] = useState(false);

    const handleAdjectiveChange = (index: number, value: string) => {
        const newAds = [...adjectives];
        newAds[index] = value;
        setAdjectives(newAds);
    };

    const handleSave = () => {
        setIsSaving(true);
        const restrictedWords = restrictedInput.split(',').map(s => s.trim()).filter(s => s !== '');
        updateBusinessProfile({
            brandVoice: {
                adjectives: adjectives.filter(a => a.trim() !== ''),
                restrictedWords
            }
        });
        setTimeout(() => {
            setIsSaving(false);
            alert("Brand Voice Profile saved successfully.");
        }, 600);
    };

    return (
        <div className="p-6 space-y-6 animate-in fade-in pb-20">
            <button onClick={() => navigate('/marketing')} className="flex items-center gap-2 text-gray-500 hover:text-[#6A2C91] font-medium">
                <ArrowLeft size={18} /> Back
            </button>
            <div className="flex items-center gap-3 mb-6">
                <div className="p-3 bg-white border border-gray-200 rounded-xl text-indigo-600 shadow-sm">
                    <Volume2 size={24} />
                </div>
                <div>
                    <h1 className="text-3xl font-bold text-gray-900">Brand Voice Profile</h1>
                    <p className="text-gray-500">Define the character and constraints of your AI-generated content</p>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <Card title="Core Adjectives">
                    <p className="text-sm text-gray-500 mb-6 uppercase tracking-tight font-medium">Define 5 key traits that describe your brand personality.</p>
                    <div className="space-y-3">
                        {adjectives.map((adj, idx) => (
                            <div key={idx} className="flex items-center gap-3">
                                <span className="text-xs font-bold text-gray-400 w-4">{idx + 1}.</span>
                                <Input 
                                    placeholder="e.g. Professional, Witty..." 
                                    value={adj} 
                                    onChange={e => handleAdjectiveChange(idx, e.target.value)}
                                />
                            </div>
                        ))}
                    </div>
                </Card>

                <Card title="Restricted Vocabulary">
                    <p className="text-sm text-gray-500 mb-6 uppercase tracking-tight font-medium">List words or phrases the AI should never use (comma separated).</p>
                    <textarea 
                        className="w-full bg-white border border-gray-200 text-gray-900 p-3 rounded-lg focus:outline-none focus:border-[#6A2C91] h-48 resize-none shadow-sm font-sans"
                        placeholder="cheap, basic, overpriced, low-end..."
                        value={restrictedInput}
                        onChange={e => setRestrictedInput(e.target.value)}
                    />
                </Card>
            </div>

            <div className="flex justify-end">
                <Button onClick={handleSave} disabled={isSaving} className="bg-[#6A2C91] text-white">
                    {isSaving ? 'Saving...' : 'Save Voice Profile'}
                </Button>
            </div>
        </div>
    );
};

