// --- MARKETING CREATOR (Image Gen) ---
export const MarketingCreator = () => {
    const navigate = useNavigate();
    const { addMarketingPost } = useArtisanData();
    const [isGenerating, setIsGenerating] = useState(false);
    const [topic, setTopic] = useState('');
    const [assetType, setAssetType] = useState('Product Photo');
    const [style, setStyle] = useState('Photorealistic');
    const [generatedImage, setGeneratedImage] = useState<string | null>(null);
    const [aspectRatio, setAspectRatio] = useState('1:1');

    const handleGenerate = async () => {
        if (!topic) return alert("Please enter a topic.");
        if ((window as any).aistudio) {
             const hasKey = await (window as any).aistudio.hasSelectedApiKey();
             if (!hasKey) { await (window as any).aistudio.openSelectKey(); }
        }
        setIsGenerating(true);
        setGeneratedImage(null);
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const prompt = `Generate a high-quality ${style} image for a ${assetType}. Subject: ${topic}.`;
            const response = await ai.models.generateContent({
                model: 'gemini-3-pro-image-preview',
                contents: { parts: [{ text: prompt }] },
                config: { imageConfig: { imageSize: '4K', aspectRatio: aspectRatio as any } }
            });
             if (response.candidates?.[0]?.content?.parts) {
                for (const part of response.candidates[0].content.parts) {
                    if (part.inlineData) {
                        setGeneratedImage(`data:image/png;base64,${part.inlineData.data}`);
                        break;
                    }
                }
            }
        } catch (error: any) {
            console.error("Generation failed", error);
            if (error.message && (error.message.includes('403') || error.status === 403 || error.message.includes('Requested entity was not found.'))) {
                 alert("Permission denied or API key invalid. Please select a valid paid API key.");
                 if ((window as any).aistudio) (window as any).aistudio.openSelectKey();
            } else { alert("Generation failed. Please try again."); }
        } finally { setIsGenerating(false); }
    };

    const handleSave = () => {
        if (!generatedImage) return;
        addMarketingPost({
            platform: 'Instagram', topic: topic || 'Marketing Asset',
            content: `New ${assetType}: ${topic}`,
            scheduledDate: new Date().toISOString().split('T')[0],
            status: 'Draft', type: 'Image', mediaUrl: generatedImage
        });
        navigate('/marketing/approvals');
    };

    return (
        <div className="p-6 space-y-6 animate-in fade-in pb-20">
             <div>
                <button onClick={() => navigate('/marketing')} className="flex items-center gap-2 text-gray-500 hover:text-[#6A2C91] mb-2 font-medium">
                    <ArrowLeft size={18} /> Back
                </button>
                <div className="flex items-center gap-3 mb-6">
                    <div className="p-3 bg-white border border-gray-200 rounded-xl text-amber-500 shadow-sm">
                        <Image size={24} />
                    </div>
                    <div>
                        <h1 className="text-3xl font-bold text-gray-900">Marketing Creator</h1>
                        <p className="text-gray-500">Generate stunning marketing assets with AI</p>
                    </div>
                </div>
            </div>
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <Card title="Asset Configuration">
                    <div className="space-y-4">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Asset Type</label>
                            <Select value={assetType} onChange={(e) => setAssetType(e.target.value)}>
                                <option>Product Photo</option>
                                <option>Social Media Post</option>
                                <option>Email Header</option>
                            </Select>
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Aspect Ratio</label>
                            <Select value={aspectRatio} onChange={(e) => setAspectRatio(e.target.value)}>
                                <option value="1:1">Square (1:1)</option>
                                <option value="16:9">Landscape (16:9)</option>
                                <option value="9:16">Portrait (9:16)</option>
                            </Select>
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Style</label>
                            <Select value={style} onChange={(e) => setStyle(e.target.value)}>
                                <option>Photorealistic</option>
                                <option>Minimalist</option>
                                <option>Vibrant</option>
                            </Select>
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Description</label>
                            <Input placeholder="Describe your image..." value={topic} onChange={(e) => setTopic(e.target.value)} />
                        </div>
                        <Button onClick={handleGenerate} className="w-full bg-amber-500 hover:bg-amber-600 text-white" disabled={isGenerating}>
                            {isGenerating ? 'Generating...' : <><Sparkles size={16} className="mr-2" /> Generate Asset</>}
