// --- ADVANCED CONTENT GENERATOR ---
export const AdvancedContentGenerator = () => {
    const navigate = useNavigate();
    const { addMarketingPost } = useArtisanData();
    const [generating, setGenerating] = useState(false);
    const [generatedItems, setGeneratedItems] = useState<any[]>([]);
    const [topic, setTopic] = useState('');
    const [tone, setTone] = useState('Professional');
    const [platforms, setPlatforms] = useState<string[]>(['Instagram', 'Facebook']);
    const [variations, setVariations] = useState(3);

    const togglePlatform = (p: string) => {
        if (platforms.includes(p)) { setPlatforms(platforms.filter(plat => plat !== p)); } 
        else { setPlatforms([...platforms, p]); }
    };

    const handleGenerate = async () => {
        if (!topic) return alert("Please enter a topic");
        if ((window as any).aistudio) {
            const hasKey = await (window as any).aistudio.hasSelectedApiKey();
            if (!hasKey) { await (window as any).aistudio.openSelectKey(); }
        }
        setGenerating(true);
        setGeneratedItems([]);
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const results = [];
            for (const platform of platforms) {
                const prompt = `Generate ${variations} distinct content variations for ${platform} about "${topic}". Tone: ${tone}. Return ONLY a JSON array of strings, where each string is a complete post.`;
                try {
                    const result = await ai.models.generateContent({
                        model: "gemini-3-flash-preview",
                        contents: prompt,
                        config: { responseMimeType: "application/json" }
                    });
                    const posts = JSON.parse(result.text || "[]");
                    posts.forEach((content: string) => {
                        results.push({ platform, content, topic });
                    });
                } catch (e: any) {
                    if (e.message && (e.message.includes('403') || e.status === 403 || e.message.includes('Requested entity was not found.'))) {
                        alert("Permission Denied or API key invalid. Please select a valid paid API key.");
                        if ((window as any).aistudio) (window as any).aistudio.openSelectKey();
                        setGenerating(false); return;
                    }
                }
            }
            setGeneratedItems(results);
        } catch (error) { console.error("Gen Error", error); } finally { setGenerating(false); }
    };

    const handleSaveAll = () => {
        generatedItems.forEach(item => {
            addMarketingPost({
                platform: item.platform as any, topic: item.topic, content: item.content,
                scheduledDate: new Date().toISOString().split('T')[0], status: 'Pending Approval', type: 'Text'
            });
        });
        navigate('/marketing/approvals');
    };

    return (
        <div className="p-6 space-y-6 animate-in fade-in h-screen flex flex-col">
            <div className="flex-none flex justify-between items-center mb-4">
                <div>
                    <button onClick={() => navigate('/marketing')} className="flex items-center gap-2 text-gray-500 hover:text-[#6A2C91] mb-1 font-medium">
                        <ArrowLeft size={18} /> Back
                    </button>
                    <div className="flex items-center gap-2 text-[#6A2C91]">
                        <Sparkles size={20} />
                        <h1 className="text-2xl font-bold text-gray-900">Advanced Content Generator</h1>
                    </div>
                    <p className="text-gray-500 text-sm">Batch generate content for multiple platforms</p>
                </div>
                {generatedItems.length > 0 && (
                    <Button onClick={handleSaveAll} className="bg-[#6A2C91] text-white">
                        <CheckCircle size={16} className="mr-2" /> Send to Approvals ({generatedItems.length})
                    </Button>
                )}
            </div>
            <div className="flex-1 grid grid-cols-1 lg:grid-cols-3 gap-8 overflow-hidden h-full">
                <div className="lg:col-span-1 bg-white border border-gray-200 rounded-xl p-6 shadow-sm overflow-y-auto">
                    <h3 className="font-bold text-gray-900 mb-6 uppercase text-xs tracking-widest">Settings</h3>
                    <div className="space-y-6">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-2">Content Topic</label>
                            <textarea className="w-full bg-white border border-gray-200 text-gray-900 p-3 rounded-lg focus:outline-none focus:border-[#6A2C91] h-24 resize-none shadow-sm" placeholder="Keywords or topic..." value={topic} onChange={(e) => setTopic(e.target.value)} />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-2">Target Platforms</label>
                            <div className="space-y-2">
                                {['Instagram', 'Facebook', 'YouTube', 'Pinterest', 'LinkedIn'].map(p => (
                                    <label key={p} className="flex items-center gap-3 cursor-pointer p-2 hover:bg-gray-50 rounded transition-colors">
                                        <input type="checkbox" checked={platforms.includes(p)} onChange={() => togglePlatform(p)} className="rounded text-[#6A2C91] focus:ring-[#6A2C91]" />
                                        <span className="text-sm text-gray-700">{p}</span>
                                    </label>
                                ))}
                            </div>
                        </div>
                        <Button onClick={handleGenerate} disabled={generating} className="w-full bg-[#6A2C91] text-white">
                            {generating ? <span className="animate-pulse">Generating...</span> : <><Sparkles size={16} className="mr-2" /> Generate All</>}
                        </Button>
                    </div>
                </div>
                <div className="lg:col-span-2 bg-gray-50 border border-gray-200 rounded-xl p-6 overflow-y-auto relative">
                    {generatedItems.length === 0 && !generating ? (
                        <div className="absolute inset-0 flex flex-col items-center justify-center text-gray-400">
                            <Sparkles size={48} className="mb-4 opacity-20" />
                            <p>Select platforms and generate to see results</p>
                        </div>
                    ) : (
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            {generatedItems.map((item, idx) => (
                                <div key={idx} className="bg-white p-4 rounded-xl border border-gray-200 shadow-sm">
                                    <Badge color="purple" className="mb-2">{item.platform}</Badge>
