export const ContentApprovals = () => {
    const navigate = useNavigate();
    const { marketingPosts, updateMarketingPost } = useArtisanData();
    const [selectedId, setSelectedId] = useState<string | null>(null);
    const [activeTab, setActiveTab] = useState<'Pending' | 'Approved'>('Pending');

    const filteredPosts = marketingPosts.filter(p => {
        if (activeTab === 'Pending') return p.status === 'Draft' || p.status === 'Pending Approval';
        return p.status === 'Scheduled' || p.status === 'Published';
    });

    const selectedPost = marketingPosts.find(p => p.id === selectedId);

    const handleApprove = () => {
        if (selectedPost) {
            updateMarketingPost(selectedPost.id, { status: 'Scheduled' });
            setSelectedId(null);
        }
    };

    return (
        <div className="p-6 space-y-6 animate-in fade-in pb-20">
            <button onClick={() => navigate('/marketing')} className="flex items-center gap-2 text-gray-500 hover:text-[#6A2C91] mb-2 font-medium">
