            </button>
            <h1 className="text-3xl font-bold text-gray-900">Content Approvals</h1>
            <div className="flex gap-4 mb-4">
                <button onClick={() => setActiveTab('Pending')} className={`px-6 py-2 rounded-full text-sm font-bold transition-all ${activeTab === 'Pending' ? 'bg-white text-[#6A2C91] shadow-sm ring-1 ring-gray-200' : 'text-gray-500'}`}>Pending</button>
                <button onClick={() => setActiveTab('Approved')} className={`px-6 py-2 rounded-full text-sm font-bold transition-all ${activeTab === 'Approved' ? 'bg-white text-[#6A2C91] shadow-sm ring-1 ring-gray-200' : 'text-gray-500'}`}>Approved</button>
            </div>
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <div className="space-y-4">
                    {filteredPosts.map(post => (
                        <div key={post.id} onClick={() => setSelectedId(post.id)} className={`p-6 rounded-xl border cursor-pointer hover:shadow-md transition-all ${selectedId === post.id ? 'bg-purple-50 border-[#6A2C91]' : 'bg-white border-gray-200'}`}>
                            <h4 className="font-bold text-gray-900">{post.topic}</h4>
                            <p className="text-sm text-gray-600 mt-2 line-clamp-2">{post.content}</p>
                        </div>
                    ))}
                </div>
                <Card title="Review Detail">
                    {selectedPost ? (
                        <div className="space-y-4">
                            <p className="text-sm font-bold uppercase text-gray-500">Platform: {selectedPost.platform}</p>
                            <p className="text-gray-800 text-sm whitespace-pre-wrap">{selectedPost.content}</p>
                            {activeTab === 'Pending' && <Button onClick={handleApprove} className="w-full bg-green-600 text-white">Approve & Schedule</Button>}
                        </div>
                    ) : <p className="text-gray-400 italic">Select a post to review.</p>}
                </Card>
            </div>
        </div>
    );
};

