import React, { useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { 
  LayoutDashboard, Package, TrendingUp, Settings, 
  ShoppingBag, Activity, Menu, X, Hexagon, User, ChevronDown, ChevronRight, LogOut, Crown, Search, Sparkles, Loader2,
  Boxes, FileText, Truck, ClipboardList, Target, Volume2, Headphones, Calendar, Share2, Video, PenTool, CheckSquare, Factory, MapPin, DollarSign, Shield, ShieldCheck, RefreshCw, Layers
} from 'lucide-react';
import { useArtisanData } from './DataContext';
import { searchBusinessData } from '../services/geminiService';

/**
 * ArtisanFlow Synaptic Layout Engine - STATUS: COMPLETE ✅
 */

export default function Layout({ children }: { children?: React.ReactNode }) {
  const navigate = useNavigate();
  const location = useLocation();
  const { businessProfile, userTier, logout, inventory, orders, getMarginMetrics } = useArtisanData();

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [searchResult, setSearchResult] = useState<string | null>(null);

  // Nav State Groups
  const [openGroups, setOpenGroups] = useState<Record<string, boolean>>({
    dashboard: true,
    operations: true,
    inventory: true,
    marketing: true,
    settings: false
  });

  const toggleGroup = (group: string) => {
    setOpenGroups(prev => ({ ...prev, [group]: !prev[group] }));
  };

  const getTierColor = () => {
    if (userTier === 'Margin Protection Pro') return 'text-[#C5A059] bg-[#C5A059]/10 border-[#C5A059]/20';
    if (userTier === 'Artisan Flow Basic') return 'text-[#6A2C91] bg-[#6A2C91]/10 border-[#6A2C91]/20';
    return 'text-slate-500 bg-slate-100 border-slate-200';
  };

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchQuery.trim()) return;
    setIsSearching(true);
    const context = { inventory, orders, margins: getMarginMetrics() };
    const result = await searchBusinessData(searchQuery, context);
    setSearchResult(result || null);
    setIsSearching(false);
    setTimeout(() => setSearchResult(null), 10000);
  };

  const NavItem = ({ to, icon: Icon, label, nested = false }: any) => {
    const isActive = location.pathname === to;
    return (
      <button 
        onClick={() => { navigate(to); setIsMobileMenuOpen(false); }}
        className={`flex items-center w-full px-4 py-2.5 rounded-xl transition-all duration-300 group relative overflow-hidden ${
          isActive 
            ? 'bg-[#6A2C91] text-white font-black shadow-lg shadow-purple-200 translate-x-1' 
            : 'text-gray-500 hover:bg-purple-50 hover:text-[#6A2C91]'
        } ${nested ? 'ml-6 text-xs' : 'text-sm font-bold'}`}
      >
        <Icon size={nested ? 14 : 18} className={`mr-3 ${isActive ? 'text-white' : 'text-gray-400 group-hover:text-[#6A2C91]'}`} />
        <span className="flex-1 text-left tracking-tight">{label}</span>
        {isActive && <div className="absolute right-0 top-0 h-full w-1.5 bg-amber-400"></div>}
      </button>
    );
  };

  const NavGroup = ({ id, label, icon: Icon, children }: any) => {
    const isOpen = openGroups[id];
    return (
      <div className="space-y-1">
        <button 
          onClick={() => toggleGroup(id)}
          className="flex items-center justify-between w-full px-4 py-3 text-[10px] font-black uppercase tracking-[0.2em] text-gray-400 hover:text-[#6A2C91] transition-colors"
        >
          <div className="flex items-center">
            <Icon size={14} className="mr-3" />
            <span>{label}</span>
          </div>
          {isOpen ? <ChevronDown size={12} /> : <ChevronRight size={12} />}
        </button>
        {isOpen && <div className="space-y-1 pb-2 animate-in slide-down duration-300">{children}</div>}
      </div>
    );
  };

  const pathnames = location.pathname.split('/').filter(x => x);

  return (
    <div className="flex h-screen w-full bg-stone-50 text-gray-900 font-sans selection:bg-purple-200">
      <style>{`
        @keyframes soft-success-glow {
          0% { box-shadow: 0 0 0 0 rgba(120, 190, 32, 0); border-color: transparent; transform: scale(1); }
          50% { box-shadow: 0 0 30px 10px rgba(120, 190, 32, 0.3); border-color: rgba(120, 190, 32, 0.6); transform: scale(1.01); }
          100% { box-shadow: 0 0 0 0 rgba(120, 190, 32, 0); border-color: transparent; transform: scale(1); }
        }
        .animate-soft-success {
          animation: soft-success-glow 3s cubic-bezier(0.4, 0, 0.2, 1) forwards;
        }
        .sidebar-gradient {
          background: linear-gradient(to bottom, #ffffff, #fcfcfb);
        }
      `}</style>

      {/* Mobile Sidebar Overlay */}
      <div 
        className={`fixed inset-0 bg-black/60 backdrop-blur-md z-40 transition-opacity md:hidden ${isMobileMenuOpen ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`} 
        onClick={() => setIsMobileMenuOpen(false)} 
      />

      {/* Sidebar */}
      <aside className={`fixed md:relative z-50 w-72 h-full border-r border-stone-200 flex flex-col sidebar-gradient shadow-2xl md:shadow-none transition-transform duration-500 cubic-bezier(0.4, 0, 0.2, 1) ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}`}>
        <div className="p-8 border-b border-stone-100 flex flex-col gap-6 sticky top-0 bg-white/80 backdrop-blur-xl z-10">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
               <div className="relative shrink-0">
                  <Hexagon size={42} className="text-[#C5A059] fill-[#C5A059]/10" />
                  <div className="absolute inset-0 flex items-center justify-center">
                      <div className="w-3 h-3 bg-[#6A2C91] rounded-full shadow-lg animate-pulse"></div>
                  </div>
               </div>
               <div className="flex-1 min-w-0">
                  <h1 className="font-black tracking-tighter uppercase text-sm text-gray-900 leading-tight truncate italic">Artisan Flow</h1>
                  <span className="text-[10px] font-mono font-black text-[#C5A059] tracking-widest uppercase block mt-0.5">Systems Architect</span>
               </div>
            </div>
            <button onClick={() => setIsMobileMenuOpen(false)} className="md:hidden text-gray-400 hover:text-red-500 transition-colors">
              <X size={24} />
            </button>
          </div>
          <div className={`px-4 py-1.5 rounded-full border text-[9px] font-black uppercase tracking-[0.2em] flex items-center gap-2 w-fit shadow-inner ${getTierColor()}`}>
             <Crown size={12} /> {userTier}
          </div>
        </div>

        <nav className="flex-1 px-4 py-8 space-y-6 overflow-y-auto scrollbar-hide">
            <NavGroup id="dashboard" label="Synaptic Path" icon={LayoutDashboard}>
              <NavItem to="/" label="Overview" icon={Activity} />
              <NavItem to="/command-center" label="Command Center" icon={LayoutDashboard} />
            </NavGroup>

            <NavGroup id="operations" label="Manufacturing" icon={Factory}>
              <NavItem to="/operations" label="Operations Hub" icon={Boxes} />
              <NavItem to="/operations/orders" label="Orders & Sync" icon={ShoppingBag} nested />
              <NavItem to="/operations/crm" label="CRM" icon={User} nested />
              <NavItem to="/operations/warehouse" label="Virtual Warehouse" icon={MapPin} nested />
            </NavGroup>

            <NavGroup id="inventory" label="Resource Hub" icon={Package}>
              <NavItem to="/inventory" label="Inventory Hub" icon={Package} />
              <NavItem to="/recipes" label="Recipes (BOM)" icon={FileText} nested />
              <NavItem to="/supplier_manager" label="Suppliers" icon={Truck} nested />
