    setRecipes(prev => prev.map(r => r.id === id ? { ...r, ...updates } : r));
  };

  const updateBudget = (updates: Partial<BudgetConfig>) => {
      setBudgets(prev => ({ ...prev, ...updates }));
  };

  const startTutorial = () => {
    setTutorialStepState(0);
    setIsTutorialActive(true);
