import { GoogleGenAI, Type } from "@google/genai";

/**
 * Lola AI Architect - STATUS: COMPLETE ✅
 */

export const chatWithLola = async (message: string, context?: any) => { 
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const systemPrompt = `
      You are Lola, a world-class Senior AI Architect for the Artisan Flow platform.
      You have real-time read access to the manufacturing database.

      CURRENT MANUFACTURING SNAPSHOT:
      ${JSON.stringify(context || {}, null, 2)}

      LOGIC PROTOCOLS:
      1. INVENTORY AWARENESS: When a user asks about product availability, stock, or SKUs, you MUST reference the 'inventory' array.
      2. WHOLESALE GATEKEEPER: Check 'isMarginHealthy' and 'marginMultiplier'.
      3. TONE: Authoritative, data-driven, yet artisanal. Brand color: #6A2C91.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: message,
      config: { systemInstruction: systemPrompt },
    });

    return { 
      text: response.text || "I'm analyzing the factory floor data but need a moment.", 
      isError: false 
    }; 
  } catch (error) {
    return { text: "Factory connection interrupted.", isError: true };
  }
};

/**
 * Global Synaptic Search - Uses Gemini to parse data queries
 */
export const searchBusinessData = async (query: string, data: any) => {
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const systemPrompt = `
            You are the ArtisanFlow Synaptic Search Engine. 
            Analyze the provided business context and answer the query concisely.
            If the user asks for specific metrics (margins, stock levels, revenue), calculate them from the data.
            CONTEXT: ${JSON.stringify(data)}
            Output format: A short, professional answer (1-2 sentences max).
        `;
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: query,
            config: { systemInstruction: systemPrompt }
        });
        return response.text;
    } catch (e) {
        return "Unable to perform synaptic search at this time.";
    }
};

