export const ReceptionistLogic = () => {
    const navigate = useNavigate();
    const { businessProfile, updateBusinessProfile } = useArtisanData();
    const [questions, setQuestions] = useState<string[]>(businessProfile.receptionistLogic?.qualificationQuestions || ['', '', '']);
    const [isSaving, setIsSaving] = useState(false);

    const handleQuestionChange = (index: number, value: string) => {
        const newQs = [...questions];
        newQs[index] = value;
        setQuestions(newQs);
    };

    const addQuestion = () => {
        if (questions.length < 5) {
            setQuestions([...questions, '']);
        }
    };

    const removeQuestion = (index: number) => {
        if (questions.length > 3) {
            setQuestions(questions.filter((_, i) => i !== index));
        }
    };

    const handleSave = () => {
        setIsSaving(true);
        updateBusinessProfile({
            receptionistLogic: {
                qualificationQuestions: questions.filter(q => q.trim() !== '')
            }
        });
        setTimeout(() => {
            setIsSaving(false);
            alert("Receptionist Logic saved successfully.");
        }, 600);
    };

    return (
        <div className="p-6 space-y-6 animate-in fade-in pb-20">
            <button onClick={() => navigate('/marketing')} className="flex items-center gap-2 text-gray-400 hover:text-[#6A2C91] font-black text-xs uppercase tracking-widest mb-4">
                <ArrowLeft size={16} /> Back to Hub
            </button>
            <div className="flex items-center gap-4 mb-6">
                <div className="p-3 bg-white border border-gray-200 rounded-xl text-purple-600 shadow-sm">
                    <Headphones size={24} />
                </div>
                <div>
                    <h1 className="text-3xl font-black text-gray-900 uppercase italic tracking-tight">Receptionist Logic</h1>
                    <p className="text-gray-500">Screen leads with automated qualification questions before scheduling</p>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                <div className="lg:col-span-2">
                    <Card title="Qualification Questions" className="rounded-3xl border-stone-100">
                        <p className="text-xs text-gray-500 mb-6 uppercase tracking-widest font-bold">Define 3-5 questions the AI agent will ask to screen leads.</p>
                        <div className="space-y-4">
                            {questions.map((q, idx) => (
                                <div key={idx} className="flex items-start gap-4">
                                    <div className="flex-none w-10 h-10 flex items-center justify-center bg-stone-50 rounded-xl text-xs font-black text-gray-400 border border-stone-100 shadow-inner">
                                        {idx + 1}
                                    </div>
                                    <div className="flex-1">
                                        <textarea 
                                            className="w-full bg-white border border-stone-200 text-gray-900 p-4 rounded-2xl focus:outline-none focus:border-[#6A2C91] h-24 resize-none shadow-sm font-sans text-sm font-medium"
                                            placeholder="e.g. What is your monthly production volume?"
                                            value={q}
                                            onChange={e => handleQuestionChange(idx, e.target.value)}
                                        />
                                    </div>
                                    {questions.length > 3 && (
                                        <button onClick={() => removeQuestion(idx)} className="mt-4 text-stone-300 hover:text-red-500 transition-colors">
                                            <Trash2 size={18} />
                                        </button>
                                    )}
                                </div>
                            ))}

                            {questions.length < 5 && (
                                <button 
                                    onClick={addQuestion}
                                    className="w-full py-4 border-2 border-dashed border-stone-100 rounded-2xl text-gray-400 hover:text-[#6A2C91] hover:border-[#6A2C91] hover:bg-purple-50 transition-all font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2"
                                >
                                    <Plus size={18} /> Add Screening Node
                                </button>
                            )}
                        </div>
                    </Card>
                </div>

                <div className="lg:col-span-1 space-y-6">
                    <Card title="Agent Behavior Protocol" className="rounded-3xl border-stone-100">
                        <div className="space-y-4">
                            <div className="p-5 bg-purple-50 rounded-2xl border border-purple-100">
                                <h4 className="text-[10px] font-black text-purple-900 uppercase tracking-widest mb-2">Lead Scoring</h4>
                                <p className="text-xs text-purple-800 leading-relaxed font-medium">
