                                </p>
                            </div>
                            <div className="p-5 bg-stone-50 rounded-2xl border border-stone-100">
                                <h4 className="text-[10px] font-black text-gray-900 uppercase tracking-widest mb-3">Screening Workflow</h4>
                                <ul className="text-xs text-gray-500 space-y-3 font-medium">
                                    <li className="flex gap-3">
                                        <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full flex-none mt-1" />
                                        <span>Agent introduces brand and greets visitor.</span>
                                    </li>
                                    <li className="flex gap-3">
                                        <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full flex-none mt-1" />
                                        <span>Agent asks defined qualification questions.</span>
                                    </li>
                                    <li className="flex gap-3">
                                        <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full flex-none mt-1" />
                                        <span>Agent evaluates fit and redirects to calendar.</span>
                                    </li>
                                </ul>
                            </div>
                        </div>
                    </Card>

