    const [result, setResult] = useState('');

    const handleGenerate = async () => {
        if (!topic) return alert("Please enter a topic");
        setGenerating(true);
        try {
            const adjectives = businessProfile.brandVoice?.adjectives?.join(', ') || 'Professional';
            const restricted = businessProfile.brandVoice?.restrictedWords?.join(', ') || '';

            const prompt = `Write an SEO-optimized, luxury-toned blog post about: ${topic}. 
            The brand voice should be described as: ${adjectives}.
            ${restricted ? `NEVER use the following words or phrases: ${restricted}.` : ''}
