export const AdvancedContentGenerator = () => {
    const navigate = useNavigate();
    const { addMarketingPost } = useArtisanData();
    const [generating, setGenerating] = useState(false);
    const [generatedItems, setGeneratedItems] = useState<any[]>([]);
    const [topic, setTopic] = useState('');
    const [tone, setTone] = useState('Professional');
    const [platforms, setPlatforms] = useState<string[]>(['Instagram', 'Facebook']);
    const [variations, setVariations] = useState(2);

    const togglePlatform = (p: string) => {
        if (platforms.includes(p)) { setPlatforms(platforms.filter(plat => plat !== p)); } 
        else { setPlatforms([...platforms, p]); }
    };

    const handleGenerate = async () => {
        if (!topic) return alert("Please enter a topic");
        if ((window as any).aistudio) {
            const hasKey = await (window as any).aistudio.hasSelectedApiKey();
            if (!hasKey) { await (window as any).aistudio.openSelectKey(); }
        }
        setGenerating(true);
        setGeneratedItems([]);
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const results = [];
            for (const platform of platforms) {
                const prompt = `Generate ${variations} distinct, luxury-toned content variations for ${platform} about "${topic}". Tone: ${tone}. Return ONLY a JSON array of strings, where each string is a complete post.`;
                try {
                    const result = await ai.models.generateContent({
                        model: "gemini-3-flash-preview",
                        contents: prompt,
                        config: { responseMimeType: "application/json" }
                    });
                    const posts = JSON.parse(result.text || "[]");
                    posts.forEach((content: string) => {
                        results.push({ platform, content, topic });
                    });
                } catch (e: any) {
                    if (e.message && (e.message.includes('403') || e.status === 403 || e.message.includes('Requested entity was not found.'))) {
                        alert("Permission Denied or API key invalid. Please select a valid paid API key.");
                        if ((window as any).aistudio) (window as any).aistudio.openSelectKey();
                        setGenerating(false); return;
                    }
                }
            }
            setGeneratedItems(results);
        } catch (error) { console.error("Gen Error", error); } finally { setGenerating(false); }
    };

    const handleSaveAll = () => {
        generatedItems.forEach(item => {
            addMarketingPost({
                platform: item.platform as any, topic: item.topic, content: item.content,
                scheduledDate: new Date().toISOString().split('T')[0], status: 'Pending Approval', type: 'Text'
            });
        });
        alert(`Successfully synchronized ${generatedItems.length} nodes to the Approvals ledger.`);
        navigate('/marketing/approvals');
    };

    return (
        <div className="p-6 space-y-8 animate-in fade-in h-screen flex flex-col pb-20">
            <div className="flex-none flex justify-between items-start mb-4">
                <div>
                    <button onClick={() => navigate('/marketing')} className="flex items-center gap-2 text-gray-400 hover:text-[#6A2C91] font-black text-xs uppercase tracking-widest mb-4">
                        <ArrowLeft size={16} /> Back to Hub
                    </button>
                    <div className="flex items-center gap-4">
                        <div className="p-3 bg-white border border-pink-100 rounded-xl text-pink-600 shadow-sm">
                            <Sparkles size={24} />
                        </div>
                        <div>
                            <h1 className="text-3xl font-black text-gray-900 uppercase italic tracking-tight">Advanced Batch Synthesizer</h1>
                            <p className="text-gray-500">Multiplex generation for cross-platform omnichannel presence</p>
                        </div>
                    </div>
                </div>
                {generatedItems.length > 0 && (
                    <Button onClick={handleSaveAll} className="bg-[#6A2C91] text-white h-12 rounded-2xl font-black text-xs tracking-widest px-8 shadow-xl">
                        <CheckCircle size={16} className="mr-2" /> Commit Batch to Queue ({generatedItems.length})
                    </Button>
                )}
            </div>

            <div className="flex-1 grid grid-cols-1 lg:grid-cols-3 gap-10 overflow-hidden">
                <Card title="Protocol Parameters" className="lg:col-span-1 rounded-3xl border-stone-100 overflow-y-auto">
                    <div className="space-y-6 mt-4">
                        <div>
                            <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Universal Topic</label>
                            <textarea className="w-full bg-stone-50 border border-stone-200 rounded-2xl p-4 text-sm focus:border-[#6A2C91] outline-none h-32 resize-none shadow-inner font-medium text-gray-700" placeholder="e.g. Sustainable material sourcing BTS..." value={topic} onChange={(e) => setTopic(e.target.value)} />
                        </div>
                        <div>
                            <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-3 ml-1">Synchronized Channels</label>
                            <div className="grid grid-cols-2 gap-2">
                                {['Instagram', 'Facebook', 'YouTube', 'Pinterest', 'LinkedIn'].map(p => (
                                    <label key={p} className={`flex items-center gap-3 cursor-pointer p-4 rounded-2xl border transition-all ${platforms.includes(p) ? 'bg-purple-50 border-[#6A2C91]' : 'bg-white border-stone-100 hover:bg-stone-50'}`}>
                                        <input type="checkbox" checked={platforms.includes(p)} onChange={() => togglePlatform(p)} className="rounded text-[#6A2C91] focus:ring-[#6A2C91] hidden" />
                                        <span className={`text-[10px] font-black uppercase tracking-tight ${platforms.includes(p) ? 'text-[#6A2C91]' : 'text-gray-400'}`}>{p}</span>
