interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'ghost' | 'outline' | 'premium' | 'danger';
  children: React.ReactNode;
}

export const Button: React.FC<ButtonProps> = ({ variant = 'primary', className = '', children, style, ...props }) => {
  const baseStyle = "w-full md:w-auto px-6 py-2.5 rounded-xl font-bold transition-all duration-300 flex items-center justify-center gap-2 uppercase tracking-widest text-[10px]";

  let variantClass = "";

  if (variant === 'primary') {
    variantClass = "bg-[#6A2C91] text-white hover:bg-[#5a257a] shadow-lg shadow-purple-200/20 active:scale-95";
  } else if (variant === 'premium') {
    variantClass = "bg-[#C5A059] text-white hover:bg-[#b08e4d] shadow-lg shadow-[#C5A059]/20 active:scale-95";
  } else if (variant === 'secondary') {
    variantClass = "bg-white text-[#6A2C91] border border-[#6A2C91]/30 hover:bg-purple-50 active:scale-95";
  } else if (variant === 'outline') {
    variantClass = "border border-stone-200 text-gray-700 hover:bg-stone-50 active:scale-95";
  } else if (variant === 'danger') {
    variantClass = "bg-red-50 text-red-600 border border-red-100 hover:bg-red-100 shadow-sm active:scale-95";
  } else {
    variantClass = "text-gray-500 hover:bg-gray-100 hover:text-gray-900 active:scale-95";
  }

  return (
    <button 
      className={`${baseStyle} ${variantClass} ${className}`} 
      style={style}
      {...props}
    >
      {children}
    </button>
  );
};

