export const FileUploader: React.FC<{ 
  onUpload?: (files: File[]) => void; 
  acceptedFormats?: string; 
  label?: string;
}> = ({ onUpload, acceptedFormats = ".csv, .pdf, .xlsx, .xls", label = "Synaptic Data Ingestion" }) => {
  const [dragActive, setDragActive] = useState(false);
  const [files, setFiles] = useState<File[]>([]);
  const inputRef = useRef<HTMLInputElement>(null);

  const handleDrag = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") {
      setDragActive(true);
    } else if (e.type === "dragleave") {
      setDragActive(false);
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFiles(Array.from(e.dataTransfer.files));
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    e.preventDefault();
    if (e.target.files && e.target.files[0]) {
      handleFiles(Array.from(e.target.files));
    }
  };

  const handleFiles = (newFiles: File[]) => {
    setFiles([...files, ...newFiles]);
    if (onUpload) onUpload(newFiles);
  };

  const removeFile = (idx: number) => {
    const newFiles = [...files];
    newFiles.splice(idx, 1);
    setFiles(newFiles);
  };

  return (
    <div className="w-full">
        <label className="block text-[10px] font-black text-stone-400 uppercase tracking-widest mb-3 ml-1">{label}</label>
        <div 
            className={`relative border-2 border-dashed rounded-[2rem] p-10 text-center transition-all duration-500 ${dragActive ? 'border-[#6A2C91] bg-purple-50 shadow-inner' : 'border-stone-200 bg-stone-50 hover:bg-white hover:border-[#6A2C91] hover:shadow-xl'}`}
            onDragEnter={handleDrag} 
            onDragLeave={handleDrag} 
            onDragOver={handleDrag} 
            onDrop={handleDrop}
        >
            <input 
                ref={inputRef}
                type="file" 
                multiple 
                className="hidden" 
                onChange={handleChange}
                accept={acceptedFormats}
            />

            <div className="flex flex-col items-center gap-4 cursor-pointer" onClick={() => inputRef.current?.click()}>
                <div className={`w-16 h-16 rounded-2xl flex items-center justify-center transition-all ${dragActive ? 'bg-[#6A2C91] text-white shadow-xl' : 'bg-white text-stone-300 shadow-sm'}`}>
                    <Upload size={32} />
                </div>
                <div>
                  <p className="text-sm font-black text-gray-900 uppercase italic">
                      Initialize Handshake
                  </p>
                  <p className="text-[10px] text-stone-400 font-bold uppercase tracking-widest mt-1">
                      Drag files or click to browse
                  </p>
                </div>
            </div>
        </div>

        {files.length > 0 && (
            <div className="mt-6 space-y-3">
                {files.map((file, idx) => (
