                                            value={q}
                                            onChange={e => handleQuestionChange(idx, e.target.value)}
                                        />
                                    </div>
                                    {questions.length > 3 && (
                                        <button onClick={() => removeQuestion(idx)} className="mt-4 text-stone-200 hover:text-red-500 transition-colors">
                                            <Trash2 size={20} />
                                        </button>
                                    )}
