import React, { useState, useRef, useEffect } from 'react';
import { MessageSquare, Send, Minimize2, Sparkles, Calendar, Factory, Database, ShieldCheck, X } from 'lucide-react';
import { useArtisanData } from './DataContext';
import { chatWithLola } from '../services/geminiService';

type Msg = { 
  role: 'user' | 'assistant', 
  text: string, 
  isSlotSelector?: boolean,
  isAuditPrompt?: boolean
};

/**
 * Lola AI Assistant - High-Fidelity Responsive Architecture ✅
 * Optimized for Mobile (w-full), Tablet (350px), and Desktop (450px).
 */

export const AIAssistant: React.FC = () => { 
  const { businessProfile, addAppointment, inventory, productionStats, getTotalRevenue, getMarginMetrics } = useArtisanData();
  const [isOpen, setIsOpen] = useState(false); 
  const [messages, setMessages] = useState<Msg[]>([ 
    { role: 'assistant', text: `Greetings! I am Lola. I've successfully synchronized with your manufacturing floor. How can I help you optimize your flow today?` } 
  ]); 
  const [input, setInput] = useState(''); 
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const totalFinishedStock = inventory.filter(i => i.type === 'finished').reduce((acc, i) => acc + i.stock, 0);
  const { isMarginHealthy, marginMultiplier } = getMarginMetrics();

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  const handleSend = async () => { 
    if (!input.trim()) return;

    const userMsg = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsLoading(true);

    try {
        const snapshot = { 
            inventory, 
            productionStats, 
            totalFinishedUnits: totalFinishedStock,
            isMarginHealthy,
            marginMultiplier,
            revenue: getTotalRevenue()
        };

        const response = await chatWithLola(userMsg, snapshot);
        const assistantMsg: Msg = { role: 'assistant', text: response.text };

        if (userMsg.toLowerCase().includes('wholesale') || userMsg.toLowerCase().includes('strategy')) {
            if (marginMultiplier < 2.2 || totalFinishedStock < 50) {
                assistantMsg.isAuditPrompt = true;
            } else {
                assistantMsg.isSlotSelector = true;
            }
        }

        setMessages(prev => [...prev, assistantMsg]);
    } catch (error) {
        setMessages(prev => [...prev, { role: 'assistant', text: "Connectivity interrupted. Lola is re-syncing with the production server." }]);
    } finally {
        setIsLoading(false);
    }
  };

  const handleSelectSlot = (time: string, type: string = 'Wholesale Strategy') => {
      addAppointment({
          clientName: 'Wholesale Lead',
          email: 'lead@artisanflow.ai',
          date: '2025-12-16',
          time,
          type: type as any,
          status: 'Confirmed'
      });
      setMessages(prev => [...prev, { 
          role: 'assistant', 
          text: `Confirmed. I have secured your ${type.toLowerCase()} for Dec 16th at ${time}.` 
      }]);
  };

  if (!isOpen) { 
    return ( 
      <button 
        onClick={() => setIsOpen(true)} 
        className="fixed bottom-6 right-6 w-16 h-16 bg-[#6A2C91] text-white rounded-full flex items-center justify-center shadow-2xl hover:scale-110 transition-all z-50 animate-float sm:w-14 sm:h-14"
      >
         <MessageSquare size={28} className="sm:size-24" />
         <div className="absolute -top-1 -right-1 w-5 h-5 bg-[#C5A059] rounded-full border-2 border-white animate-pulse"></div>
      </button> 
    ); 
  }

  return (
    <div className="fixed inset-x-0 bottom-0 sm:inset-auto sm:bottom-6 sm:right-6 w-full sm:w-[350px] md:w-[450px] h-[90vh] sm:h-[650px] bg-white border border-stone-200 rounded-t-[2.5rem] sm:rounded-3xl shadow-2xl flex flex-col overflow-hidden z-[60] animate-in slide-up duration-500">
      <div className="bg-[#6A2C91] p-6 sm:p-5 flex justify-between items-center text-white">
        <div className="flex items-center gap-4 sm:gap-3">
            <div className="p-3 sm:p-2 bg-white/10 rounded-2xl sm:rounded-xl">
                <Database size={24} className="text-[#C5A059] sm:size-20" />
            </div>
            <div>
                <h3 className="font-black text-lg sm:text-sm tracking-tight flex items-center gap-1.5 uppercase italic">
                    Lola <Sparkles size={14} className="text-[#C5A059]" />
                </h3>
                <p className="text-[10px] sm:text-[9px] text-white/60 font-black uppercase tracking-widest">Inventory-Aware Logic Node</p>
            </div>
        </div>
        <button onClick={() => setIsOpen(false)} className="p-3 sm:p-2 hover:bg-white/10 rounded-full transition-colors">
            <Minimize2 size={24} className="sm:size-18" />
        </button>
      </div>

      <div className="px-6 py-3 sm:px-5 sm:py-2 bg-stone-100 border-b border-stone-200 flex justify-between items-center text-[10px] font-black text-gray-400">
          <div className="flex items-center gap-2">
              <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></div>
              <span className="uppercase tracking-widest">FACTORY LINK ONLINE</span>
          </div>
          <div className="flex items-center gap-1.5 text-[#C5A059]">
              <ShieldCheck size={12} />
              <span className="uppercase tracking-widest">MARGIN GUARD™ ACTIVE</span>
          </div>
      </div>

      <div className="flex-1 overflow-y-auto p-6 sm:p-5 space-y-6 sm:space-y-4 bg-stone-50/50 scrollbar-hide">
        {messages.map((msg, idx) => (
          <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[90%] sm:max-w-[85%] p-5 sm:p-4 rounded-2xl sm:rounded-3xl text-base sm:text-sm shadow-md leading-relaxed ${
              msg.role === 'user' 
                ? 'bg-[#6A2C91] text-white rounded-br-none' 
                : 'bg-white text-gray-800 rounded-bl-none border border-stone-100'
            }`}>
              {msg.text}

              {msg.isAuditPrompt && (
                <div className="mt-6 sm:mt-4 p-4 sm:p-3 bg-amber-50 border border-amber-200 rounded-2xl space-y-4 sm:space-y-3">
                   <p className="text-xs sm:text-[11px] font-black text-amber-800 flex items-center gap-2 uppercase tracking-tight">
                       <Factory size={16} /> CAPACITY ALERT: Margin health below threshold.
                   </p>
                   <button onClick={() => handleSelectSlot('10:00 AM', 'Manufacturing Audit')} className="w-full bg-[#C5A059] text-white py-3 sm:py-2 rounded-xl text-xs font-black uppercase tracking-[0.2em] shadow-lg shadow-amber-500/10 hover:bg-[#b08e4d] transition-all">Schedule Audit</button>
                </div>
              )}

              {msg.isSlotSelector && (
                  <div className="mt-6 sm:mt-4 space-y-3 sm:space-y-2">
                      <p className="text-[10px] font-black text-emerald-600 uppercase tracking-[0.2em] mb-3 ml-1">Availability Synchronized:</p>
                      <div className="grid grid-cols-2 gap-3 sm:gap-2">
                        {['09:00 AM', '02:00 PM'].map(slot => (
                            <button key={slot} onClick={() => handleSelectSlot(slot)} className="bg-purple-50 text-[#6A2C91] border border-purple-100 py-3 sm:py-2 rounded-xl text-xs font-black hover:bg-[#6A2C91] hover:text-white transition-all flex items-center justify-center gap-2">
                                <Calendar size={14} /> {slot}
                            </button>
                        ))}
                      </div>
                  </div>
              )}
            </div>
          </div>
        ))}
        {isLoading && (
            <div className="flex justify-start">
                <div className="bg-stone-200/50 p-4 rounded-3xl animate-pulse flex items-center gap-3">
                    <div className="flex gap-1">
                        <div className="w-1.5 h-1.5 bg-stone-400 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
                        <div className="w-1.5 h-1.5 bg-stone-400 rounded-full animate-bounce" style={{ animationDelay: '200ms' }}></div>
                        <div className="w-1.5 h-1.5 bg-stone-400 rounded-full animate-bounce" style={{ animationDelay: '400ms' }}></div>
                    </div>
                    <span className="text-[10px] font-black text-stone-400 uppercase tracking-widest">Querying Logic Nodes...</span>
                </div>
            </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <div className="p-6 sm:p-5 bg-white border-t border-stone-100 pb-10 sm:pb-5">
        <div className="flex items-center gap-3 bg-stone-100 rounded-2xl px-5 py-2 sm:px-4 sm:py-1 border border-stone-200 focus-within:border-[#6A2C91] focus-within:ring-4 focus-within:ring-purple-500/5 transition-all">
          <input 
            type="text" 
            value={input} 
            onChange={(e) => setInput(e.target.value)} 
            onKeyDown={(e) => e.key === 'Enter' && handleSend()} 
            placeholder="Optimize stock or batches..." 
            className="flex-1 bg-transparent py-4 sm:py-3 text-gray-900 text-base sm:text-sm outline-none placeholder:text-stone-400 font-medium" 
          />
          <button 
            onClick={handleSend} 
            disabled={isLoading} 
            className="p-3 sm:p-2 text-[#6A2C91] hover:scale-125 transition-all disabled:opacity-30"
          >
            <Send size={24} className="sm:size-20" />
          </button>
        </div>
        <p className="text-center text-[9px] font-black text-stone-300 uppercase tracking-[0.3em] mt-6 sm:mt-4 italic">Artisan Flow Synaptic Link Active</p>
      </div>
    </div>
  ); 
};

