import React, { useState, useRef, useEffect } from 'react';
import { MessageSquare, Send, Minimize2, Sparkles, Calendar, Factory, Database, ShieldCheck, X } from 'lucide-react';
import { useArtisanData } from './DataContext';
import { chatWithLola } from '../services/geminiService';

type Msg = { 
  role: 'user' | 'assistant', 
  text: string, 
  isSlotSelector?: boolean,
  isAuditPrompt?: boolean
};

/**
 * Lola AI Assistant - High-Fidelity Responsive Architecture ✅
 * Optimized for Mobile (w-full), Tablet (350px), and Desktop (450px).
 */

export const AIAssistant: React.FC = () => { 
  const { businessProfile, addAppointment, inventory, productionStats, getTotalRevenue, getMarginMetrics } = useArtisanData();
  const [isOpen, setIsOpen] = useState(false); 
  const [messages, setMessages] = useState<Msg[]>([ 
    { role: 'assistant', text: `Greetings! I am Lola. I've successfully synchronized with your manufacturing floor. How can I help you optimize your flow today?` } 
  ]); 
  const [input, setInput] = useState(''); 
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const totalFinishedStock = inventory.filter(i => i.type === 'finished').reduce((acc, i) => acc + i.stock, 0);
  const { isMarginHealthy, marginMultiplier } = getMarginMetrics();

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  const handleSend = async () => { 
    if (!input.trim()) return;

    const userMsg = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsLoading(true);

    try {
        const snapshot = { 
            inventory, 
            productionStats, 
            totalFinishedUnits: totalFinishedStock,
            isMarginHealthy,
            marginMultiplier,
            revenue: getTotalRevenue()
        };

        const response = await chatWithLola(userMsg, snapshot);
        const assistantMsg: Msg = { role: 'assistant', text: response.text };

        if (userMsg.toLowerCase().includes('wholesale') || userMsg.toLowerCase().includes('strategy')) {
            if (marginMultiplier < 2.2 || totalFinishedStock < 50) {
                assistantMsg.isAuditPrompt = true;
            } else {
                assistantMsg.isSlotSelector = true;
            }
        }

        setMessages(prev => [...prev, assistantMsg]);
    } catch (error) {
        setMessages(prev => [...prev, { role: 'assistant', text: "Connectivity interrupted. Lola is re-syncing with the production server." }]);
    } finally {
        setIsLoading(false);
    }
  };

  const handleSelectSlot = (time: string, type: string = 'Wholesale Strategy') => {
      addAppointment({
          clientName: 'Wholesale Lead',
          email: 'lead@artisanflow.ai',
          date: '2025-12-16',
          time,
          type: type as any,
          status: 'Confirmed'
      });
      setMessages(prev => [...prev, { 
          role: 'assistant', 
          text: `Confirmed. I have secured your ${type.toLowerCase()} for Dec 16th at ${time}.` 
      }]);
  };

  if (!isOpen) { 
    return ( 
      <button 
        onClick={() => setIsOpen(true)} 
        className="fixed bottom-6 right-6 w-16 h-16 bg-[#6A2C91] text-white rounded-full flex items-center justify-center shadow-2xl hover:scale-110 transition-all z-50 animate-float sm:w-14 sm:h-14"
      >
         <MessageSquare size={28} className="sm:size-24" />
         <div className="absolute -top-1 -right-1 w-5 h-5 bg-[#C5A059] rounded-full border-2 border-white animate-pulse"></div>
      </button> 
    ); 
  }

  return (
    <div className="fixed inset-x-0 bottom-0 sm:inset-auto sm:bottom-6 sm:right-6 w-full sm:w-[350px] md:w-[450px] h-[90vh] sm:h-[650px] bg-white border border-stone-200 rounded-t-[2.5rem] sm:rounded-3xl shadow-2xl flex flex-col overflow-hidden z-[60] animate-in slide-up duration-500">
      <div className="bg-[#6A2C91] p-6 sm:p-5 flex justify-between items-center text-white">
