import React, { useState, useRef, useEffect } from 'react';
import { MessageSquare, Send, Minimize2, Sparkles, Calendar, Factory, Database, ShieldCheck, X } from 'lucide-react';
import { useArtisanData } from './DataContext';
import { chatWithLola } from '../services/geminiService';

type Msg = { 
  role: 'user' | 'assistant', 
  text: string, 
  isSlotSelector?: boolean,
  isAuditPrompt?: boolean
};

/**
 * Lola AI Assistant - High-Fidelity Synaptic Architecture ✅
 */

export const AIAssistant: React.FC = () => { 
  const { businessProfile, addAppointment, inventory, productionStats, getTotalRevenue, getMarginMetrics } = useArtisanData();
  const [isOpen, setIsOpen] = useState(false); 
  const [messages, setMessages] = useState<Msg[]>([ 
    { role: 'assistant', text: `Greetings! I am Lola. I've successfully synchronized with your manufacturing floor. How can I help you optimize your flow today?` } 
  ]); 
  const [input, setInput] = useState(''); 
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const totalFinishedStock = inventory.filter(i => i.type === 'finished').reduce((acc, i) => acc + i.stock, 0);
  const { isMarginHealthy, marginMultiplier } = getMarginMetrics();

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  const handleSend = async () => { 
    if (!input.trim()) return;

    const userMsg = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsLoading(true);

    try {
        const snapshot = { 
            inventory, 
            productionStats, 
            totalFinishedUnits: totalFinishedStock,
            isMarginHealthy,
            marginMultiplier,
            revenue: getTotalRevenue()
        };

        const response = await chatWithLola(userMsg, snapshot);
        const assistantMsg: Msg = { role: 'assistant', text: response.text };

        if (userMsg.toLowerCase().includes('wholesale') || userMsg.toLowerCase().includes('strategy')) {
            if (marginMultiplier < 2.2 || totalFinishedStock < 50) {
                assistantMsg.isAuditPrompt = true;
            } else {
                assistantMsg.isSlotSelector = true;
            }
        }

        setMessages(prev => [...prev, assistantMsg]);
    } catch (error) {
        setMessages(prev => [...prev, { role: 'assistant', text: "Connectivity interrupted. Lola is re-syncing with the production server." }]);
    } finally {
        setIsLoading(false);
    }
  };

  const handleSelectSlot = (time: string, type: string = 'Wholesale Strategy') => {
      addAppointment({
          clientName: 'Wholesale Lead',
          email: 'lead@artisanflow.ai',
          date: '2025-12-16',
          time,
          type: type as any,
          status: 'Confirmed'
      });
      setMessages(prev => [...prev, { 
          role: 'assistant', 
          text: `Confirmed. I have secured your ${type.toLowerCase()} for Dec 16th at ${time}.` 
      }]);
  };

  if (!isOpen) { 
    return ( 
      <button 
        onClick={() => setIsOpen(true)} 
        className="fixed bottom-6 right-6 w-14 h-14 bg-[#6A2C91] text-white rounded-full flex items-center justify-center shadow-lg hover:bg-white transition-colors z-50 animate-float"
      >
         <MessageSquare size={24} />
         <div className="absolute -top-1 -right-1 w-4 h-4 bg-[#C5A059] rounded-full border-2 border-white animate-pulse"></div>
      </button> 
    ); 
  }

  return (
    <div className="fixed bottom-6 right-6 w-96 h-[600px] bg-white border border-stone-200 rounded-3xl shadow-2xl flex flex-col overflow-hidden z-50 animate-in slide-in-from-bottom-10">
      <div className="bg-[#6A2C91] p-5 flex justify-between items-center text-white">
        <div className="flex items-center gap-3">
            <div className="p-2 bg-white/10 rounded-xl">
                <Database size={20} className="text-[#C5A059]" />
            </div>
            <div>
                <h3 className="font-black text-sm tracking-tight flex items-center gap-1.5 uppercase italic">
                    Lola <Sparkles size={14} className="text-[#C5A059]" />
                </h3>
                <p className="text-[9px] text-white/60 font-black uppercase tracking-widest">Inventory-Aware Logic Node</p>
            </div>
        </div>
        <button onClick={() => setIsOpen(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors">
            <Minimize2 size={18} />
        </button>
      </div>

      <div className="px-5 py-2 bg-stone-100 border-b border-stone-200 flex justify-between items-center text-[10px] font-black text-gray-400">
          <div className="flex items-center gap-2">
              <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></div>
              <span className="uppercase tracking-widest">FACTORY LINK ONLINE</span>
          </div>
          <div className="flex items-center gap-1.5 text-[#C5A059]">
              <ShieldCheck size={12} />
              <span className="uppercase tracking-widest">MARGIN GUARD™ ACTIVE</span>
          </div>
      </div>

      <div className="flex-1 overflow-y-auto p-5 space-y-4 bg-stone-50/50 scrollbar-hide">
        {messages.map((msg, idx) => (
          <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-4 rounded-3xl text-sm shadow-md leading-relaxed ${
              msg.role === 'user' 
                ? 'bg-[#6A2C91] text-white rounded-br-none' 
                : 'bg-white text-gray-800 rounded-bl-none border border-stone-100'
            }`}>
              {msg.text}

              {msg.isAuditPrompt && (
                <div className="mt-4 p-3 bg-amber-50 border border-amber-200 rounded-2xl space-y-3">
                   <p className="text-[11px] font-black text-amber-800 flex items-center gap-2 uppercase tracking-tight">
                       <Factory size={16} /> CAPACITY ALERT: Margin health below threshold.
                   </p>
                   <button onClick={() => handleSelectSlot('10:00 AM', 'Manufacturing Audit')} className="w-full bg-[#C5A059] text-white py-2 rounded-xl text-xs font-black uppercase tracking-[0.2em] shadow-lg shadow-amber-500/10 hover:bg-[#b08e4d] transition-all">Schedule Audit</button>
