import React, { useState, useRef, useEffect } from 'react';
import { MessageSquare, Send, Minimize2, Sparkles, Calendar, Factory, Database, Mic, MicOff, Volume2, VolumeX, Loader2 } from 'lucide-react';
import { useArtisanData } from './DataContext';
import { chatWithLola, generateLolaSpeech } from '../services/geminiService';

type Msg = { 
  role: 'user' | 'assistant', 
  text: string, 
  isSlotSelector?: boolean,
  isAuditPrompt?: boolean
};

/**
 * Lola AI Assistant - Compact Synaptic Architecture with Voice Accessibility ✅
 */

export const AIAssistant: React.FC = () => { 
  const { businessProfile, addAppointment, inventory, productionStats, getTotalRevenue, getMarginMetrics } = useArtisanData();
  const [isOpen, setIsOpen] = useState(false); 
  const [messages, setMessages] = useState<Msg[]>([ 
    { role: 'assistant', text: `Greetings! I am Lola. Ready to optimize your flow.` } 
  ]); 
  const [input, setInput] = useState(''); 
  const [isLoading, setIsLoading] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isTtsEnabled, setIsTtsEnabled] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const recognitionRef = useRef<any>(null);

  const totalFinishedStock = inventory.filter(i => i.type === 'finished').reduce((acc, i) => acc + i.stock, 0);
  const { isMarginHealthy, marginMultiplier } = getMarginMetrics();

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  // Audio Decoding Utilities
  const decodeBase64 = (base64: string) => {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  };

  const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> => {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
      }
    }
    return buffer;
  };

  const playLolaVoice = async (text: string) => {
    if (!isTtsEnabled) return;
    setIsSpeaking(true);
    try {
      const base64Audio = await generateLolaSpeech(text);
      if (base64Audio) {
        if (!audioContextRef.current) {
          audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const ctx = audioContextRef.current;
        const audioBuffer = await decodeAudioData(decodeBase64(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.onended = () => setIsSpeaking(false);
        source.start();
      } else {
        setIsSpeaking(false);
      }
    } catch (e) {
      console.error("Speech synthesis failed", e);
      setIsSpeaking(false);
    }
  };

  const toggleDictation = () => {
    if (isListening) {
      recognitionRef.current?.stop();
      setIsListening(false);
      return;
    }

    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert("Voice recognition is not supported in this browser.");
      return;
    }

    const recognition = new SpeechRecognition();
    recognition.continuous = false;
    recognition.interimResults = false;
    recognition.lang = 'en-US';

    recognition.onstart = () => setIsListening(true);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setInput(prev => prev + (prev ? ' ' : '') + transcript);
      setIsListening(false);
    };
    recognition.onerror = () => setIsListening(false);
    recognition.onend = () => setIsListening(false);

    recognitionRef.current = recognition;
    recognition.start();
  };

  const handleSend = async () => { 
    if (!input.trim()) return;

    const userMsg = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsLoading(true);

    try {
        const snapshot = { 
            inventory, 
            productionStats, 
            totalFinishedUnits: totalFinishedStock,
            isMarginHealthy,
            marginMultiplier,
            revenue: getTotalRevenue()
        };

        const response = await chatWithLola(userMsg, snapshot);
        const assistantMsg: Msg = { role: 'assistant', text: response.text };

        if (userMsg.toLowerCase().includes('wholesale') || userMsg.toLowerCase().includes('strategy')) {
            if (marginMultiplier < 2.2 || totalFinishedStock < 50) {
                assistantMsg.isAuditPrompt = true;
            } else {
                assistantMsg.isSlotSelector = true;
            }
        }

        setMessages(prev => [...prev, assistantMsg]);
        if (isTtsEnabled) {
          playLolaVoice(response.text);
        }
    } catch (error) {
        setMessages(prev => [...prev, { role: 'assistant', text: "Connection error." }]);
    } finally {
        setIsLoading(false);
    }
  };

  const handleSelectSlot = (time: string, type: string = 'Wholesale Strategy') => {
      const confirmText = `Confirmed for ${time}.`;
      addAppointment({
          clientName: 'Wholesale Lead',
          email: 'lead@artisanflow.ai',
          date: '2025-12-16',
          time,
          type: type as any,
          status: 'Confirmed'
      });
      setMessages(prev => [...prev, { 
          role: 'assistant', 
          text: confirmText 
      }]);
      if (isTtsEnabled) playLolaVoice(confirmText);
  };

  if (!isOpen) { 
    return ( 
      <button 
        onClick={() => setIsOpen(true)} 
        className="fixed bottom-6 right-6 w-10 h-10 bg-[#6A2C91] text-white rounded-full flex items-center justify-center shadow-lg hover:bg-white transition-colors z-50 animate-float"
      >
         <MessageSquare size={18} />
         <div className="absolute -top-1 -right-1 w-3 h-3 bg-[#C5A059] rounded-full border border-white animate-pulse"></div>
      </button> 
    ); 
  }

  return (
    <div className="fixed bottom-6 right-6 w-56 h-[240px] max-h-[calc(100vh-64px)] bg-white border border-stone-200 rounded-2xl shadow-2xl flex flex-col overflow-hidden z-50 animate-in slide-in-from-bottom-10">
      <div className="bg-[#6A2C91] p-2 flex justify-between items-center text-white relative">
        <div className="absolute top-2.5 left-2 flex items-center justify-center">
            <div className={`w-1.5 h-1.5 rounded-full shadow-[0_0_4px_rgba(16,185,129,0.8)] ${isSpeaking ? 'bg-amber-400 animate-ping' : 'bg-emerald-500 animate-pulse'}`}></div>
        </div>

        <div className="flex items-center gap-1.5 pl-2">
            <div className="p-1 bg-white/10 rounded-md">
                <Database size={10} className="text-[#C5A059]" />
            </div>
            <h3 className="font-black text-[10px] tracking-tight flex items-center gap-1 uppercase italic">
                Lola <Sparkles size={8} className="text-[#C5A059]" />
            </h3>
        </div>

        <div className="flex items-center gap-1">
            <button 
                onClick={() => setIsTtsEnabled(!isTtsEnabled)} 
                className={`p-1 rounded-full transition-colors ${isTtsEnabled ? 'bg-white/20 text-white' : 'text-white/40 hover:text-white'}`}
                title={isTtsEnabled ? "Disable Voice" : "Enable Voice Output"}
            >
                {isTtsEnabled ? <Volume2 size={12} /> : <VolumeX size={12} />}
            </button>
            <button onClick={() => setIsOpen(false)} className="p-1 hover:bg-white/10 rounded-full transition-colors">
                <Minimize2 size={12} />
            </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-2 space-y-2 bg-stone-50/50 scrollbar-hide">
        {messages.map((msg, idx) => (
          <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[90%] p-2 rounded-xl text-[10px] shadow-sm leading-tight group relative ${
              msg.role === 'user' 
                ? 'bg-[#6A2C91] text-white rounded-br-none' 
                : 'bg-white text-gray-800 rounded-bl-none border border-stone-100'
            }`}>
              {msg.text}
              {msg.role === 'assistant' && (
                <button 
                    onClick={() => playLolaVoice(msg.text)} 
                    className="absolute -right-5 top-1 opacity-0 group-hover:opacity-100 transition-opacity text-stone-300 hover:text-[#6A2C91]"
                >
                    <Volume2 size={10} />
                </button>
              )}

              {msg.isAuditPrompt && (
                <div className="mt-2 p-1.5 bg-amber-50 border border-amber-200 rounded-lg space-y-1">
                   <p className="text-[8px] font-black text-amber-800 flex items-center gap-1 uppercase tracking-tight">
                       <Factory size={10} /> CAPACITY ALERT
                   </p>
                   <button onClick={() => handleSelectSlot('10:00 AM', 'Manufacturing Audit')} className="w-full bg-[#C5A059] text-white py-1 rounded-md text-[7px] font-black uppercase tracking-widest shadow-sm hover:bg-[#b08e4d]">Schedule Audit</button>
                </div>
              )}

              {msg.isSlotSelector && (
                  <div className="mt-2 space-y-1">
                      <p className="text-[7px] font-black text-emerald-600 uppercase tracking-widest mb-1 ml-1">Available:</p>
                      <div className="grid grid-cols-2 gap-1">
                        {['09:00 AM', '02:00 PM'].map(slot => (
                            <button key={slot} onClick={() => handleSelectSlot(slot)} className="bg-purple-50 text-[#6A2C91] border border-purple-100 py-1 rounded-md text-[7px] font-black hover:bg-[#6A2C91] hover:text-white flex items-center justify-center gap-1">
                                <Calendar size={8} /> {slot}
                            </button>
                        ))}
                      </div>
                  </div>
              )}
            </div>
          </div>
        ))}
        {isLoading && (
            <div className="flex justify-start">
                <div className="bg-stone-200/50 p-2 rounded-xl animate-pulse flex items-center gap-2">
                    <div className="flex gap-0.5">
                        <div className="w-1 h-1 bg-stone-400 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
                        <div className="w-1 h-1 bg-stone-400 rounded-full animate-bounce" style={{ animationDelay: '200ms' }}></div>
                        <div className="w-1 h-1 bg-stone-400 rounded-full animate-bounce" style={{ animationDelay: '400ms' }}></div>
                    </div>
                    <span className="text-[8px] font-black text-stone-400 uppercase tracking-widest">Querying...</span>
                </div>
            </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <div className="p-2 bg-white border-t border-stone-100">
        <div className="flex items-center gap-1 bg-stone-100 rounded-lg px-2 py-0.5 border border-stone-200 focus-within:border-[#6A2C91] transition-all">
          <input 
            type="text" 
            value={input} 
            onChange={(e) => setInput(e.target.value)} 
            onKeyDown={(e) => e.key === 'Enter' && handleSend()} 
            placeholder={isListening ? "Listening..." : "Ask Lola..."} 
            className="flex-1 bg-transparent py-1.5 text-gray-900 text-[10px] outline-none placeholder:text-stone-400 font-medium" 
          />
          <button 
            onClick={toggleDictation}
            className={`p-1 transition-colors ${isListening ? 'text-red-500 animate-pulse' : 'text-stone-400 hover:text-[#6A2C91]'}`}
            title="Voice Input"
          >
            {isListening ? <Mic size={14} /> : <Mic size={14} />}
          </button>
          <button 
            onClick={handleSend} 
            disabled={isLoading || !input.trim()} 
            className="p-1 text-[#6A2C91] hover:scale-110 transition-all disabled:opacity-30"
          >
            <Send size={14} />
          </button>
        </div>
      </div>
    </div>
  ); 
};

