/**
 * Lola Text-to-Speech - High-Fidelity Audio Synthesis
 * FIXED: 500 Internal Error handling by cleaning input and simplifying the prompt
 */
export const generateLolaSpeech = async (text: string) => {
  if (!text) return null;

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // Clean text for TTS engine: remove markdown patterns which can cause 500 errors or poor speech synthesis
    const cleanText = text
      .replace(/\*\*/g, '') // Remove bold markdown
      .replace(/\*/g, '')   // Remove italic markdown
      .replace(/#/g, '')    // Remove header markdown
      .replace(/\[([^\]]+)\]\([^\)]+\)/g, '$1') // Convert markdown links to plain text
      .replace(/`/g, '')    // Remove code ticks
      .replace(/\n/g, ' ')  // Convert newlines to spaces for smoother speech
      .trim();

    // Limit text length to prevent internal errors on extremely long sequences
    // Most experimental TTS endpoints have a token/length budget
    const ttsPayload = cleanText.length > 400 ? cleanText.substring(0, 397) + "..." : cleanText;

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: ttsPayload }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Puck' }, // Puck is confirmed high-stability for this model
          },
        },
      },
    });

    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  } catch (error) {
    console.error("Lola TTS Error:", error);
    return null;
  }
};

