import React, { useState, useRef, useEffect } from 'react';
import { MessageSquare, Send, Minimize2, Sparkles, Calendar, Factory, Database, Mic, MicOff, Volume2, VolumeX, Loader2, CheckCircle2 } from 'lucide-react';
import { useArtisanData } from './DataContext';
import { chatWithLola, generateLolaSpeech } from '../services/geminiService';

type Msg = { 
  role: 'user' | 'assistant', 
  text: string, 
  isSlotSelector?: boolean,
  isAuditPrompt?: boolean
};

/**
 * Lola AI Assistant - Compact Synaptic Architecture with Voice Accessibility ✅
 */

export const AIAssistant: React.FC = () => { 
  const { businessProfile, addAppointment, inventory, productionStats, getTotalRevenue, getMarginMetrics } = useArtisanData();
  const [isOpen, setIsOpen] = useState(false); 
  const [messages, setMessages] = useState<Msg[]>([ 
    { role: 'assistant', text: `Greetings! Lola online. Systems optimized. Check-in complete. ✅` } 
  ]); 
  const [input, setInput] = useState(''); 
  const [isLoading, setIsLoading] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isTtsEnabled, setIsTtsEnabled] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const recognitionRef = useRef<any>(null);
  const currentAudioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  const totalFinishedStock = inventory.filter(i => i.type === 'finished').reduce((acc, i) => acc + i.stock, 0);
  const { isMarginHealthy, marginMultiplier } = getMarginMetrics();

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  // Cleanup audio on unmount
  useEffect(() => {
    return () => {
        currentAudioSourceRef.current?.stop();
        audioContextRef.current?.close();
    };
  }, []);

  const decodeBase64 = (base64: string) => {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  };

  const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> => {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
      }
    }
    return buffer;
  };

  const playLolaVoice = async (text: string) => {
    if (!isTtsEnabled) return;

    // Stop any current speaking
    if (currentAudioSourceRef.current) {
        currentAudioSourceRef.current.stop();
    }

    setIsSpeaking(true);
    try {
      const base64Audio = await generateLolaSpeech(text);
      if (base64Audio) {
        if (!audioContextRef.current || audioContextRef.current.state === 'closed') {
          audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const ctx = audioContextRef.current;

        // Resume if suspended (common browser policy)
        if (ctx.state === 'suspended') await ctx.resume();

        const audioBuffer = await decodeAudioData(decodeBase64(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.onended = () => setIsSpeaking(false);
        currentAudioSourceRef.current = source;
        source.start(0);
      } else {
        setIsSpeaking(false);
      }
    } catch (e) {
      console.error("Speech synthesis failed", e);
      setIsSpeaking(false);
    }
  };

  const toggleDictation = () => {
    if (isListening) {
      recognitionRef.current?.stop();
      setIsListening(false);
      return;
    }

    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert("Voice recognition is not supported.");
      return;
    }

    const recognition = new SpeechRecognition();
    recognition.continuous = false;
    recognition.interimResults = false;
    recognition.lang = 'en-US';

    recognition.onstart = () => setIsListening(true);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setInput(prev => prev + (prev ? ' ' : '') + transcript);
      setIsListening(false);
    };
    recognition.onerror = () => setIsListening(false);
    recognition.onend = () => setIsListening(false);

    recognitionRef.current = recognition;
    recognition.start();
  };

  const handleSend = async () => { 
    if (!input.trim()) return;

    const userMsg = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsLoading(true);

    try {
        const snapshot = { 
            inventory, 
            productionStats, 
            totalFinishedUnits: totalFinishedStock,
            isMarginHealthy,
            marginMultiplier,
            revenue: getTotalRevenue()
        };

        const response = await chatWithLola(userMsg, snapshot);
        const assistantMsg: Msg = { role: 'assistant', text: response.text };

        if (userMsg.toLowerCase().includes('wholesale') || userMsg.toLowerCase().includes('strategy')) {
            if (marginMultiplier < 2.2 || totalFinishedStock < 50) {
                assistantMsg.isAuditPrompt = true;
            } else {
                assistantMsg.isSlotSelector = true;
            }
        }

        setMessages(prev => [...prev, assistantMsg]);
        if (isTtsEnabled) {
          playLolaVoice(response.text);
        }
    } catch (error) {
        setMessages(prev => [...prev, { role: 'assistant', text: "Node communication error." }]);
    } finally {
        setIsLoading(false);
    }
  };

  const handleSelectSlot = (time: string, type: string = 'Wholesale Strategy') => {
      const confirmText = `Confirmed for ${time}.`;
      addAppointment({
          clientName: 'Wholesale Lead',
          email: 'lead@artisanflow.ai',
          date: '2025-12-16',
          time,
          type: type as any,
          status: 'Confirmed'
      });
      setMessages(prev => [...prev, { 
          role: 'assistant', 
          text: confirmText 
      }]);
      if (isTtsEnabled) playLolaVoice(confirmText);
  };

  if (!isOpen) { 
    return ( 
      <button 
        onClick={() => setIsOpen(true)} 
        className="fixed bottom-6 right-6 w-10 h-10 bg-[#6A2C91] text-white rounded-full flex items-center justify-center shadow-lg hover:bg-white transition-colors z-50 animate-float"
      >
         <MessageSquare size={18} />
         <div className="absolute -top-1 -right-1 w-3 h-3 bg-[#C5A059] rounded-full border border-white animate-pulse"></div>
      </button> 
    ); 
  }

  return (
    <div className="fixed bottom-6 right-6 w-56 h-[260px] max-h-[calc(100vh-64px)] bg-white border border-stone-200 rounded-2xl shadow-2xl flex flex-col overflow-hidden z-50 animate-in slide-in-from-bottom-10">
      <div className="bg-[#6A2C91] p-2 flex justify-between items-center text-white relative">
        <div className="absolute top-2.5 left-2 flex items-center justify-center">
            <div className={`w-1.5 h-1.5 rounded-full shadow-[0_0_4px_rgba(16,185,129,0.8)] ${isSpeaking ? 'bg-amber-400 animate-ping' : 'bg-emerald-500 animate-pulse'}`}></div>
        </div>

        <div className="flex items-center gap-1.5 pl-2">
            <div className="p-1 bg-white/10 rounded-md">
                <Database size={10} className="text-[#C5A059]" />
            </div>
