              {msg.isSlotSelector && (
                  <div className="mt-2.5 space-y-1.5">
                      <p className="text-[7px] font-black text-emerald-600 uppercase tracking-widest mb-1 ml-1">Available:</p>
                      <div className="grid grid-cols-2 gap-1.5">
                        {['09:00 AM', '02:00 PM'].map(slot => (
                            <button key={slot} onClick={() => handleSelectSlot(slot)} className="bg-purple-50 text-[#6A2C91] border border-purple-100 py-1.5 rounded-md text-[7px] font-black hover:bg-[#6A2C91] hover:text-white flex items-center justify-center gap-1">
                                <Calendar size={9} /> {slot}
                            </button>
                        ))}
                      </div>
                  </div>
              )}
            </div>
          </div>
        ))}
        {isLoading && (
            <div className="flex justify-start">
                <div className="bg-stone-200/50 p-2 rounded-xl animate-pulse flex items-center gap-2">
                    <div className="flex gap-0.5">
                        <div className="w-1 h-1 bg-stone-400 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
