            onKeyDown={(e) => e.key === 'Enter' && handleSend()} 
            placeholder={isListening ? "Listening..." : "Ask Lola..."} 
            className="flex-1 bg-transparent py-1.5 text-gray-900 text-[11px] outline-none placeholder:text-stone-400 font-medium" 
