/**
 * Lola AI Architect - High Velocity Node
 */
export const chatWithLola = async (message: string, context?: any) => { 
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const systemPrompt = `
      You are Lola, a world-class Senior AI Architect for the Artisan Flow platform.
      You have real-time read access to the manufacturing database.

      CURRENT MANUFACTURING SNAPSHOT:
      ${JSON.stringify(context || {}, null, 2)}

      LOGIC PROTOCOLS:
      1. INVENTORY AWARENESS: When a user asks about product availability, stock, or SKUs, you MUST reference the 'inventory' array.
      2. WHOLESALE GATEKEEPER: Check 'isMarginHealthy' and 'marginMultiplier'.
      3. TONE: Authoritative, data-driven, concise, yet artisanal. Brand color: #6A2C91.
      4. FORMATTING: NEVER use asterisks (*) for lists, emphasis, or any other purpose. Use hyphens (-) for all bullet points. Use plain text only. No markdown headers.
      5. SPEED: Respond immediately with zero hesitation. Keep answers under 3 sentences unless complex data is requested.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview', // Flash provides near-instant response initialization
      contents: message,
      config: { systemInstruction: systemPrompt },
    });

    return { 
      text: response.text || "I'm analyzing the factory floor data.", 
      isError: false 
    }; 
  } catch (error) {
    return { text: "Factory connection interrupted.", isError: true };
  }
};

/**
 * Lola Text-to-Speech - High-Fidelity Audio Synthesis
 * FIXED: Optimized for long-form stability and punctuation handling to prevent audio cutoff.
 */
export const generateLolaSpeech = async (text: string) => {
  if (!text) return null;

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // Aggressive cleaning to ensure the TTS engine parses every character without interruption
    const cleanText = text
      .replace(/\*/g, '-') // Final fallback check for asterisks
      .replace(/#/g, '')
      .replace(/\[([^\]]+)\]\([^\)]+\)/g, '$1')
      .replace(/`/g, '')
      .replace(/\n/g, '. ') // Ensure newlines have a pause for audio stability
      .trim();

    // Experimental models prefer chunks around 500 chars for perfect audio completion
    const ttsPayload = cleanText.length > 500 ? cleanText.substring(0, 497) + "..." : cleanText;

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: ttsPayload }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Puck' }, // Puck is the most stable voice for long responses
          },
        },
      },
    });

    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  } catch (error) {
    console.error("Lola TTS Error:", error);
    return null;
  }
};

