export const MarketingCreator = () => {
    const navigate = useNavigate();
    const { addMarketingPost } = useArtisanData();
    const [isGenerating, setIsGenerating] = useState(false);
    const [topic, setTopic] = useState('');
    const [assetType, setAssetType] = useState('Product Photo');
    const [style, setStyle] = useState('Photorealistic');
    const [generatedImage, setGeneratedImage] = useState<string | null>(null);
    const [aspectRatio, setAspectRatio] = useState('1:1');

    const handleGenerate = async () => {
        if (!topic) return alert("Please enter a topic.");
        if ((window as any).aistudio) {
             const hasKey = await (window as any).aistudio.hasSelectedApiKey();
             if (!hasKey) { await (window as any).aistudio.openSelectKey(); }
        }
        setIsGenerating(true);
        setGeneratedImage(null);
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const prompt = `Generate a high-quality ${style} image for a ${assetType}. Subject: ${topic}.`;
            const response = await ai.models.generateContent({
                model: 'gemini-3-pro-image-preview',
                contents: { parts: [{ text: prompt }] },
                config: { imageConfig: { imageSize: '1K', aspectRatio: aspectRatio as any } }
            });
             if (response.candidates?.[0]?.content?.parts) {
                for (const part of response.candidates[0].content.parts) {
                    if (part.inlineData) {
                        setGeneratedImage(`data:image/png;base64,${part.inlineData.data}`);
                        break;
                    }
                }
            }
        } catch (error: any) {
            console.error("Generation failed", error);
            if (error.message && (error.message.includes('403') || error.status === 403 || error.message.includes('Requested entity was not found.'))) {
                 alert("Permission denied or API key invalid. Please select a valid paid API key.");
                 if ((window as any).aistudio) (window as any).aistudio.openSelectKey();
            } else { alert("Generation failed. Please try again."); }
        } finally { setIsGenerating(false); }
    };

    const handleSave = () => {
        if (!generatedImage) return;
        addMarketingPost({
            platform: 'Instagram', topic: topic || 'Marketing Asset',
            content: `New ${assetType}: ${topic}`,
            scheduledDate: new Date().toISOString().split('T')[0],
            status: 'Draft', type: 'Image', mediaUrl: generatedImage
        });
        navigate('/marketing/approvals');
    };

    return (
        <div className="p-6 space-y-10 animate-in fade-in pb-20 max-w-7xl mx-auto">
             <div className="w-full md:w-1/2">
                <button onClick={() => navigate('/marketing')} className="flex items-center gap-2 text-gray-400 hover:text-[#6A2C91] font-black text-xs uppercase tracking-widest mb-6">
                    <ArrowLeft size={18} /> Back to Hub
                </button>
                <div className="flex items-center gap-4 mb-8">
                    <div className="p-4 bg-white border border-stone-200 rounded-2xl text-amber-500 shadow-lg">
                        <Image size={28} />
                    </div>
                    <div>
                        <h1 className="text-4xl font-black text-gray-900 uppercase italic tracking-tighter">Marketing Creator</h1>
                        <p className="text-gray-500 font-medium">Synthesize high-fidelity visual assets with Gemini Pro Vision</p>
                    </div>
                </div>
            </div>
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                <Card title="Asset Configuration" className="border-stone-100">
                    <div className="space-y-8 mt-4">
                        <div className="w-full md:w-1/2">
                            <label className="block text-[10px] font-black text-stone-400 uppercase tracking-[0.2em] mb-3 ml-1">Manifest Type</label>
                            <Select value={assetType} onChange={(e) => setAssetType(e.target.value)} className="h-14 rounded-2xl">
