export const AdvancedContentGenerator = () => {
    const navigate = useNavigate();
    const { addMarketingPost } = useArtisanData();
    const [generating, setGenerating] = useState(false);
    const [generatedItems, setGeneratedItems] = useState<any[]>([]);
    const [topic, setTopic] = useState('');
    const [tone, setTone] = useState('Professional');
    const [platforms, setPlatforms] = useState<string[]>(['Instagram', 'Facebook']);
    const [variations, setVariations] = useState(2);

    const togglePlatform = (p: string) => {
        if (platforms.includes(p)) { setPlatforms(platforms.filter(plat => plat !== p)); } 
        else { setPlatforms([...platforms, p]); }
    };

    const handleGenerate = async () => {
        if (!topic) return alert("Please enter a topic");
        if ((window as any).aistudio) {
            const hasKey = await (window as any).aistudio.hasSelectedApiKey();
            if (!hasKey) { await (window as any).aistudio.openSelectKey(); }
        }
        setGenerating(true);
        setGeneratedItems([]);
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const results = [];
            for (const platform of platforms) {
                const prompt = `Generate ${variations} distinct, luxury-toned content variations for ${platform} about "${topic}". Tone: ${tone}. Return ONLY a JSON array of strings, where each string is a complete post.`;
                try {
                    const result = await ai.models.generateContent({
                        model: "gemini-3-flash-preview",
                        contents: prompt,
                        config: { responseMimeType: "application/json" }
                    });
                    const posts = JSON.parse(result.text || "[]");
                    posts.forEach((content: string) => {
                        results.push({ platform, content, topic });
                    });
                } catch (e: any) {
                    if (e.message && (e.message.includes('403') || e.status === 403 || e.message.includes('Requested entity was not found.'))) {
                        alert("Permission Denied or API key invalid. Please select a valid paid API key.");
                        if ((window as any).aistudio) (window as any).aistudio.openSelectKey();
                        setGenerating(false); return;
                    }
                }
            }
            setGeneratedItems(results);
        } catch (error) { console.error("Gen Error", error); } finally { setGenerating(false); }
    };

    const handleSaveAll = () => {
        generatedItems.forEach(item => {
            addMarketingPost({
                platform: item.platform as any, topic: item.topic, content: item.content,
                scheduledDate: new Date().toISOString().split('T')[0], status: 'Pending Approval', type: 'Text'
            });
        });
        alert(`Successfully synchronized ${generatedItems.length} nodes to the Approvals ledger.`);
        navigate('/marketing/approvals');
    };

    return (
        <div className="p-6 space-y-10 animate-in fade-in h-screen flex flex-col pb-20 max-w-7xl mx-auto">
            <div className="flex-none flex flex-col md:flex-row justify-between items-start gap-8">
                <div className="w-full md:w-1/2">
                    <button onClick={() => navigate('/marketing')} className="flex items-center gap-2 text-gray-400 hover:text-[#6A2C91] font-black text-xs uppercase tracking-widest mb-6">
                        <ArrowLeft size={16} /> Back to Hub
                    </button>
                    <div className="flex items-center gap-4">
                        <div className="p-4 bg-white border border-pink-100 rounded-2xl text-pink-600 shadow-lg">
                            <Sparkles size={28} />
                        </div>
                        <div>
                            <h1 className="text-4xl font-black text-gray-900 uppercase italic tracking-tighter">Batch Synthesizer</h1>
                            <p className="text-gray-500 font-medium">Multiplex cross-platform generation</p>
                        </div>
                    </div>
                </div>
                {generatedItems.length > 0 && (
                    <Button onClick={handleSaveAll} className="w-full md:w-auto bg-[#6A2C91] text-white h-14 rounded-[2rem] font-black text-xs tracking-[0.2em] px-12 shadow-2xl shadow-purple-500/20 uppercase">
                        <CheckCircle size={18} className="mr-2" /> Commit Batch ({generatedItems.length})
                    </Button>
                )}
            </div>

            <div className="flex-1 grid grid-cols-1 lg:grid-cols-3 gap-10 overflow-hidden min-h-0">
                <Card title="Protocol Parameters" className="lg:col-span-1 rounded-[3rem] border-stone-100 overflow-y-auto scrollbar-hide">
                    <div className="space-y-8 mt-4">
                        <div>
                            <label className="block text-[10px] font-black text-stone-400 uppercase tracking-[0.2em] mb-3 ml-1">Universal Topic Pivot</label>
                            <textarea className="w-full bg-stone-50 border border-stone-200 rounded-[2rem] p-8 text-sm focus:bg-white focus:border-[#6A2C91] outline-none h-40 resize-none shadow-inner font-medium text-gray-700 transition-all" placeholder="e.g. Sustainable material sourcing and manufacturing BTS..." value={topic} onChange={(e) => setTopic(e.target.value)} />
                        </div>
                        <div>
                            <label className="block text-[10px] font-black text-stone-400 uppercase tracking-[0.2em] mb-4 ml-1">Synchronized Channels</label>
                            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-1 xl:grid-cols-2 gap-3">
                                {['Instagram', 'Facebook', 'YouTube', 'Pinterest', 'LinkedIn'].map(p => (
                                    <label key={p} className={`flex items-center gap-4 cursor-pointer p-5 rounded-2xl border transition-all duration-300 ${platforms.includes(p) ? 'bg-purple-50 border-[#6A2C91] shadow-md' : 'bg-white border-stone-100 hover:bg-stone-50'}`}>
                                        <input type="checkbox" checked={platforms.includes(p)} onChange={() => togglePlatform(p)} className="hidden" />
                                        <div className={`w-5 h-5 rounded-lg border-2 flex items-center justify-center transition-all ${platforms.includes(p) ? 'bg-[#6A2C91] border-[#6A2C91]' : 'border-stone-200'}`}>
