                            </div>
                        </div>
                        <Button onClick={handleGenerate} disabled={generating} className="w-full bg-[#6A2C91] text-white h-16 rounded-[2.5rem] font-black text-xs uppercase tracking-[0.2em] shadow-2xl shadow-purple-500/20">
