      VALID ROUTES FOR TASK NAVIGATION:
      - /inventory (Stock Hub)
      - /operations/orders (Order Processing)
      - /marketing (Marketing Studio)
      - /recipes (Recipe Formulas)
      - /finance (Finance Hub)
      - /lola/todos (To-Do List)

      CURRENT MANUFACTURING SNAPSHOT:
      ${JSON.stringify(context || {}, null, 2)}

      LOGIC PROTOCOLS:
      1. INVENTORY AWARENESS: Always check inventory stock levels.
      2. TASK SUGGESTIONS: If a task needs doing (low stock, pending orders), suggest the specific route.
      3. TONE: Authoritative, data-driven, concise.
      4. FORMATTING: NEVER use asterisks (*). Use hyphens (-) for lists.
      5. RESPONSE SCHEMA: You MUST return a JSON object with:
         - text: The main response string.
         - followUpQuestions: An array of 2-3 short strings suggesting next user steps.
         - suggestedRoute: (Optional) A string route from the valid routes list if a task is recommended.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: message,
      config: { 
        systemInstruction: systemPrompt,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            text: { type: Type.STRING },
            followUpQuestions: { 
              type: Type.ARRAY,
              items: { type: Type.STRING }
            },
            suggestedRoute: { type: Type.STRING }
          },
          required: ["text", "followUpQuestions"]
        }
      },
    });

    try {
        const parsed = JSON.parse(response.text || "{}");
        return { 
          text: parsed.text || "I'm analyzing the data nodes.", 
          followUpQuestions: parsed.followUpQuestions || [],
          suggestedRoute: parsed.suggestedRoute || null,
          isError: false 
        }; 
    } catch (e) {
        return { text: response.text, isError: false, followUpQuestions: [] };
    }
  } catch (error) {
    return { text: "Factory connection interrupted.", isError: true, followUpQuestions: [] };
  }
};

/**
 * Lola Text-to-Speech - High-Fidelity Audio Synthesis
 * FIXED: Optimized for long-form stability and punctuation handling to prevent audio cutoff.
 */
export const generateLolaSpeech = async (text: string) => {
  if (!text) return null;

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const cleanText = text
      .replace(/\*/g, '-') 
      .replace(/#/g, '')
      .replace(/\[([^\]]+)\]\([^\)]+\)/g, '$1')
      .replace(/`/g, '')
      .replace(/\n/g, '. ')
      .trim();

    const ttsPayload = cleanText.length > 500 ? cleanText.substring(0, 497) + "..." : cleanText;

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: ttsPayload }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Puck' },
          },
        },
      },
    });

    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  } catch (error) {
    console.error("Lola TTS Error:", error);
    return null;
  }
};

