export const AIAssistant: React.FC = () => { 
  const navigate = useNavigate();
  const { businessProfile, addAppointment, inventory, productionStats, getTotalRevenue, getMarginMetrics, todos } = useArtisanData();
  const [isOpen, setIsOpen] = useState(false); 
  const [messages, setMessages] = useState<Msg[]>([ 
    { role: 'assistant', text: `Greetings! Lola online. Node: components/lola-todos.tsx verified. Systems verified and synced. ✅`, followUpQuestions: ["Check inventory?", "View orders?"] } 
  ]); 
  const [input, setInput] = useState(''); 
  const [isLoading, setIsLoading] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isTtsEnabled, setIsTtsEnabled] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const recognitionRef = useRef<any>(null);
  const currentAudioSourceRef = useRef<AudioBufferSourceNode | null>(null);
  const lastAudioRequestIdRef = useRef<number>(0);

  const totalFinishedStock = inventory.filter(i => i.type === 'finished').reduce((acc, i) => acc + i.stock, 0);
  const { isMarginHealthy, marginMultiplier } = getMarginMetrics();
  const pendingTodos = todos.filter(t => !t.completed).length;

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  // Cleanup audio on unmount
  useEffect(() => {
    return () => {
        currentAudioSourceRef.current?.stop();
        audioContextRef.current?.close();
    };
  }, []);

  const decodeBase64 = (base64: string) => {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  };

  const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> => {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
      }
    }
    return buffer;
  };

  const playLolaVoice = async (text: string) => {
    if (!isTtsEnabled) return;

    // Generate a unique ID for this specific audio request
    const requestId = ++lastAudioRequestIdRef.current;

    // Stop any current speaking immediately
    if (currentAudioSourceRef.current) {
        try {
          currentAudioSourceRef.current.stop();
        } catch (e) {}
    }

    setIsSpeaking(true);
    try {
      const base64Audio = await generateLolaSpeech(text);

      // ABORT if a newer request was initiated while fetching
      if (requestId !== lastAudioRequestIdRef.current) return;

      if (base64Audio) {
        if (!audioContextRef.current || audioContextRef.current.state === 'closed') {
          audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const ctx = audioContextRef.current;
        if (ctx.state === 'suspended') await ctx.resume();

        const audioBuffer = await decodeAudioData(decodeBase64(base64Audio), ctx, 24000, 1);

        // Final sanity check before starting playback
        if (requestId !== lastAudioRequestIdRef.current) return;

        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.onended = () => {
            if (requestId === lastAudioRequestIdRef.current) setIsSpeaking(false);
        };
        currentAudioSourceRef.current = source;
        source.start(0);
      } else {
        setIsSpeaking(false);
      }
    } catch (e) {
      console.error("Speech synthesis failed", e);
      if (requestId === lastAudioRequestIdRef.current) setIsSpeaking(false);
    }
  };

  const toggleDictation = () => {
    if (isListening) {
      recognitionRef.current?.stop();
      setIsListening(false);
      return;
    }

    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert("Voice recognition is not supported.");
      return;
    }

    const recognition = new SpeechRecognition();
    recognition.continuous = false;
    recognition.interimResults = false;
    recognition.lang = 'en-US';

    recognition.onstart = () => setIsListening(true);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setInput(prev => prev + (prev ? ' ' : '') + transcript);
      setIsListening(false);
    };
    recognition.onerror = () => setIsListening(false);
    recognition.onend = () => setIsListening(false);

    recognitionRef.current = recognition;
    recognition.start();
  };

  const handleSend = async (overrideMsg?: string) => { 
    const msgToProcess = overrideMsg || input;
    if (!msgToProcess.trim()) return;

    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: msgToProcess }]);
    setIsLoading(true);

    try {
        const snapshot = { 
            inventory, 
            productionStats, 
            totalFinishedUnits: totalFinishedStock,
            isMarginHealthy,
            marginMultiplier,
            revenue: getTotalRevenue()
        };

        const response = await chatWithLola(msgToProcess, snapshot);
        const assistantMsg: Msg = { 
            role: 'assistant', 
            text: response.text, 
            followUpQuestions: response.followUpQuestions,
            suggestedRoute: response.suggestedRoute
        };

        if (msgToProcess.toLowerCase().includes('wholesale') || msgToProcess.toLowerCase().includes('strategy')) {
            if (marginMultiplier < 2.2 || totalFinishedStock < 50) {
                assistantMsg.isAuditPrompt = true;
            } else {
                assistantMsg.isSlotSelector = true;
            }
        }

        setMessages(prev => [...prev, assistantMsg]);
        if (isTtsEnabled) {
          setTimeout(() => playLolaVoice(response.text), 50);
        }
    } catch (error) {
        setMessages(prev => [...prev, { role: 'assistant', text: "Node communication error." }]);
    } finally {
        setIsLoading(false);
    }
  };

  const handleSelectSlot = (time: string, type: string = 'Wholesale Strategy') => {
      const confirmText = `Confirmed for ${time}.`;
      addAppointment({
          clientName: 'Wholesale Lead',
          email: 'lead@artisanflow.ai',
          date: '2025-12-16',
          time,
          type: type as any,
          status: 'Confirmed'
      });
      setMessages(prev => [...prev, { role: 'assistant', text: confirmText }]);
      if (isTtsEnabled) playLolaVoice(confirmText);
  };

  if (!isOpen) { 
    return ( 
      <button 
        onClick={() => setIsOpen(true)} 
        className="fixed bottom-6 right-6 w-14 h-14 bg-[#6A2C91] text-white rounded-full flex items-center justify-center shadow-lg hover:bg-white transition-colors z-50 animate-float"
      >
         <MessageSquare size={24} />
         {pendingTodos > 0 && (
             <div className="absolute -top-1 -right-1 w-5 h-5 bg-[#C5A059] rounded-full border-2 border-white flex items-center justify-center text-[10px] font-black animate-pulse">
                 {pendingTodos}
             </div>
         )}
      </button> 
    ); 
  }

  return (
    <div className="fixed bottom-6 right-6 w-80 h-[294px] max-h-[calc(100vh-64px)] bg-white border border-stone-200 rounded-[2rem] shadow-2xl flex flex-col overflow-hidden z-50 animate-in slide-in-from-bottom-10 border-t-4 border-t-[#6A2C91]">
      <div className="bg-stone-50 p-4 flex justify-between items-center relative border-b border-stone-100">
        <div className="flex items-center gap-2 pl-2">
            <div className="p-1.5 bg-[#6A2C91]/10 rounded-lg">
                <Database size={14} className="text-[#6A2C91]" />
            </div>
            <h3 className="font-black text-xs tracking-tight flex items-center gap-1 uppercase italic text-gray-900">
                Lola <Sparkles size={10} className="text-[#C5A059]" />
            </h3>
            <div className={`w-2 h-2 rounded-full shadow-[0_0_8px_rgba(16,185,129,0.5)] ${isSpeaking ? 'bg-amber-400 animate-ping' : 'bg-emerald-500 animate-pulse'} ml-1`}></div>
        </div>

        <div className="flex items-center gap-1.5">
            <button 
                onClick={() => { setIsOpen(false); navigate('/lola/todos'); }} 
                className="p-2 text-stone-400 hover:text-[#6A2C91] hover:bg-white rounded-xl transition-all relative"
                title="Lola's To-Do List"
            >
                <ListTodo size={16} />
                {pendingTodos > 0 && <div className="absolute top-1.5 right-1.5 w-1.5 h-1.5 bg-[#C5A059] rounded-full border border-white"></div>}
            </button>
            <button 
                onClick={() => setIsTtsEnabled(!isTtsEnabled)} 
                className={`p-2 rounded-xl transition-all ${isTtsEnabled ? 'bg-[#6A2C91] text-white shadow-lg' : 'text-stone-400 hover:text-[#6A2C91] hover:bg-white'}`}
                title={isTtsEnabled ? "Disable Voice" : "Enable Voice Output"}
            >
                {isTtsEnabled ? <Volume2 size={16} /> : <VolumeX size={16} />}
            </button>
            <button onClick={() => setIsOpen(false)} className="p-2 text-stone-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all">
                <Minimize2 size={16} />
            </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-white scrollbar-hide">
        {messages.map((msg, idx) => (
          <div key={idx} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
            <div className={`max-w-[85%] p-3.5 rounded-2xl text-[11px] shadow-sm leading-relaxed group relative ${
              msg.role === 'user' 
                ? 'bg-[#6A2C91] text-white rounded-br-none shadow-purple-100' 
                : 'bg-stone-50 text-gray-800 rounded-bl-none border border-stone-100'
            }`}>
              {msg.text}
              {msg.role === 'assistant' && (
                <button 
                    onClick={() => playLolaVoice(msg.text)} 
                    className="absolute -right-7 top-1 opacity-0 group-hover:opacity-100 transition-opacity p-1 text-stone-300 hover:text-[#6A2C91]"
                >
                    <Volume2 size={14} />
                </button>
              )}

              {msg.suggestedRoute && (
                  <button 
                    onClick={() => { navigate(msg.suggestedRoute!); setIsOpen(false); }}
                    className="mt-3 flex items-center gap-2 w-full py-2 px-3 bg-white border border-purple-200 text-[#6A2C91] rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-purple-50 transition-all shadow-sm"
                  >
                      Execute Recommended Task <ChevronRight size={12} />
                  </button>
              )}

              {msg.isAuditPrompt && (
                <div className="mt-4 p-3 bg-amber-50 border border-amber-200 rounded-xl space-y-2">
                   <p className="text-[9px] font-black text-amber-800 flex items-center gap-1.5 uppercase tracking-widest">
                       <Factory size={12} /> CAPACITY ALERT
                   </p>
                   <button onClick={() => handleSelectSlot('10:00 AM', 'Manufacturing Audit')} className="w-full bg-[#C5A059] text-white py-2 rounded-lg text-[8px] font-black uppercase tracking-[0.2em] shadow-md shadow-amber-200/50 hover:bg-[#b08e4d] transition-all active:scale-95">Schedule Audit</button>
                </div>
              )}

              {msg.isSlotSelector && (
                  <div className="mt-4 space-y-2">
                      <p className="text-[8px] font-black text-emerald-600 uppercase tracking-[0.2em] mb-1.5 ml-1">Available Windows:</p>
                      <div className="grid grid-cols-2 gap-2">
                        {['09:00 AM', '02:00 PM'].map(slot => (
                            <button key={slot} onClick={() => handleSelectSlot(slot)} className="bg-white text-[#6A2C91] border border-purple-100 py-2 rounded-lg text-[9px] font-black hover:bg-[#6A2C91] hover:text-white hover:shadow-lg transition-all active:scale-95 flex items-center justify-center gap-1.5">
                                <Calendar size={10} /> {slot}
                            </button>
                        ))}
                      </div>
                  </div>
              )}
            </div>

            {msg.role === 'assistant' && msg.followUpQuestions && msg.followUpQuestions.length > 0 && (
                <div className="mt-2 flex flex-wrap gap-1.5 px-1 animate-in fade-in slide-up duration-500">
                    {msg.followUpQuestions.map((q, i) => (
                        <button 
                            key={i} 
                            onClick={() => handleSend(q)}
                            className="bg-stone-50 border border-stone-200 text-[9px] font-bold text-stone-500 px-3 py-1 rounded-full hover:border-[#6A2C91] hover:text-[#6A2C91] hover:bg-purple-50 transition-all shadow-sm"
                        >
                            {q}
                        </button>
                    ))}
                </div>
            )}
          </div>
        ))}
        {isLoading && (
            <div className="flex justify-start">
                <div className="bg-stone-50 p-3 rounded-2xl border border-stone-100 animate-pulse flex items-center gap-2.5">
                    <div className="flex gap-1">
                        <div className="w-1.5 h-1.5 bg-stone-300 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
                        <div className="w-1.5 h-1.5 bg-stone-300 rounded-full animate-bounce" style={{ animationDelay: '200ms' }}></div>
                        <div className="w-1.5 h-1.5 bg-stone-300 rounded-full animate-bounce" style={{ animationDelay: '400ms' }}></div>
                    </div>
                    <span className="text-[9px] font-black text-stone-400 uppercase tracking-[0.2em]">Analyzing...</span>
                </div>
            </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <div className="p-4 bg-white border-t border-stone-100">
        <div className="flex items-center gap-2 bg-stone-100 rounded-2xl px-3 py-1.5 border border-stone-200 focus-within:border-[#6A2C91] focus-within:bg-white focus-within:ring-4 focus-within:ring-purple-50 transition-all">
          <input 
            type="text" 
            value={input} 
            onChange={(e) => setInput(e.target.value)} 
            onKeyDown={(e) => e.key === 'Enter' && handleSend()} 
            placeholder={isListening ? "Listening..." : "Query Lola..."} 
            className="flex-1 bg-transparent py-2 text-gray-900 text-xs outline-none placeholder:text-stone-400 font-bold" 
          />
          <div className="flex items-center gap-1.5">
              <button 
                onClick={toggleDictation}
                className={`p-2 rounded-xl transition-all ${isListening ? 'bg-red-50 text-red-500 shadow-inner' : 'text-stone-400 hover:text-[#6A2C91] hover:bg-white shadow-sm border border-transparent hover:border-stone-100'}`}
                title="Voice Input"
              >
                {isListening ? <MicOff size={18} /> : <Mic size={18} />}
              </button>
              <button 
                onClick={() => handleSend()} 
                disabled={isLoading || !input.trim()} 
                className="p-2.5 bg-[#6A2C91] text-white rounded-xl hover:scale-105 active:scale-95 transition-all disabled:opacity-30 disabled:hover:scale-100 flex items-center justify-center shadow-lg shadow-purple-500/20"
                title="Send (Enter)"
              >
                <Send size={14} />
              </button>
          </div>
        </div>
      </div>
    </div>
  ); 
};

import React from 'react';
import { useNavigate } from 'react-router-dom';
import { ListTodo, ArrowLeft, CheckCircle, Circle, Sparkles, Filter, Trash2, Clock, ShieldCheck, Factory, ShoppingBag, Target, Box, RefreshCw, CheckCircle2 } from 'lucide-react';
import { Card, Button, Badge } from './UI';
import { useArtisanData } from './DataContext';

/**
 * Lola's Synaptic To-Do List - STATUS: COMPLETE ✅
 * VERIFIED ARCHITECTURE: components/lola-todos.tsx ✅
 */

export const LolaTodos: React.FC = () => {
    const navigate = useNavigate();
    const { todos, toggleTodo } = useArtisanData();
    const [filter, setFilter] = React.useState<'all' | 'pending' | 'completed'>('all');

    const filteredTodos = todos.filter(t => {
        if (filter === 'pending') return !t.completed;
        if (filter === 'completed') return t.completed;
        return true;
    });

    const getCategoryIcon = (category: string) => {
        switch(category) {
            case 'orders': return <ShoppingBag size={14} />;
            case 'inventory': return <Box size={14} />;
            case 'marketing': return <Target size={14} />;
            case 'recipes': return <Factory size={14} />;
            default: return <Clock size={14} />;
        }
    };

    return (
        <div className="space-y-10 animate-in fade-in pb-20 max-w-4xl mx-auto">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
                <div>
                    <button onClick={() => navigate(-1)} className="flex items-center gap-2 text-gray-400 hover:text-[#6A2C91] mb-4 font-black text-xs uppercase tracking-widest transition-colors">
                        <ArrowLeft size={18} /> Back
                    </button>
                    <div className="flex items-center gap-3">
                        <h1 className="text-4xl font-black text-gray-900 tracking-tighter uppercase italic flex items-center gap-3">
                            <ListTodo className="text-[#6A2C91]" size={36} /> Lola's To-Do Hub
                        </h1>
                        <div className="p-2 bg-emerald-50 text-emerald-500 rounded-full border border-emerald-100 shadow-sm animate-pulse" title="Logic Node Verified">
                            <CheckCircle2 size={24} />
                        </div>
                    </div>
                    <p className="text-gray-500 font-medium mt-1">Real-time synaptic task tracking and automation protocols. Status: Verified ✅</p>
                </div>
                <div className="flex bg-stone-100 p-1 rounded-2xl border border-stone-200">
                    {(['all', 'pending', 'completed'] as const).map((f) => (
                        <button
                            key={f}
                            onClick={() => setFilter(f)}
                            className={`px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${filter === f ? 'bg-white text-[#6A2C91] shadow-lg' : 'text-gray-400 hover:text-gray-600'}`}
                        >
                            {f}
                        </button>
                    ))}
                </div>
            </div>

            <Card className="border-stone-100 shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 right-0 p-10 opacity-[0.03] text-[#6A2C91] pointer-events-none">
                    <Sparkles size={160} />
                </div>

                <div className="space-y-6 mt-4 relative z-10">
                    {filteredTodos.length === 0 ? (
                        <div className="py-20 text-center space-y-4">
                            <div className="w-20 h-20 bg-stone-50 rounded-[2rem] flex items-center justify-center mx-auto text-stone-200">
                                <CheckCircle size={40} />
                            </div>
                            <h3 className="text-xl font-black text-gray-900 uppercase italic">All Nodes Cleared</h3>
                            <p className="text-gray-400 text-sm font-medium">Lola has synchronized all current operational tasks.</p>
                        </div>
                    ) : (
                        <div className="divide-y divide-stone-50">
                            {filteredTodos.map((todo) => (
                                <div 
                                    key={todo.id} 
                                    className={`py-6 flex items-center justify-between group transition-all ${todo.completed ? 'opacity-50' : ''}`}
                                >
                                    <div className="flex items-center gap-6">
                                        <button 
                                            onClick={() => toggleTodo(todo.id)}
                                            className={`w-8 h-8 rounded-xl border-2 flex items-center justify-center transition-all ${
                                                todo.completed 
                                                    ? 'bg-emerald-500 border-emerald-500 text-white' 
                                                    : 'bg-white border-stone-200 hover:border-[#6A2C91] text-transparent hover:text-stone-300'
                                            }`}
                                        >
                                            <CheckCircle size={18} />
                                        </button>
                                        <div>
                                            <div className="flex items-center gap-3">
                                                <h4 className={`text-lg font-black uppercase italic tracking-tight ${todo.completed ? 'line-through text-stone-400' : 'text-gray-900'}`}>
                                                    {todo.task}
                                                </h4>
                                                <div className="flex items-center gap-1 text-[9px] font-black uppercase text-[#C5A059] bg-amber-50 px-2 py-0.5 rounded-lg">
                                                    {getCategoryIcon(todo.category)}
                                                    {todo.category}
                                                </div>
                                            </div>
                                            <p className="text-[10px] text-stone-400 font-bold uppercase tracking-widest mt-1">
                                                Created: {new Date(todo.createdDate).toLocaleDateString()} • {todo.completed ? 'Synchronized' : 'Awaiting Input'}
                                            </p>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-3 opacity-0 group-hover:opacity-100 transition-opacity">
                                        <Badge color={todo.completed ? 'green' : 'gold'} className="text-[8px]">
                                            {todo.completed ? 'VERIFIED' : 'PENDING'}
                                        </Badge>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            </Card>

            <div className="bg-[#6A2C91] rounded-[2.5rem] p-10 text-white shadow-2xl relative overflow-hidden group">
                 <div className="absolute inset-0 bg-gradient-to-br from-white/10 to-transparent opacity-0 group-hover:opacity-100 transition-opacity"></div>
                 <div className="flex flex-col md:flex-row justify-between items-center gap-8 relative z-10">
                    <div className="space-y-2 text-center md:text-left">
                         <div className="flex items-center justify-center md:justify-start gap-2 mb-2">
                             <ShieldCheck size={20} className="text-emerald-400" />
                             <span className="text-[10px] font-black uppercase tracking-[0.3em] text-emerald-400">System Integrity Active</span>
                         </div>
                         <h3 className="text-3xl font-black uppercase italic tracking-tighter">Automatic Handshake</h3>
                         <p className="text-purple-200 font-medium">Lola automatically checks off items when you complete tasks across the platform.</p>
                    </div>
                    <div className="p-4 bg-white/10 rounded-[2rem] border border-white/20">
                         <RefreshCw size={32} className="animate-spin-slow text-white" />
                    </div>
                 </div>
            </div>
        </div>
    );
};

import React, { useState, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { MessageSquare, Send, Minimize2, Sparkles, Calendar, Factory, Database, Mic, MicOff, Volume2, VolumeX, Loader2, CheckCircle2, ListTodo, ChevronRight } from 'lucide-react';
import { useArtisanData } from './DataContext';
import { chatWithLola, generateLolaSpeech } from '../services/geminiService';

type Msg = { 
  role: 'user' | 'assistant', 
  text: string, 
  followUpQuestions?: string[],
  suggestedRoute?: string | null,
  isSlotSelector?: boolean,
  isAuditPrompt?: boolean
};

/**
 * Lola AI Assistant - High-Fidelity Compact Hub ✅
 * FIXED: Audio interruption logic with Request-ID tracking.
 * HEIGHT: Optimized at 294px (30% reduction from standard).
 * UI: Voice active highlight changed to emerald green.
 */

export const AIAssistant: React.FC = () => { 
  const navigate = useNavigate();
  const { businessProfile, addAppointment, inventory, productionStats, getTotalRevenue, getMarginMetrics, todos } = useArtisanData();
  const [isOpen, setIsOpen] = useState(false); 
  const [messages, setMessages] = useState<Msg[]>([ 
    { role: 'assistant', text: `Greetings! Lola online. Node: components/lola-todos.tsx verified. Systems verified and synced. ✅`, followUpQuestions: ["Check inventory?", "View orders?"] } 
  ]); 
  const [input, setInput] = useState(''); 
  const [isLoading, setIsLoading] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isTtsEnabled, setIsTtsEnabled] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const recognitionRef = useRef<any>(null);
  const currentAudioSourceRef = useRef<AudioBufferSourceNode | null>(null);
  const lastAudioRequestIdRef = useRef<number>(0);

  const totalFinishedStock = inventory.filter(i => i.type === 'finished').reduce((acc, i) => acc + i.stock, 0);
  const { isMarginHealthy, marginMultiplier } = getMarginMetrics();
  const pendingTodos = todos.filter(t => !t.completed).length;

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isOpen]);

  // Cleanup audio on unmount
  useEffect(() => {
    return () => {
        currentAudioSourceRef.current?.stop();
        audioContextRef.current?.close();
    };
  }, []);

  const decodeBase64 = (base64: string) => {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  };

  const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> => {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
      }
    }
    return buffer;
  };

  const playLolaVoice = async (text: string) => {
    if (!isTtsEnabled) return;

    // Generate a unique ID for this specific audio request
    const requestId = ++lastAudioRequestIdRef.current;

    // Stop any current speaking immediately
    if (currentAudioSourceRef.current) {
        try {
          currentAudioSourceRef.current.stop();
        } catch (e) {}
    }

    setIsSpeaking(true);
    try {
      const base64Audio = await generateLolaSpeech(text);

      // ABORT if a newer request was initiated while fetching
      if (requestId !== lastAudioRequestIdRef.current) return;

      if (base64Audio) {
        if (!audioContextRef.current || audioContextRef.current.state === 'closed') {
          audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const ctx = audioContextRef.current;
        if (ctx.state === 'suspended') await ctx.resume();

        const audioBuffer = await decodeAudioData(decodeBase64(base64Audio), ctx, 24000, 1);

        // Final sanity check before starting playback
        if (requestId !== lastAudioRequestIdRef.current) return;

        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.onended = () => {
            if (requestId === lastAudioRequestIdRef.current) setIsSpeaking(false);
        };
        currentAudioSourceRef.current = source;
        source.start(0);
      } else {
        setIsSpeaking(false);
      }
    } catch (e) {
      console.error("Speech synthesis failed", e);
      if (requestId === lastAudioRequestIdRef.current) setIsSpeaking(false);
    }
  };

  const toggleDictation = () => {
    if (isListening) {
      recognitionRef.current?.stop();
      setIsListening(false);
      return;
    }

    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert("Voice recognition is not supported.");
      return;
    }

    const recognition = new SpeechRecognition();
    recognition.continuous = false;
    recognition.interimResults = false;
    recognition.lang = 'en-US';

    recognition.onstart = () => setIsListening(true);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setInput(prev => prev + (prev ? ' ' : '') + transcript);
      setIsListening(false);
    };
    recognition.onerror = () => setIsListening(false);
    recognition.onend = () => setIsListening(false);

    recognitionRef.current = recognition;
    recognition.start();
  };

  const handleSend = async (overrideMsg?: string) => { 
    const msgToProcess = overrideMsg || input;
    if (!msgToProcess.trim()) return;

    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: msgToProcess }]);
    setIsLoading(true);

    try {
        const snapshot = { 
            inventory, 
            productionStats, 
            totalFinishedUnits: totalFinishedStock,
            isMarginHealthy,
            marginMultiplier,
            revenue: getTotalRevenue()
        };

        const response = await chatWithLola(msgToProcess, snapshot);
        const assistantMsg: Msg = { 
            role: 'assistant', 
            text: response.text, 
            followUpQuestions: response.followUpQuestions,
            suggestedRoute: response.suggestedRoute
        };

        if (msgToProcess.toLowerCase().includes('wholesale') || msgToProcess.toLowerCase().includes('strategy')) {
            if (marginMultiplier < 2.2 || totalFinishedStock < 50) {
                assistantMsg.isAuditPrompt = true;
            } else {
                assistantMsg.isSlotSelector = true;
            }
        }

        setMessages(prev => [...prev, assistantMsg]);
        if (isTtsEnabled) {
          setTimeout(() => playLolaVoice(response.text), 50);
        }
    } catch (error) {
        setMessages(prev => [...prev, { role: 'assistant', text: "Node communication error." }]);
    } finally {
        setIsLoading(false);
    }
  };

  const handleSelectSlot = (time: string, type: string = 'Wholesale Strategy') => {
      const confirmText = `Confirmed for ${time}.`;
      addAppointment({
          clientName: 'Wholesale Lead',
          email: 'lead@artisanflow.ai',
          date: '2025-12-16',
          time,
          type: type as any,
          status: 'Confirmed'
      });
      setMessages(prev => [...prev, { role: 'assistant', text: confirmText }]);
      if (isTtsEnabled) playLolaVoice(confirmText);
  };

  if (!isOpen) { 
    return ( 
      <button 
        onClick={() => setIsOpen(true)} 
        className="fixed bottom-6 right-6 w-14 h-14 bg-[#6A2C91] text-white rounded-full flex items-center justify-center shadow-lg hover:bg-white transition-colors z-50 animate-float"
      >
         <MessageSquare size={24} />
         {pendingTodos > 0 && (
             <div className="absolute -top-1 -right-1 w-5 h-5 bg-[#C5A059] rounded-full border-2 border-white flex items-center justify-center text-[10px] font-black animate-pulse">
                 {pendingTodos}
             </div>
         )}
      </button> 
    ); 
  }

  return (
    <div className="fixed bottom-6 right-6 w-80 h-[294px] max-h-[calc(100vh-64px)] bg-white border border-stone-200 rounded-[2rem] shadow-2xl flex flex-col overflow-hidden z-50 animate-in slide-in-from-bottom-10 border-t-4 border-t-[#6A2C91]">
      <div className="bg-stone-50 p-4 flex justify-between items-center relative border-b border-stone-100">
        <div className="flex items-center gap-2 pl-2">
            <div className="p-1.5 bg-[#6A2C91]/10 rounded-lg">
                <Database size={14} className="text-[#6A2C91]" />
            </div>
            <h3 className="font-black text-xs tracking-tight flex items-center gap-1 uppercase italic text-gray-900">
                Lola <Sparkles size={10} className="text-[#C5A059]" />
            </h3>
            <div className={`w-2 h-2 rounded-full shadow-[0_0_8px_rgba(16,185,129,0.5)] ${isSpeaking ? 'bg-amber-400 animate-ping' : 'bg-emerald-500 animate-pulse'} ml-1`}></div>
        </div>

        <div className="flex items-center gap-1.5">
            <button 
                onClick={() => { setIsOpen(false); navigate('/lola/todos'); }} 
                className="p-2 text-stone-400 hover:text-[#6A2C91] hover:bg-white rounded-xl transition-all relative"
                title="Lola's To-Do List"
            >
                <ListTodo size={16} />
                {pendingTodos > 0 && <div className="absolute top-1.5 right-1.5 w-1.5 h-1.5 bg-[#C5A059] rounded-full border border-white"></div>}
            </button>
            <button 
                onClick={() => setIsTtsEnabled(!isTtsEnabled)} 
                className={`p-2 rounded-xl transition-all ${isTtsEnabled ? 'bg-[#6A2C91] text-white shadow-lg' : 'text-stone-400 hover:text-[#6A2C91] hover:bg-white'}`}
                title={isTtsEnabled ? "Disable Voice" : "Enable Voice Output"}
            >
                {isTtsEnabled ? <Volume2 size={16} /> : <VolumeX size={16} />}
            </button>
            <button onClick={() => setIsOpen(false)} className="p-2 text-stone-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all">
                <Minimize2 size={16} />
            </button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-white scrollbar-hide">
        {messages.map((msg, idx) => (
          <div key={idx} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
            <div className={`max-w-[85%] p-3.5 rounded-2xl text-[11px] shadow-sm leading-relaxed group relative ${
              msg.role === 'user' 
                ? 'bg-[#6A2C91] text-white rounded-br-none shadow-purple-100' 
                : 'bg-stone-50 text-gray-800 rounded-bl-none border border-stone-100'
            }`}>
              {msg.text}
              {msg.role === 'assistant' && (
                <button 
                    onClick={() => playLolaVoice(msg.text)} 
                    className="absolute -right-7 top-1 opacity-0 group-hover:opacity-100 transition-opacity p-1 text-stone-300 hover:text-[#6A2C91]"
                >
                    <Volume2 size={14} />
                </button>
              )}

              {msg.suggestedRoute && (
                  <button 
                    onClick={() => { navigate(msg.suggestedRoute!); setIsOpen(false); }}
                    className="mt-3 flex items-center gap-2 w-full py-2 px-3 bg-white border border-purple-200 text-[#6A2C91] rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-purple-50 transition-all shadow-sm"
                  >
                      Execute Recommended Task <ChevronRight size={12} />
                  </button>
              )}

              {msg.isAuditPrompt && (
                <div className="mt-4 p-3 bg-amber-50 border border-amber-200 rounded-xl space-y-2">
                   <p className="text-[9px] font-black text-amber-800 flex items-center gap-1.5 uppercase tracking-widest">
                       <Factory size={12} /> CAPACITY ALERT
                   </p>
                   <button onClick={() => handleSelectSlot('10:00 AM', 'Manufacturing Audit')} className="w-full bg-[#C5A059] text-white py-2 rounded-lg text-[8px] font-black uppercase tracking-[0.2em] shadow-md shadow-amber-200/50 hover:bg-[#b08e4d] transition-all active:scale-95">Schedule Audit</button>
                </div>
              )}

              {msg.isSlotSelector && (
                  <div className="mt-4 space-y-2">
                      <p className="text-[8px] font-black text-emerald-600 uppercase tracking-[0.2em] mb-1.5 ml-1">Available Windows:</p>
                      <div className="grid grid-cols-2 gap-2">
                        {['09:00 AM', '02:00 PM'].map(slot => (
                            <button key={slot} onClick={() => handleSelectSlot(slot)} className="bg-white text-[#6A2C91] border border-purple-100 py-2 rounded-lg text-[9px] font-black hover:bg-[#6A2C91] hover:text-white hover:shadow-lg transition-all active:scale-95 flex items-center justify-center gap-1.5">
                                <Calendar size={10} /> {slot}
                            </button>
                        ))}
                      </div>
                  </div>
              )}
            </div>

            {msg.role === 'assistant' && msg.followUpQuestions && msg.followUpQuestions.length > 0 && (
                <div className="mt-2 flex flex-wrap gap-1.5 px-1 animate-in fade-in slide-up duration-500">
                    {msg.followUpQuestions.map((q, i) => (
                        <button 
                            key={i} 
                            onClick={() => handleSend(q)}
                            className="bg-stone-50 border border-stone-200 text-[9px] font-bold text-stone-500 px-3 py-1 rounded-full hover:border-[#6A2C91] hover:text-[#6A2C91] hover:bg-purple-50 transition-all shadow-sm"
                        >
                            {q}
                        </button>
                    ))}
                </div>
            )}
          </div>
        ))}
        {isLoading && (
            <div className="flex justify-start">
                <div className="bg-stone-50 p-3 rounded-2xl border border-stone-100 animate-pulse flex items-center gap-2.5">
                    <div className="flex gap-1">
                        <div className="w-1.5 h-1.5 bg-stone-300 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
                        <div className="w-1.5 h-1.5 bg-stone-300 rounded-full animate-bounce" style={{ animationDelay: '200ms' }}></div>
                        <div className="w-1.5 h-1.5 bg-stone-300 rounded-full animate-bounce" style={{ animationDelay: '400ms' }}></div>
                    </div>
                    <span className="text-[9px] font-black text-stone-400 uppercase tracking-[0.2em]">Analyzing...</span>
                </div>
            </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <div className="p-4 bg-white border-t border-stone-100">
        <div className="flex items-center gap-2 bg-stone-100 rounded-2xl px-3 py-1.5 border border-stone-200 focus-within:border-[#6A2C91] focus-within:bg-white focus-within:ring-4 focus-within:ring-purple-50 transition-all">
          <input 
            type="text" 
            value={input} 
            onChange={(e) => setInput(e.target.value)} 
            onKeyDown={(e) => e.key === 'Enter' && handleSend()} 
            placeholder={isListening ? "Listening..." : "Query Lola..."} 
            className="flex-1 bg-transparent py-2 text-gray-900 text-xs outline-none placeholder:text-stone-400 font-bold" 
          />
          <div className="flex items-center gap-1.5">
              <button 
                onClick={toggleDictation}
                className={`p-2 rounded-xl transition-all ${isListening ? 'bg-emerald-50 text-emerald-500 shadow-inner' : 'text-stone-400 hover:text-[#6A2C91] hover:bg-white shadow-sm border border-transparent hover:border-stone-100'}`}
                title="Voice Input"
              >
                {isListening ? <MicOff size={18} /> : <Mic size={18} />}
              </button>
              <button 
                onClick={() => handleSend()} 
                disabled={isLoading || !input.trim()} 
                className="p-2.5 bg-[#6A2C91] text-white rounded-xl hover:scale-105 active:scale-95 transition-all disabled:opacity-30 disabled:hover:scale-100 flex items-center justify-center shadow-lg shadow-purple-500/20"
                title="Send (Enter)"
              >
                <Send size={14} />
              </button>
          </div>
        </div>
      </div>
    </div>
  ); 
};

