export type UserTier = 'Free Audit' | 'Artisan Flow Basic' | 'Margin Protection Pro';

export interface TodoItem {
  id: string;
  task: string;
  completed: boolean;
  category: 'orders' | 'inventory' | 'marketing' | 'recipes' | 'general';
  createdDate: string;
}

export interface InventoryItem {
  id: string | number;
  name: string;
  sku: string;
  stock: number;
  unit: string;
  unitCost: number;
  retailPrice?: number;
  stockValue: number;
  reorderPoint: number;
  type: 'raw' | 'finished';
  category?: string;
  img?: string;
  lowStock?: boolean;
  description?: string;
  supplier?: string;
}

export interface Order {
  id: string;
  customer: string;
  email?: string;
  date: string;
  status: 'Processing' | 'Shipped' | 'Delivered' | 'Cancelled';
  platform: string;
  items: { name: string; qty: number; price: number }[];
  total: number;
  location: string;
}

export interface ManualCustomer {
  id: string;
  name: string;
  email: string;
  location: string;
  createdDate: string;
}

export interface BusinessProfile {
  name: string;
  ownerName: string;
  email: string;
  logo?: string;
  industry: string;
  tier: UserTier;
  status: 'Active' | 'Inactive';
  brandVoice: { adjectives: string[]; restrictedWords: string[] };
  receptionistLogic: { qualificationQuestions: string[] };
}

export interface Report {
  id: string;
  title: string;
  category: string;
  type: string;
  generatedDate: string;
  headers: string[];
  data: any[];
  summaryStats: { label: string; value: string | number; color?: string }[];
