// --- VISUAL ANALYSIS NODE ---
export const VisualAnalysisNode = () => {
    const navigate = useNavigate();
    const [file, setFile] = useState<File | null>(null);
    const [preview, setPreview] = useState<string | null>(null);
    const [analysis, setAnalysis] = useState<string | null>(null);
    const [isAnalyzing, setIsAnalyzing] = useState(false);
    const [prompt, setPrompt] = useState('Analyze this artisanal product for brand alignment and visual quality.');

    const handleFileChange = (files: File[]) => {
        if (files[0]) {
            setFile(files[0]);
            const reader = new FileReader();
            reader.onloadend = () => setPreview(reader.result as string);
            reader.readAsDataURL(files[0]);
        }
    };

    const runAnalysis = async () => {
        if (!preview) return;
        setIsAnalyzing(true);
        const result = await analyzeLolaImage(preview, prompt);
        setAnalysis(result);
        setIsAnalyzing(false);
    };

    return (
        <div className="p-6 space-y-10 animate-in fade-in pb-20 max-w-7xl mx-auto">
            <div className="w-full md:w-1/2">
                <button onClick={() => navigate('/marketing')} className="flex items-center gap-2 text-gray-400 hover:text-[#6A2C91] font-black text-xs uppercase tracking-widest mb-6">
                    <ArrowLeft size={16} /> Back to Hub
                </button>
                <div className="flex items-center gap-4 mb-8">
                    <div className="p-4 bg-white border border-stone-200 rounded-2xl text-emerald-600 shadow-lg">
                        <Camera size={28} />
                    </div>
                    <div>
                        <h1 className="text-4xl font-black text-gray-900 uppercase italic tracking-tighter">Visual Analyst</h1>
                        <p className="text-gray-500 font-medium">Audit artisanal assets with Gemini 3 Pro</p>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                <Card title="Source Asset Ingestion" className="border-stone-100">
                    <div className="space-y-6">
                        <FileUploader onUpload={handleFileChange} acceptedFormats=".jpg, .jpeg, .png" label="Drop product photo for audit" />
                        {preview && (
                            <div className="space-y-6 animate-in zoom-in">
                                <div className="aspect-video rounded-3xl overflow-hidden border border-stone-100 shadow-inner">
                                    <img src={preview} className="w-full h-full object-cover" />
                                </div>
                                <div className="space-y-1">
                                    <label className="text-[10px] font-black text-stone-400 uppercase tracking-widest ml-1">Analysis Focus</label>
                                    <textarea 
                                        className="w-full bg-stone-50 border border-stone-200 rounded-2xl p-4 text-sm focus:bg-white focus:border-[#6A2C91] h-24 resize-none transition-all"
                                        value={prompt}
                                        onChange={e => setPrompt(e.target.value)}
                                    />
                                </div>
                                <Button onClick={runAnalysis} disabled={isAnalyzing} className="w-full bg-[#6A2C91] text-white h-14 rounded-2xl font-black uppercase tracking-widest">
                                    {isAnalyzing ? <Loader2 className="animate-spin" /> : 'INITIALIZE VISUAL AUDIT'}
                                </Button>
                            </div>
                        )}
                    </div>
                </Card>

                <Card title="Synaptic Analysis Report" className="border-stone-100 bg-stone-50/30">
                    {analysis ? (
                        <div className="prose prose-stone max-w-none animate-in slide-up">
                            <p className="text-gray-700 leading-relaxed font-medium whitespace-pre-wrap italic">
                                {analysis}
                            </p>
                        </div>
                    ) : (
